-- Importazione completa delle traduzioni revisionate.

-- Eseguire soltanto dopo revisione e conferma. Transazione atomica.

BEGIN;

SET LOCAL client_encoding = 'UTF8';

LOCK TABLE public.menu_category_translations, public.menu_subcategory_translations, public.menu_intro_translations, public.menu_setting_translations, public.menu_item_translations IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMP TABLE source_menu_category_translations ON COMMIT DROP AS SELECT id, nome FROM public.menu_categories WITH NO DATA;

