DO $source$
BEGIN
 IF EXISTS (SELECT 1 FROM source_menu_category_translations s LEFT JOIN public.menu_categories b ON b.id=s.id WHERE b.id IS NULL OR b.nome IS DISTINCT FROM s.nome) THEN
  RAISE EXCEPTION 'Fonte italiana non corrispondente per menu_categories: transazione annullata. Verificare ID, testi e NULL';
 END IF;
END $source$;

