DO $check$
BEGIN
 IF EXISTS (SELECT 1 FROM stage_menu_category_translations s LEFT JOIN public.menu_category_translations t USING (category_id, language_code) WHERE t.id IS NULL)
 AND NOT EXISTS (
  SELECT 1 FROM information_schema.columns
  WHERE table_schema='public' AND table_name='menu_category_translations' AND column_name='id'
    AND (is_identity='YES' OR column_default IS NOT NULL)
 ) THEN
  RAISE EXCEPTION 'La tabella menu_category_translations richiede nuovi ID ma non ha generazione automatica: nessun dato importato';
 END IF;
END $check$;

UPDATE public.menu_category_translations t SET nome=s.nome, updated_at=now() FROM stage_menu_category_translations s WHERE t.category_id=s.category_id AND t.language_code=s.language_code;

INSERT INTO public.menu_category_translations (category_id, language_code, nome) SELECT s.category_id, s.language_code, s.nome FROM stage_menu_category_translations s WHERE NOT EXISTS (SELECT 1 FROM public.menu_category_translations t WHERE t.category_id=s.category_id AND t.language_code=s.language_code)
ON CONFLICT (category_id, language_code) DO UPDATE SET nome=EXCLUDED.nome, updated_at=now();

