(11, 'uk', 'Шампанське'),
(12, 'uk', 'Італійські ігристі вина'),
(13, 'uk', 'Розливне'),
(14, 'uk', 'Пляшкове'),
(15, 'uk', 'Ром'),
(16, 'uk', 'Віскі'),
(17, 'uk', 'Граппа');

DO $check$
BEGIN
 IF EXISTS (SELECT 1 FROM stage_menu_subcategory_translations s LEFT JOIN public.menu_subcategory_translations t USING (subcategory_id, language_code) WHERE t.id IS NULL)
 AND NOT EXISTS (
  SELECT 1 FROM information_schema.columns
  WHERE table_schema='public' AND table_name='menu_subcategory_translations' AND column_name='id'
    AND (is_identity='YES' OR column_default IS NOT NULL)
 ) THEN
  RAISE EXCEPTION 'La tabella menu_subcategory_translations richiede nuovi ID ma non ha generazione automatica: nessun dato importato';
 END IF;
END $check$;

UPDATE public.menu_subcategory_translations t SET nome=s.nome, updated_at=now() FROM stage_menu_subcategory_translations s WHERE t.subcategory_id=s.subcategory_id AND t.language_code=s.language_code;

INSERT INTO public.menu_subcategory_translations (subcategory_id, language_code, nome) SELECT s.subcategory_id, s.language_code, s.nome FROM stage_menu_subcategory_translations s WHERE NOT EXISTS (SELECT 1 FROM public.menu_subcategory_translations t WHERE t.subcategory_id=s.subcategory_id AND t.language_code=s.language_code)
ON CONFLICT (subcategory_id, language_code) DO UPDATE SET nome=EXCLUDED.nome, updated_at=now();

CREATE TEMP TABLE source_menu_intro_translations ON COMMIT DROP AS SELECT id, titolo, testo FROM public.menu_intro WITH NO DATA;

INSERT INTO source_menu_intro_translations (id, titolo, testo) VALUES
(1, 'IL PESCATO DEL GIORNO', 'Ogni giorno selezioniamo con cura il miglior pescato locale, espressione autentica del nostro mare. La nostra vetrina è un invito a scegliere, lasciandovi guidare dall’eccellenza della materia prima e dalla sensibilità della nostra cucina.'),
(2, 'CRUDO & TARTARE', 'Tartare e carpacci realizzati al momento: Gamberi, Scampi, Ostriche, Ricci di mare, Tonno, Ricciola, Cernia, Dentice Rosso, Polpo.'),
(3, 'PRIMI DI MARE', 'Interpretazioni eleganti del pescato del giorno: Astice, Aragosta, Gamberi, Scampi, Ricci di mare, Granciporro, Gallinella, Scorfano, Triglia di scoglio.'),
(4, 'SECONDI DI PESCE', 'Il pescato viene proposto secondo la preparazione più adatta: alla griglia, al forno, al sale, al cartoccio, al vapore o in umido. Spigola, Orata, Dentice Rosso, Cernia, Ricciola, Rombo chiodato, Sogliola, San Pietro, Seppia.');

DO $source$
BEGIN
 IF EXISTS (SELECT 1 FROM source_menu_intro_translations s LEFT JOIN public.menu_intro b ON b.id=s.id WHERE b.id IS NULL OR b.titolo IS DISTINCT FROM s.titolo OR b.testo IS DISTINCT FROM s.testo) THEN
  RAISE EXCEPTION 'Fonte italiana non corrispondente per menu_intro: transazione annullata. Verificare ID, testi e NULL';
 END IF;
END $source$;

CREATE TEMP TABLE stage_menu_intro_translations ON COMMIT DROP AS SELECT intro_id, language_code, titolo, testo FROM public.menu_intro_translations WITH NO DATA;

INSERT INTO stage_menu_intro_translations (intro_id, language_code, titolo, testo) VALUES
(1, 'ar', 'صيد اليوم', 'نختار كل يوم بعناية أفضل ما يجود به الصيد المحلي، تعبيرًا أصيلًا عن بحرنا. تدعوكم واجهتنا إلى الاختيار، مسترشدين بتميّز المكوّنات ورهافة مطبخنا.'),
(2, 'ar', 'مأكولات بحرية نيئة وتارتار', 'تارتار وكارباتشيو يُحضّران عند الطلب: روبيان, لانغوستين, محار, قنافذ البحر, تونة, سمك السريولا, هامور, سمك الدنتكس الأحمر, أخطبوط.'),
(3, 'ar', 'الأطباق الأولى من البحر', 'تفسيرات راقية لصيد اليوم: كركند ذو مخالب, جراد البحر الشوكي, روبيان, لانغوستين, قنافذ البحر, سرطان البحر البني, سمك الغرنار الأحمر, سمك العقرب, سمك السلطان إبراهيم.'),
(4, 'ar', 'أطباق السمك الرئيسية', 'يُقدّم الصيد بالطريقة الأنسب لكل سمكة: على الشواية، في الفرن، بالملح، في ورق الطهي، على البخار أو مطهوًا في صلصة. قاروص, دنيس, سمك الدنتكس الأحمر, هامور, سمك السريولا, سمك الترس, سمك موسى, سمك القديس بطرس, حبار السيبيا.'),
(1, 'cs', 'Úlovek dne', 'Každý den pečlivě vybíráme to nejlepší z místního úlovku, autentický výraz našeho moře. Naše vitrína vás zve k výběru, při němž vás provází výjimečnost surovin a citlivost naší kuchyně.'),
(2, 'cs', 'Syrové mořské plody a tataráky', 'Tataráky a carpaccia připravované na objednávku: krevety, langustinka, ústřice, mořští ježci, tuňák, kranas velký, kanic, červená zubatice, chobotnice.'),
(3, 'cs', 'První chody s mořskými plody', 'Elegantní variace na úlovek dne: humr, langusta, krevety, langustinka, mořští ježci, krab jedlý, štítník červený, ropušnice, parmice skalní.'),
(4, 'cs', 'Hlavní rybí chody', 'Úlovek podáváme v nejvhodnější úpravě: grilovaný, pečený, v soli, v papilotě, na páře nebo dušený. mořský vlk, pražma královská, červená zubatice, kanic, kranas velký, pakambala, jazyk mořský, pilobřich, sépie.'),
(1, 'da', 'Dagens fangst', 'Hver dag udvælger vi omhyggeligt den bedste lokale fangst, et autentisk udtryk for vores hav. Vores montre indbyder jer til at vælge, guidet af råvarernes kvalitet og vores køkkens fine sans.'),
(2, 'da', 'Rå skaldyr & tatar', 'Tatar og carpaccio tilberedt på bestilling: rejer, jomfruhummer, østers, søpindsvin, tun, ravfisk, havaborre, rød tandbrasen, ottearmet blæksprutte.'),
(3, 'da', 'Første retter med havets smag', 'Elegante fortolkninger af dagens fangst: hummer, languster, rejer, jomfruhummer, søpindsvin, taskekrabbe, rød knurhane, skorpionfisk, stribet mulle.'),
(4, 'da', 'Hovedretter med fisk', 'Fangsten serveres med den tilberedning, der passer bedst: grillet, ovnbagt, i salt, i pakke, dampet eller braiseret. havbars, guldbrasen, rød tandbrasen, havaborre, ravfisk, pighvar, søtunge, sanktpetersfisk, sepia.'),
(1, 'de', 'Der Fang des Tages', 'Jeden Tag wählen wir mit Sorgfalt den besten lokalen Fang aus – ein authentischer Ausdruck unseres Meeres. Unsere Auslage lädt Sie ein, Ihre Wahl zu treffen, geleitet von der Qualität der Zutaten und dem Feingefühl unserer Küche.'),
(2, 'de', 'Rohe Meeresfrüchte & Tatar', 'Frisch auf Bestellung zubereitete Tatar- und Carpaccio-Gerichte: Garnelen, Kaisergranat, Austern, Seeigel, Thunfisch, Bernsteinmakrele, Zackenbarsch, Rote Zahnbrasse, Oktopus.'),
(3, 'de', 'Erste Gänge mit Meeresfrüchten', 'Elegante Interpretationen des Tagesfangs: Hummer, Languste, Garnelen, Kaisergranat, Seeigel, Taschenkrebs, Roter Knurrhahn, Drachenkopf, Felsen-Rotbarbe.'),
(4, 'de', 'Fischhauptgerichte', 'Der Fang wird mit der jeweils passendsten Zubereitung serviert: gegrillt, im Ofen, in Salzkruste, in der Folie, gedämpft oder geschmort. Wolfsbarsch, Goldbrasse, Rote Zahnbrasse, Zackenbarsch, Bernsteinmakrele, Steinbutt, Seezunge, Petersfisch, Sepia.'),
(1, 'el', 'Η ψαριά της ημέρας', 'Κάθε μέρα επιλέγουμε με φροντίδα την καλύτερη τοπική ψαριά, αυθεντική έκφραση της θάλασσάς μας. Η βιτρίνα μας σας προσκαλεί να διαλέξετε, με οδηγό την αριστεία της πρώτης ύλης και την ευαισθησία της κουζίνας μας.'),
(2, 'el', 'Ωμά θαλασσινά & ταρτάρ', 'Ταρτάρ και καρπάτσιο που ετοιμάζονται τη στιγμή της παραγγελίας: γαρίδες, καραβίδα, στρείδια, αχινοί, τόνος, μαγιάτικο, ροφός, κόκκινη συναγρίδα, χταπόδι.'),
(3, 'el', 'Πρώτα πιάτα της θάλασσας', 'Κομψές ερμηνείες της ψαριάς της ημέρας: αστακός με δαγκάνες, αστακός χωρίς δαγκάνες, γαρίδες, καραβίδα, αχινοί, καβούρι καφέ, καπόνι, σκορπίνα, μπαρμπούνι.'),
(4, 'el', 'Κυρίως πιάτα ψαριού', 'Η ψαριά προτείνεται με τον καταλληλότερο τρόπο παρασκευής: στη σχάρα, στον φούρνο, στο αλάτι, σε λαδόκολλα, στον ατμό ή μαγειρευτή. λαβράκι, τσιπούρα, κόκκινη συναγρίδα, ροφός, μαγιάτικο, καλκάνι, γλώσσα, χριστόψαρο, σουπιά.'),
(1, 'en', 'The catch of the day', 'Every day we carefully select the finest local catch, an authentic expression of our sea. Our display invites you to choose, guided by the excellence of the ingredients and the finesse of our cooking.'),
(2, 'en', 'Raw seafood & tartare', 'Tartare and carpaccio prepared to order: prawns, langoustine, oysters, sea urchins, tuna, amberjack, grouper, red dentex, octopus.'),
(3, 'en', 'Seafood first courses', 'Elegant interpretations of the catch of the day: lobster, spiny lobster, prawns, langoustine, sea urchins, brown crab, tub gurnard, scorpionfish, red mullet.'),
(4, 'en', 'Fish main courses', 'The catch is served using the preparation best suited to each fish: grilled, oven-baked, baked in salt, en papillote, steamed or stewed. sea bass, gilthead sea bream, red dentex, grouper, amberjack, turbot, sole, John Dory, cuttlefish.'),
(1, 'es', 'La pesca del día', 'Cada día seleccionamos con esmero lo mejor de la pesca local, expresión auténtica de nuestro mar. Nuestra vitrina invita a elegir, dejándose guiar por la excelencia de la materia prima y la sensibilidad de nuestra cocina.'),
(2, 'es', 'Marisco crudo y tartares', 'Tartares y carpaccios preparados al momento: gambas, cigala, ostras, erizos de mar, atún, pez limón, mero, dentón rojo, pulpo.'),
(3, 'es', 'Primeros platos del mar', 'Elegantes interpretaciones de la pesca del día: bogavante, langosta, gambas, cigala, erizos de mar, buey de mar, rubio, cabracho, salmonete de roca.'),
(4, 'es', 'Platos principales de pescado', 'El pescado se ofrece con la preparación más adecuada: a la parrilla, al horno, a la sal, en papillote, al vapor o guisado. lubina, dorada, dentón rojo, mero, pez limón, rodaballo, lenguado, pez de San Pedro, sepia.'),
(1, 'fi', 'Päivän saalis', 'Valitsemme joka päivä huolella parhaat paikalliset saaliit, oman meremme aidon ilmentymän. Esittelytiskimme kutsuu valitsemaan raaka-aineiden erinomaisuuden ja keittiömme hienovaraisen otteen johdattamana.'),
(2, 'fi', 'Raakoja mereneläviä ja tartareja', 'Tilauksesta valmistetut tartarit ja carpacciot: katkaravut, keisarihummeri, osterit, merisiilit, tonnikala, meripihkakala, meriahven (grouper), punainen hammasahven, mustekala.'),
(3, 'fi', 'Ensimmäiset ruokalajit meren antimista', 'Päivän saaliin elegantteja tulkintoja: hummeri, langusti, katkaravut, keisarihummeri, merisiilit, taskurapu, punakurnusimppu, skorpionikala, juovamullo.'),
(4, 'fi', 'Kalapääruoat', 'Saalis valmistetaan kalalle parhaiten sopivalla tavalla: grillattuna, uunissa, suolassa, paketissa, höyrytettynä tai haudutettuna. meribassi, kultaotsa-ahven, punainen hammasahven, meriahven (grouper), meripihkakala, piikkikampela, meriantura, pietarinkala, seepia.'),
(1, 'fr', 'La pêche du jour', 'Chaque jour, nous sélectionnons avec soin le meilleur de la pêche locale, expression authentique de notre mer. Notre vitrine vous invite à choisir, en vous laissant guider par l’excellence des produits et la sensibilité de notre cuisine.'),
(2, 'fr', 'Crus de la mer & tartares', 'Tartares et carpaccios préparés à la minute: crevettes, langoustine, huîtres, oursins, thon, sériole, mérou, denté rouge, poulpe.'),
(3, 'fr', 'Premiers plats de la mer', 'Interprétations élégantes de la pêche du jour: homard, langouste, crevettes, langoustine, oursins, tourteau, grondin perlon, rascasse, rouget de roche.'),
(4, 'fr', 'Plats principaux de poisson', 'La pêche est proposée selon la préparation la mieux adaptée à chaque poisson : grillé, au four, en croûte de sel, en papillote, à la vapeur ou en ragoût. bar, dorade royale, denté rouge, mérou, sériole, turbot, sole, saint-pierre, seiche.'),
(1, 'hu', 'A nap fogása', 'Nap mint nap gondosan válogatjuk a legjobb helyi fogást, tengerünk hiteles kifejeződését. Vitrinünk választásra hívja: az alapanyagok kiválósága és konyhánk kifinomult érzéke vezeti az élményben.'),
(2, 'hu', 'Nyers tengeri fogások és tatárok', 'Frissen, rendelésre készülő tatárok és carpacciók: garnélák, norvég homár, osztrigák, tengeri sünök, tonhal, borostyánmakréla, fűrészes sügér, vörös fogas durbincs, polip.'),
(3, 'hu', 'Tengeri első fogások', 'A nap fogásának elegáns újragondolásai: homár, languszta, garnélák, norvég homár, tengeri sünök, barna tarisznyarák, vörös morgóhal, skorpióhal, csíkos vörösmárna.'),
(4, 'hu', 'Halból készült főételek', 'A fogást a halhoz leginkább illő módon készítjük: grillezve, sütőben, sókéregben, papírban sütve, párolva vagy raguként. tengeri sügér, aranydurbincs, vörös fogas durbincs, fűrészes sügér, borostyánmakréla, rombuszhal, nyelvhal, Szent Péter hala, szépia.'),
(1, 'nl', 'De vangst van de dag', 'Elke dag selecteren we zorgvuldig de beste lokale vangst, een authentieke weerspiegeling van onze zee. Onze vitrine nodigt u uit te kiezen, geleid door de kwaliteit van de ingrediënten en de finesse van onze keuken.'),
(2, 'nl', 'Rauwe zeevruchten & tartaar', 'Tartaar en carpaccio, vers op bestelling bereid: garnalen, langoustine, oesters, zee-egels, tonijn, geelstaartvis, tandbaars, rode tandbrasem, octopus.'),
(3, 'nl', 'Eerste gangen uit de zee', 'Elegante interpretaties van de dagvangst: kreeft, langoest, garnalen, langoustine, zee-egels, Noordzeekrab, rode poon, schorpioenvis, gestreepte zeebarbeel.'),
(4, 'nl', 'Hoofdgerechten met vis', 'De vangst wordt bereid op de manier die het best bij de vis past: gegrild, uit de oven, in zoutkorst, en papillote, gestoomd of gestoofd. zeebaars, goudbrasem, rode tandbrasem, tandbaars, geelstaartvis, tarbot, tong, zonnevis, zeekat.'),
(1, 'no', 'Dagens fangst', 'Hver dag velger vi med omhu den beste lokale fangsten, et ekte uttrykk for havet vårt. Vår disk inviterer dere til å velge, veiledet av råvarenes kvalitet og kjøkkenets fine sans.'),
(2, 'no', 'Rå sjømat & tartar', 'Tartar og carpaccio tilberedt på bestilling: reker, sjøkreps, østers, kråkeboller, tunfisk, ravfisk, havabbor, rød tannbrasme, blekksprut.'),
(3, 'no', 'Første retter med havets smaker', 'Elegante tolkninger av dagens fangst: hummer, languster, reker, sjøkreps, kråkeboller, taskekrabbe, rødknurr, skorpionfisk, stripet mulle.'),
(4, 'no', 'Hovedretter med fisk', 'Fangsten serveres med den tilberedningen som passer best: grillet, ovnsbakt, i salt, i pakke, dampet eller braisert. havabbor (seabass), gullbrasme, rød tannbrasme, havabbor, ravfisk, piggvar, sjøtunge, sanktpetersfisk, sepia.'),
(1, 'pl', 'Połów dnia', 'Każdego dnia starannie wybieramy najlepszy lokalny połów, będący autentycznym wyrazem naszego morza. Nasza witryna zaprasza do wyboru, w którym prowadzą Państwa doskonałość składników i wyczucie naszej kuchni.'),
(2, 'pl', 'Surowe owoce morza i tatary', 'Tatary i carpaccia przygotowywane na zamówienie: krewetki, langustynka, ostrygi, jeżowce, tuńczyk, seriola, granik, denteks czerwony, ośmiornica.'),
(3, 'pl', 'Pierwsze dania z owocami morza', 'Eleganckie interpretacje połowu dnia: homar, langusta, krewetki, langustynka, jeżowce, krab kieszeniec, kurek czerwony, skorpena, barwena skalna.'),
(4, 'pl', 'Dania główne z ryb', 'Połów podajemy w sposób najlepiej dobrany do danej ryby: z grilla, z pieca, w soli, w papilotach, na parze lub duszony. labraks, dorada, denteks czerwony, granik, seriola, turbot, sola, piotrosz, mątwa.'),
(1, 'pt', 'A pesca do dia', 'Todos os dias selecionamos com cuidado o melhor peixe local, expressão autêntica do nosso mar. A nossa montra convida a escolher, deixando-se guiar pela excelência dos ingredientes e pela sensibilidade da nossa cozinha.'),
(2, 'pt', 'Marisco cru e tártaros', 'Tártaros e carpaccios preparados no momento: camarões, lagostim, ostras, ouriços-do-mar, atum, lírio, garoupa, dentão-vermelho, polvo.'),
(3, 'pt', 'Primeiros pratos do mar', 'Interpretações elegantes da pesca do dia: lavagante, lagosta, camarões, lagostim, ouriços-do-mar, sapateira, cabra-vermelha, rascasso, salmonete de rocha.'),
(4, 'pt', 'Pratos principais de peixe', 'O peixe é servido com a preparação mais adequada: grelhado, no forno, ao sal, em papillote, ao vapor ou estufado. robalo, dourada, dentão-vermelho, garoupa, lírio, pregado, linguado, peixe-galo, choco.'),
(1, 'ro', 'Captura zilei', 'În fiecare zi selectăm cu grijă cea mai bună captură locală, expresie autentică a mării noastre. Vitrina noastră vă invită să alegeți, lăsându-vă îndrumați de calitatea excepțională a ingredientelor și de sensibilitatea bucătăriei noastre.'),
(2, 'ro', 'Fructe de mare crude și tartar', 'Tartar și carpaccio preparate pe loc: creveți, langustină, stridii, arici de mare, ton, seriolă, biban de stâncă, dentex roșu, caracatiță.'),
(3, 'ro', 'Feluri întâi cu fructe de mare', 'Interpretări elegante ale capturii zilei: homar, langustă, creveți, langustină, arici de mare, crab brun, rândunică de mare, scorpie de mare, barbun de stâncă.'),
(4, 'ro', 'Feluri principale cu pește', 'Peștele este propus în prepararea cea mai potrivită: la grătar, la cuptor, în sare, în papillote, la abur sau înăbușit. biban de mare, doradă, dentex roșu, biban de stâncă, seriolă, calcan, limbă-de-mare, pește Sfântul Petru, sepie.'),
(1, 'ru', 'Улов дня', 'Каждый день мы тщательно отбираем лучший местный улов — подлинное воплощение нашего моря. Наша витрина приглашает вас сделать выбор, доверившись превосходному качеству продуктов и тонкому чувству нашей кухни.'),
(2, 'ru', 'Сырые морепродукты и тартары', 'Тартары и карпаччо, приготовленные на заказ: креветки, лангустин, устрицы, морские ежи, тунец, сериола, групер, красный зубан, осьминог.'),
(3, 'ru', 'Первые блюда с дарами моря', 'Изысканные интерпретации улова дня: омар, лангуст, креветки, лангустин, морские ежи, съедобный краб, морской петух, скорпена, барабулька.'),
(4, 'ru', 'Основные блюда из рыбы', 'Улов предлагаем в наиболее подходящем приготовлении: на гриле, в печи, в соли, в пергаменте, на пару или тушёным. сибас, дорада, красный зубан, групер, сериола, тюрбо, морской язык, солнечник, каракатица.'),
(1, 'sv', 'Dagens fångst', 'Varje dag väljer vi omsorgsfullt ut det bästa av den lokala fångsten, ett äkta uttryck för vårt hav. Vår monter bjuder in er att välja, med råvarornas kvalitet och vårt köks finess som vägledning.'),
(2, 'sv', 'Råa skaldjur & tartar', 'Tartar och carpaccio som tillagas på beställning: räkor, havskräfta, ostron, sjöborrar, tonfisk, bärnstensmakrill, havsabborre, röd tandbraxen, åttaarmad bläckfisk.'),
(3, 'sv', 'Första rätter med havets smaker', 'Eleganta tolkningar av dagens fångst: hummer, langust, räkor, havskräfta, sjöborrar, krabbtaska, röd knorrhane, skorpionfisk, strimmig mullus.'),
(4, 'sv', 'Huvudrätter med fisk', 'Fångsten serveras med den tillagning som passar bäst: grillad, ugnsbakad, i salt, i paket, ångad eller bräserad. havsabborre (seabass), guldsparid, röd tandbraxen, havsabborre, bärnstensmakrill, piggvar, sjötunga, Sanktpersfisk, sepia.'),
(1, 'tr', 'Günün balıkları', 'Her gün denizimizin özgün ifadesi olan en iyi yerel avı özenle seçiyoruz. Vitrinimiz, malzemenin üstün kalitesi ve mutfağımızın incelikli yaklaşımı eşliğinde sizi seçiminizi yapmaya davet ediyor.'),
(2, 'tr', 'Çiğ deniz ürünleri ve tartar', 'Sipariş üzerine hazırlanan tartar ve carpaccio: karides, Norveç ıstakozu, istiridye, deniz kestaneleri, ton balığı, akya, orfoz, kırmızı sinarit, ahtapot.'),
(3, 'tr', 'Deniz ürünlü ilk yemekler', 'Günün balıklarının zarif yorumları: kıskaçlı ıstakoz, dikenli ıstakoz, karides, Norveç ıstakozu, deniz kestaneleri, kahverengi yengeç, kırlangıç balığı, iskorpit, tekir.'),
(4, 'tr', 'Balık ana yemekleri', 'Balıklar en uygun yöntemle hazırlanır: ızgarada, fırında, tuzda, kâğıtta, buharda veya yahni olarak. levrek, çipura, kırmızı sinarit, orfoz, akya, kalkan, dil balığı, dülger balığı, mürekkep balığı.'),
(1, 'uk', 'Улов дня', 'Щодня ми ретельно обираємо найкращий місцевий улов — справжнє втілення нашого моря. Наша вітрина запрошує вас зробити вибір, покладаючись на виняткову якість продуктів і тонке відчуття нашої кухні.'),
(2, 'uk', 'Сирі морепродукти й тартари', 'Тартари й карпачо, приготовані на замовлення: креветки, лангустина, устриці, морські їжаки, тунець, серіола, групер, червоний дентекс, восьминіг.'),
(3, 'uk', 'Перші страви з дарами моря', 'Вишукані інтерпретації улову дня: омар, лангуст, креветки, лангустина, морські їжаки, їстівний краб, морський півень, скорпена, барабулька.'),
(4, 'uk', 'Основні страви з риби', 'Улов пропонуємо у найвідповіднішому приготуванні: на грилі, у печі, у солі, у пергаменті, на парі або тушкованим. сібас, дорада, червоний дентекс, групер, серіола, калкан, морський язик, сонцевик, каракатиця.');

DO $check$
BEGIN
 IF EXISTS (SELECT 1 FROM stage_menu_intro_translations s LEFT JOIN public.menu_intro_translations t USING (intro_id, language_code) WHERE t.id IS NULL)
 AND NOT EXISTS (
  SELECT 1 FROM information_schema.columns
  WHERE table_schema='public' AND table_name='menu_intro_translations' AND column_name='id'
    AND (is_identity='YES' OR column_default IS NOT NULL)
 ) THEN
  RAISE EXCEPTION 'La tabella menu_intro_translations richiede nuovi ID ma non ha generazione automatica: nessun dato importato';
 END IF;
END $check$;

UPDATE public.menu_intro_translations t SET titolo=s.titolo, testo=s.testo, updated_at=now() FROM stage_menu_intro_translations s WHERE t.intro_id=s.intro_id AND t.language_code=s.language_code;

INSERT INTO public.menu_intro_translations (intro_id, language_code, titolo, testo) SELECT s.intro_id, s.language_code, s.titolo, s.testo FROM stage_menu_intro_translations s WHERE NOT EXISTS (SELECT 1 FROM public.menu_intro_translations t WHERE t.intro_id=s.intro_id AND t.language_code=s.language_code)
ON CONFLICT (intro_id, language_code) DO UPDATE SET titolo=EXCLUDED.titolo, testo=EXCLUDED.testo, updated_at=now();

