DO $source$
BEGIN
 IF EXISTS (SELECT 1 FROM source_menu_setting_translations s LEFT JOIN public.menu_settings b ON b.id=s.id WHERE b.id IS NULL OR b.valore IS DISTINCT FROM s.valore) THEN
  RAISE EXCEPTION 'Fonte italiana non corrispondente per menu_settings: transazione annullata. Verificare ID, testi e NULL';
 END IF;
END $source$;

