DO $check$
BEGIN
 IF EXISTS (SELECT 1 FROM stage_menu_setting_translations s LEFT JOIN public.menu_setting_translations t USING (setting_id, language_code) WHERE t.id IS NULL)
 AND NOT EXISTS (
  SELECT 1 FROM information_schema.columns
  WHERE table_schema='public' AND table_name='menu_setting_translations' AND column_name='id'
    AND (is_identity='YES' OR column_default IS NOT NULL)
 ) THEN
  RAISE EXCEPTION 'La tabella menu_setting_translations richiede nuovi ID ma non ha generazione automatica: nessun dato importato';
 END IF;
END $check$;

UPDATE public.menu_setting_translations t SET valore=s.valore, updated_at=now() FROM stage_menu_setting_translations s WHERE t.setting_id=s.setting_id AND t.language_code=s.language_code;

INSERT INTO public.menu_setting_translations (setting_id, language_code, valore) SELECT s.setting_id, s.language_code, s.valore FROM stage_menu_setting_translations s WHERE NOT EXISTS (SELECT 1 FROM public.menu_setting_translations t WHERE t.setting_id=s.setting_id AND t.language_code=s.language_code)
ON CONFLICT (setting_id, language_code) DO UPDATE SET valore=EXCLUDED.valore, updated_at=now();

