(284, 'RUM ZACAPA CENTENARIO 23', 'Originario del Guatemala, il Ron Zacapa 23 Años è un insieme di rum giovani e rum invecchiati fra i 6 e i 23 anni, affinato secondo un nuovo sistema di invecchiamento: il Solera dinamico. Un sistema che prevede l’utilizzo di botti di rovere bruciate che prima contenevano bourbon o Sherry, che conferiscono al distillato un profumo morbido e complesso con sentori di frutta matura e note speziate di noce moscata, cacao e liquirizia. Al palato risulta avvolgente, cremoso e caldo, con aromi speziati di cacao e vaniglia in cui si riconosce un leggero ricordo di legno bruciato, e con un finale piacevolmente intenso e persistente.', NULL, NULL, 'Guatemala', NULL),
(285, 'RUM ZACAPA XO', 'Matura in botti di rovere che hanno in precedenza ospitato robusti bourbon, delicati sherry e pregiati Pedro Ximenez, infine in barili francesi di cognac. Si ottiene da una miscela che include rum invecchiati fino a 25 anni, di eccezionale armonia e di qualità ineguagliabile. Intenso e morbido, con note di legno, frutta e leggeri sentori di vaniglia, mandorle e cioccolato.', NULL, NULL, 'Guatemala', NULL),
(286, 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Invecchiato per 6 lunghi anni in sole botti di rovere francese che hanno precedentemente contenuto Bourbon Whisky, processo necessario per ottenere il riconoscimento di XO. Il Très Vieux Rhum Agricole J. M riporta in pieno lo stile dei rhum agricoli della Martinica, con aromi complessi e stratificati ma dolci ed eleganti, un corpo pieno che pervade il palato lentamente e un finale lungo e dolcemente speziato.', NULL, NULL, 'Martinica', NULL),
(287, 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Colore ambrato intenso, con vivi riflessi rubino, presenta aromi fruttati dolci di datteri e albicocche secche, uva passa e pesca sciroppata, insieme a soffi speziati intensi di cannella e anice stellato e lievi accenni vanigliati. L''assaggio rivela calore ed eleganza, forza e delicatezza allo stesso tempo, in un corpo strutturato e goloso nei rimandi fruttati, deciso nel finale asciutto e coerente che chiude su toni di cuoio, tabacco e nocciola.', NULL, NULL, 'Martinica', NULL),
(288, 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Rhum agricolo full proof distillato nel 1995 ed imbottigliato nel 2015. Imbottigliato senza aggiunta di acqua o filtrazione prima dell’imbottigliamento; affumicato, legnoso, potente, pieno, di lunga persistenza.', NULL, NULL, NULL, NULL),
(289, 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'È un assemblaggio di rum tradizionali distillati in alambicchi a colonna e a ripasso: Diamond, Enmore, Versailles e Albione. Vengono invecchiati in fusti ex-bourbon, per ottenere un rum complesso, ricco e speziato, ma ugualmente mielato ed aromatico.', NULL, NULL, 'Guyana', NULL),
(290, 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Simbolo del rum latino, è prodotto a partire da un blend di melassa e succo di canna da zucchero e invecchiato per 12 anni in botti di rovere bianco. Gli aromi sono dolci e avvolgenti, con note prevalenti di frutta esotica, miele e caramello.', NULL, NULL, 'Venezuela', NULL),
(291, 'OBAN 14 Y.O.', 'L''Oban 14 Years Old è un dram classico che porta al suo interno tutta la storia della distilleria, al naso è ricco e torboso con note di frutta, al palato è denso e pieno, note di spezie e miele seguite da un secco affumicato, la finitura è abbastanza lunga con retrogusto di legno e con una certa salinità.', NULL, NULL, NULL, NULL),
(292, 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Di colore oro scuro, questo whisky è caratterizzato da un profilo olfattivo in cui si riconoscono sentori minerali che si intrecciano a note di alga in salamoia, fumo di torba e un leggero aroma agrumato. Al palato regala un’esperienza di degustazione unica con un sorso corposo e intenso e un ricordo di torba, fumo e pepe.', NULL, NULL, NULL, NULL),
(293, 'LAPHROAIG 10 Y.O.', 'Il Laphroaig 10 Years Old viene distillato nello stesso modo da quasi 75 anni. Il malto d''orzo viene essiccato su un fuoco di torba, torba che proviene esclusivamente dall''isola di Islay e che conferisce al Laphroaig il suo particolare sapore. Il risultato è un whisky corposo dal gusto affumicato e una dolcezza sorprendente.', NULL, NULL, NULL, NULL),
(294, 'LAGAVULIN 16 Y.O.', 'Il Lagavulin 16 Years Old è un single malt Scotch whisky torbato invecchiato per almeno 16 anni in botti ex-bourbon, è uno dei whisky di riferimento di milioni di appassionati nel mondo. In questo whisky troverete tutta la selvaggia e indomita isola di Skye.', NULL, NULL, NULL, NULL),
(295, 'NIKKA FROM THE BARREL', 'Il Nikka Whisky From The Barrel è un blend che unisce la tradizione giapponese, un riuscitissimo mix di whisky single malt e grain whisky giapponesi provenienti dalle distillerie Yoichi e Miyahikyo. La miscela riposa in botti di rovere prima di essere imbottigliata al 51,4% ed è senza dichiarazione d''età.', NULL, NULL, NULL, NULL),
(296, 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Il Johnnie Walker Green Label è un whisky formato da diversi single malt provenienti dallo Speyside, Highland, Lowland e Island invecchiati per almeno 15 anni, una miscela unica che comprende Talisker, Linkwood, Cragganmore e Caol Ila, pensata per offrire tutto il carattere e la profondità dei single malt Scozzesi.', NULL, NULL, NULL, NULL),
