DO $source$
BEGIN
 IF EXISTS (SELECT 1 FROM source_menu_item_translations s LEFT JOIN public.menu_items b ON b.id=s.id WHERE b.id IS NULL OR b.nome IS DISTINCT FROM s.nome OR b.descrizione IS DISTINCT FROM s.descrizione OR b.vitigni IS DISTINCT FROM s.vitigni OR b.produttore IS DISTINCT FROM s.produttore OR b.origine IS DISTINCT FROM s.origine OR b.regione IS DISTINCT FROM s.regione) THEN
  RAISE EXCEPTION 'Fonte italiana non corrispondente per menu_items: transazione annullata. Verificare ID, testi e NULL';
 END IF;
END $source$;

CREATE TEMP TABLE stage_menu_item_translations ON COMMIT DROP AS SELECT item_id, language_code, nome, descrizione, vitigni, produttore, origine, regione FROM public.menu_item_translations WITH NO DATA;

