(23, 'ar', 'ثلاثية Marechiaro', 'روبيان أحمر محلي متبّل بالحمضيات، قاعدة من البرتقال، بندق مجروش؛ خبز بحبر السيبيا، سلمون متبّل في مطبخنا، كريمة جبن، أوراق سلطة مشكّلة، مايونيز بالزعفران؛ تاتاكي التونة، كريمة شمّام Cantalupo.', NULL, NULL, NULL, NULL),
(24, 'ar', 'الكلاسيكية الخالدة', 'سلطة مأكولات بحرية محضّرة في مطبخنا.', NULL, NULL, NULL, NULL),
(25, 'ar', 'المقدّس والدنيوي', 'مورزيلّو من سمك القد المملّح، خبز pitta على طريقة كالابريا.', NULL, NULL, NULL, NULL),
(26, 'ar', 'جمال الكلاسيكيات', 'بلح البحر بالفلفل، خبز محمّص.', NULL, NULL, NULL, NULL),
(27, 'ar', 'أرضنا', 'لوح من اللحوم المقدّدة والأجبان والمربّيات من كالابريا.', NULL, NULL, NULL, NULL),
(28, 'ar', 'الريزوتو', 'أرز Carnaroli من Sibari “Magisa”، روبيان أحمر محلي، ليمون، زعتر.', NULL, NULL, NULL, NULL),
(29, 'ar', 'حين تغوص البطاطس في البحر', 'نيوكي محضّر في مطبخنا من بطاطس Sila I.G.P.، روبيان أحمر محلي، محار vongole veraci سوتيه، سالكورنيا.', NULL, NULL, NULL, NULL),
(30, 'ar', 'كلاسيكية الكلاسيكيات', 'سباغيتي “Gentile”، أنشوفة، باقة عطرية من كالابريا.', NULL, NULL, NULL, NULL),
(31, 'ar', 'نكهة كالابريا الأصيلة', 'معكرونة mezze maniche “Monograno” Felicetti، فطر بورسيني، باذنجان، سجق من خنزير كالابريا الأسود، ريكوتا مدخّنة.', NULL, NULL, NULL, NULL),
(32, 'ar', 'حين يلتقي البحث في فن الطهي بخصوصية المكان', 'سمك قد مملّح مطهو على حرارة منخفضة، بطاطس Sila، بصل Tropea، مسحوق زيتون Carolea، فلفل حار مجروش خشنًا.', NULL, NULL, NULL, NULL),
(33, 'ar', 'من كالابريا إلى المناطق الاستوائية', 'تونة محمّرة سريعًا، جوز الهند، نعناع، ليمون أخضر، Gin Mare.', NULL, NULL, NULL, NULL),
(34, 'ar', 'صيد اليوم المقلي', 'بحسب توفر صيد اليوم.', NULL, NULL, NULL, NULL),
(35, 'ar', 'حبار وروبيان مقليان', NULL, NULL, NULL, NULL, NULL),
(36, 'ar', 'الفيليه', 'فيليه لحم بقري مشوي.', NULL, NULL, NULL, NULL),
(37, 'ar', 'الأوّل في الصف', 'ستيك Fiorentina / Tomahawk.', NULL, NULL, NULL, NULL),
(38, 'ar', 'بطاطس بالفرن مع الأعشاب العطرية', NULL, NULL, NULL, NULL, NULL),
(39, 'ar', 'كابوناتينا على طريقة كالابريا', 'باذنجان, كوسا, فلفل حلو, طماطم كرزية كونفي, رقاقة خبز مقرمشة, بصل حلو وحامض.', NULL, NULL, NULL, NULL),
(40, 'ar', 'سلطة موسمية مشكّلة', NULL, NULL, NULL, NULL, NULL),
(41, 'ar', 'سلطة كالابريا', 'طماطم, زيت زيتون بكر ممتاز, بصل Tropea, أوريغانو, ريحان, فلفل حار.', NULL, NULL, NULL, NULL),
(42, 'ar', 'خضار برية على الطريقة الريفية التقليدية', NULL, NULL, NULL, NULL, NULL),
(43, 'ar', 'ميلفوي، كريمة شانتيلي، شوكولاتة', NULL, NULL, NULL, NULL, NULL),
