(52, 'ar', 'بروسكيتا بالطماطم', NULL, NULL, NULL, NULL, NULL),
(53, 'ar', 'MARINARA', 'باساتا طماطم datterino الحمراء من “Migliarese”, ثوم, أوريغانو, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(54, 'ar', 'MARGHERITA', 'باساتا طماطم datterino الحمراء من “Migliarese”, موزاريلا fior di latte, ريحان, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(55, 'ar', 'SFIZIOSA', 'موزاريلا fior di latte, لحم خنزير مقدّد Parma D.O.P. Gran Riserva، معتّق 24 شهرًا, تين, بصل مكرمل, جبن stracciatella, طماطم datterino صفراء وحمراء.', NULL, NULL, NULL, NULL),
(56, 'ar', 'PARMIGIANA 2.0', 'باساتا طماطم datterino الحمراء من “Migliarese”, موزاريلا fior di latte, جبن Parmigiano Reggiano D.O.P.، معتّق 24 شهرًا, شرائح باذنجان مقلية, كولي طماطم datterino حمراء كونفي, ريكوتا مدخّنة Crotonese D.O.P., ريحان, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(57, 'ar', 'MEDITERRANEA', 'Focaccia, شرائح موزاريلا fior di latte, شرائح تونة, لحم خنزير مقدّد Parma D.O.P. Gran Riserva، معتّق 24 شهرًا, جرجير, جبن Parmigiano Reggiano D.O.P.، معتّق 24 شهرًا, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(58, 'ar', 'FIORITA', 'موزاريلا fior di latte, شرائح أنشوفة من البحر المتوسط, طماطم datterino صفراء, أزهار الكوسا, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(59, 'ar', 'ROMANA', 'باساتا طماطم datterino الحمراء من “Migliarese”, شرائح أنشوفة من البحر المتوسط, ثمار الكَبَر (“Cucunci”), زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(60, 'ar', 'BRONTE', 'موزاريلا fior di latte, لحم خنزير مقدّد Parma D.O.P. Gran Riserva، معتّق 24 شهرًا, موزاريلا من حليب الجاموس, طماطم كرزية, فستق Pistacchio di Bronte D.O.P. مجروش, ريحان, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(61, 'ar', 'CALZONE GHIOTTO', 'موزاريلا fior di latte, لحم خنزير مقدّد Parma D.O.P. Gran Riserva، معتّق 24 شهرًا, موزاريلا من حليب الجاموس, طماطم كرزية, جرجير, جبن Parmigiano Reggiano D.O.P.، معتّق 24 شهرًا, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(62, 'ar', 'MUFASA', 'موزاريلا fior di latte, لحم خنزير مقدّد Parma D.O.P. Gran Riserva، معتّق 24 شهرًا, موزاريلا من حليب الجاموس, طماطم كرزية, جرجير, جبن Parmigiano Reggiano D.O.P.، معتّق 24 شهرًا, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(63, 'ar', 'GOLOSA', 'باساتا طماطم datterino الحمراء من “Migliarese”, شرائح أنشوفة من البحر المتوسط, friarielli (خضار البروكلي الإيطالية), بورّاتا, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(64, 'ar', 'MONTANARA', 'موزاريلا fior di latte, موزاريلا مدخّنة, بانشيتّا (بطن خنزير مقدّد), بطاطس بالفرن, caciocavallo di Ciminà, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(65, 'ar', 'سجق وfriarielli', 'موزاريلا fior di latte, سجق من خنزير كالابريا الأسود, friarielli (خضار البروكلي الإيطالية), زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(66, 'ar', 'البحر والجبال', 'موزاريلا fior di latte, روبيان, فطر بورسيني, جبن Parmigiano Reggiano D.O.P.، معتّق 24 شهرًا, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(67, 'ar', 'نباتية', 'موزاريلا fior di latte, كوسا, باذنجان, فلفل حلو, جرجير, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(68, 'ar', 'NAPOLI', 'باساتا طماطم datterino الحمراء من “Migliarese”, موزاريلا fior di latte, شرائح أنشوفة من البحر المتوسط, زيتون أسود مشوي بالفرن, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(69, 'ar', 'CALABRESE', 'باساتا طماطم datterino الحمراء من “Migliarese”, موزاريلا fior di latte, سلامي, زيتون أسود مشوي بالفرن, فلفل حار, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(70, 'ar', 'PUGLIESE', 'باساتا طماطم datterino الحمراء من “Migliarese”, موزاريلا fior di latte, تونة, بصل, زيتون أسود مشوي بالفرن, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(71, 'ar', 'أربعة أجبان', 'موزاريلا fior di latte, gorgonzola, Emmenthal, جبن Parmigiano Reggiano D.O.P.، معتّق 24 شهرًا, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(72, 'ar', 'الفصول الأربعة', 'باساتا طماطم datterino الحمراء من “Migliarese”, موزاريلا fior di latte, لحم خنزير مطهو, فطر, خرشوف, زيتون أسود مشوي بالفرن, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
(73, 'ar', 'CAPRESE', 'Focaccia, موزاريلا fior di latte, طماطم قلب الثور, ريحان, أوريغانو, زيت زيتون بكر ممتاز.', NULL, NULL, NULL, NULL),
