(284, 'ar', 'RUM ZACAPA CENTENARIO 23', 'يجمع Ron Zacapa 23 Años، القادم من غواتيمالا، بين أنواع روم فتيّة وأخرى معتّقة من 6 إلى 23 عامًا، وفق نظام تعتيق جديد: Solera الديناميكي. تمنحه براميل البلوط المحمّصة التي سبق أن احتوت bourbon أو Sherry باقة ناعمة ومركّبة من الفاكهة الناضجة وجوزة الطيب والكاكاو وعرق السوس. على الحنك هو غني وكريمي ودافئ، بروائح متبّلة من الكاكاو والفانيليا، ولمحة خفيفة من الخشب المحروق، ونهاية كثيفة وممتدة على نحو ممتع.', NULL, NULL, 'غواتيمالا', NULL),
(285, 'ar', 'RUM ZACAPA XO', 'ينضج في براميل البلوط التي كانت تحتوي في السابق على البوربون القوي، والشيري الرقيق، وPedro Ximenez الفاخر، وأخيرًا في براميل الكونياك الفرنسية. يتم الحصول عليه من مزيج يتضمن مشروب الرم الذي يصل عمره إلى 25 عامًا، ويتميز بتناغم استثنائي وجودة لا مثيل لها. كثيف وناعم، مع روائح الخشب والفواكه ولمحات خفيفة من الفانيليا واللوز والشوكولاتة.', NULL, NULL, 'غواتيمالا', NULL),
(286, 'ar', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'يُعتّق ست سنوات كاملة حصريًا في براميل بلوط فرنسي سبق أن احتوت Bourbon Whisky، وهي مدة التعتيق المطلوبة لتصنيف XO. يجسّد Très Vieux Rhum Agricole J. M أسلوب الروم الزراعي (rhum agricole) في مارتينيك: روائح مركّبة ومتعددة الطبقات، حلوة وأنيقة، وقوام ممتلئ يتكشّف ببطء على الحنك، ونهاية طويلة ومتبلّة بحلاوة.', NULL, NULL, 'مارتينيك', NULL),
(287, 'ar', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'لون كهرماني عميق بلمعات ياقوتية حيوية. تتداخل الروائح الحلوة للتمر والمشمش المجفف والزبيب والخوخ في الشراب السكّري مع نفحات كثيفة من القرفة واليانسون النجمي ولمسات رقيقة من الفانيليا. يجمع المذاق الدفء والأناقة والقوّة والرهافة في قوام منظّم وشهيّ بأصداء فاكهية. وتنتهي النهاية الواضحة والجافة والمتناغمة بنغمات الجلد والتبغ والبندق.', NULL, NULL, 'مارتينيك', NULL),
(288, 'ar', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'روم زراعي (rhum agricole) بكامل قوّته، قُطّر عام 1995 وعُبّئ عام 2015 دون إضافة ماء أو ترشيح. مدخّن وخشبي وقوي وممتلئ، بنهاية طويلة.', NULL, NULL, NULL, NULL),
(289, 'ar', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'مزيج من أنواع الروم التقليدية المقطّرة في أجهزة عمودية وأجهزة إعادة تقطير: Diamond وEnmore وVersailles وAlbione. يُعتّق في براميل سبق أن احتوت bourbon، للحصول على روم مركّب وغني ومتبل، وعسلي وعطري في الوقت نفسه.', NULL, NULL, 'غيانا', NULL),
(290, 'ar', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'رمز الروم اللاتيني، ويتم إنتاجه من مزيج من دبس السكر وعصير قصب السكر ويعمر لمدة 12 عامًا في براميل من خشب البلوط الأبيض. الروائح حلوة وغنية، مع روائح الفاكهة الاستوائية والعسل والكراميل.', NULL, NULL, 'فنزويلا', NULL),
(291, 'ar', 'OBAN 14 Y.O.', 'Oban 14 Years Old كأس كلاسيكية تختزل تاريخ مصنع التقطير. عطره غنيّ بالخث ونفحات الفاكهة؛ وفي الفم كثيف وممتلئ، بتوابل وعسل يتبعهما دخان جاف. وتترك نهايته الطويلة نسبيًا أصداء خشبية ولمسة ملوحة.', NULL, NULL, NULL, NULL),
(292, 'ar', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'يقدّم هذا الويسكي، بلونه الذهبي الداكن، باقة معدنية تتداخل مع أعشاب بحرية في محلول ملحي ودخان الخث وعطر حمضيات رقيق. وعلى الحنك يمنح تجربة مميّزة: مذاق ممتلئ وكثيف بأصداء الخث والدخان والفلفل.', NULL, NULL, NULL, NULL),
(293, 'ar', 'LAPHROAIG 10 Y.O.', 'يُقطّر Laphroaig 10 Years Old بالطريقة نفسها منذ ما يقرب من 75 عامًا. يُجفّف مالت الشعير فوق نار من الخث الذي يأتي حصريًا من Islay، فيمنح Laphroaig نكهته المميّزة. والنتيجة ويسكي ممتلئ بمذاق دخاني وحلاوة مدهشة.', NULL, NULL, NULL, NULL),
(294, 'ar', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old ويسكي سكوتش أحادي المالت بطابع الخث، معتّق 16 عامًا على الأقل في براميل سبق أن احتوت bourbon، ومرجع لملايين الهواة في العالم. ستجدون فيه الطابع البريّ الجامح لجزيرة Skye كاملًا.', NULL, NULL, NULL, NULL),
(295, 'ar', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel مزيج متجذّر في التقاليد اليابانية، يجمع بنجاح بين ويسكي أحادي المالت وويسكي حبوب ياباني من مصنعي Yoichi وMiyahikyo. يستريح المزيج في براميل بلوط قبل تعبئته بنسبة كحول 51,4 %، دون بيان للعمر.', NULL, NULL, NULL, NULL),
(296, 'ar', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'يجمع Johnnie Walker Green Label أنواع ويسكي أحادي المالت من Speyside وHighland وLowland وIsland، معتّقة 15 عامًا على الأقل. يضم هذا المزيج الفريد Talisker وLinkwood وCragganmore وCaol Ila، ليُظهر كامل طابع الويسكي الاسكتلندي أحادي المالت وعمقه.', NULL, NULL, NULL, NULL),
