(23, 'cs', 'Trilogie Marechiaro', 'Místní červená kreveta marinovaná v citrusech, pomerančový základ, drcené lískové oříšky; houska se sépiovým inkoustem, doma marinovaný losos, sýrový krém, směs mladých listů, šafránová majonéza; tuňákové tataki, krém z melounu Cantalupo.', NULL, NULL, NULL, NULL),
(24, 'cs', 'Nadčasová klasika', 'Domácí salát z mořských plodů.', NULL, NULL, NULL, NULL),
(25, 'cs', 'Posvátné a světské', 'Morzello ze soleného tresčího masa, kalábrijský chléb pitta.', NULL, NULL, NULL, NULL),
(26, 'cs', 'Krása klasiky', 'Slávky s pepřem, opečený chléb.', NULL, NULL, NULL, NULL),
(27, 'cs', 'Náš kraj', 'Prkénko kalábrijských uzenin, sýrů a džemů.', NULL, NULL, NULL, NULL),
(28, 'cs', 'Risotto', 'Rýže Carnaroli ze Sibari „Magisa“, místní červená kreveta, citron, tymián.', NULL, NULL, NULL, NULL),
(29, 'cs', 'Když se brambora ponoří do moře', 'Domácí gnocchi z brambor Sila I.G.P., místní červená kreveta, restované škeble vongole veraci, slanorožec.', NULL, NULL, NULL, NULL),
(30, 'cs', 'Klasika všech klasik', 'Spaghetti „Gentile“, ančovičky, kalábrijská aromatická směs.', NULL, NULL, NULL, NULL),
(31, 'cs', 'Typicky kalábrijské', 'Mezze maniche „Monograno“ Felicetti, hříbky, lilky, klobása z kalábrijského černého prasete, uzená ricotta.', NULL, NULL, NULL, NULL),
(32, 'cs', 'Když se kulinářské hledání setká s naším krajem', 'Solená treska připravená při nízké teplotě, brambora ze Sily, cibule z Tropey, prášek z oliv Carolea, hrubě mleté chilli.', NULL, NULL, NULL, NULL),
(33, 'cs', 'Z Kalábrie do tropů', 'Krátce opečený tuňák, kokos, máta, limeta, Gin Mare.', NULL, NULL, NULL, NULL),
(34, 'cs', 'Smažený úlovek dne', 'Dle dostupnosti denního úlovku.', NULL, NULL, NULL, NULL),
(35, 'cs', 'Smažené olihně a krevety', NULL, NULL, NULL, NULL, NULL),
(36, 'cs', 'Filet', 'Grilovaná hovězí svíčková.', NULL, NULL, NULL, NULL),
