(39, 'cs', 'Kalábrijská caponatina', 'Lilky, cukety, papriky, konfitovaná cherry rajčata, křupavá chlebová oplatka, sladkokyselá cibule.', NULL, NULL, NULL, NULL),
(40, 'cs', 'Míchaný sezonní salát', NULL, NULL, NULL, NULL, NULL),
(41, 'cs', 'Kalábrijský salát', 'Rajčata, extra panenský olivový olej, cibule z Tropey, oregano, bazalka, chilli paprička.', NULL, NULL, NULL, NULL),
