(53, 'cs', 'MARINARA', 'Passata z červených rajčat datterino „Migliarese“, česnek, oregano, extra panenský olivový olej.', NULL, NULL, NULL, NULL),
(54, 'cs', 'MARGHERITA', 'Passata z červených rajčat datterino „Migliarese“, mozzarella fior di latte, bazalka, extra panenský olivový olej.', NULL, NULL, NULL, NULL),
(55, 'cs', 'SFIZIOSA', 'Mozzarella fior di latte, sušená šunka Parma D.O.P. Gran Riserva, zrající 24 měsíců, fíky, karamelizovaná cibule, sýr stracciatella, žlutá a červená rajčata datterino.', NULL, NULL, NULL, NULL),
(56, 'cs', 'PARMIGIANA 2.0', 'Passata z červených rajčat datterino „Migliarese“, mozzarella fior di latte, Parmigiano Reggiano D.O.P., zrající 24 měsíců, proužky smaženého lilku, coulis z konfitovaných červených rajčat datterino, uzená ricotta Crotonese D.O.P., bazalka, extra panenský olivový olej.', NULL, NULL, NULL, NULL),
(57, 'cs', 'MEDITERRANEA', 'Focaccia, mozzarella fior di latte na plátky, filety z tuňáka, sušená šunka Parma D.O.P. Gran Riserva, zrající 24 měsíců, rukola, Parmigiano Reggiano D.O.P., zrající 24 měsíců, extra panenský olivový olej.', NULL, NULL, NULL, NULL),
(58, 'cs', 'FIORITA', 'Mozzarella fior di latte, filety ze středomořských ančoviček, žlutá rajčata datterino, cuketové květy, extra panenský olivový olej.', NULL, NULL, NULL, NULL),
(59, 'cs', 'ROMANA', 'Passata z červených rajčat datterino „Migliarese“, filety ze středomořských ančoviček, plody kaparů („Cucunci“), extra panenský olivový olej.', NULL, NULL, NULL, NULL),
(60, 'cs', 'BRONTE', 'Mozzarella fior di latte, sušená šunka Parma D.O.P. Gran Riserva, zrající 24 měsíců, buvolí mozzarella, cherry rajčata, drcený Pistacchio di Bronte D.O.P., bazalka, extra panenský olivový olej.', NULL, NULL, NULL, NULL),
(61, 'cs', 'CALZONE GHIOTTO', 'Mozzarella fior di latte, sušená šunka Parma D.O.P. Gran Riserva, zrající 24 měsíců, buvolí mozzarella, cherry rajčata, rukola, Parmigiano Reggiano D.O.P., zrající 24 měsíců, extra panenský olivový olej.', NULL, NULL, NULL, NULL),
(62, 'cs', 'MUFASA', 'Mozzarella fior di latte, sušená šunka Parma D.O.P. Gran Riserva, zrající 24 měsíců, buvolí mozzarella, cherry rajčata, rukola, Parmigiano Reggiano D.O.P., zrající 24 měsíců, extra panenský olivový olej.', NULL, NULL, NULL, NULL),
(63, 'cs', 'GOLOSA', 'Passata z červených rajčat datterino „Migliarese“, filety ze středomořských ančoviček, friarielli (italská listová brokolice), burrata, extra panenský olivový olej.', NULL, NULL, NULL, NULL),
