(284, 'cs', 'RUM ZACAPA CENTENARIO 23', 'Ron Zacapa 23 Años z Guatemaly spojuje mladé rumy s rumy zrajícími 6 až 23 let, zušlechtěné novým systémem zrání: dynamickou Solerou. Vypálené dubové sudy po bourbonu nebo Sherry mu propůjčují jemnou, komplexní vůni zralého ovoce, muškátového oříšku, kakaa a lékořice. Na patře je plný, krémový a hřejivý, s kořenitými tóny kakaa a vanilky, jemnou připomínkou opáleného dřeva a příjemně intenzivním, dlouhým závěrem.', NULL, NULL, 'Guatemala', NULL),
(285, 'cs', 'RUM ZACAPA XO', 'Zraje v dubových sudech, ve kterých dříve zrál robustní bourbony, jemné sherry a jemné Pedro Ximenez, a nakonec v sudech po francouzském koňaku. Získává se ze směsi, která obsahuje rumy zrající až 25 let, výjimečné harmonie a bezkonkurenční kvality. Intenzivní a jemný, s tóny dřeva, ovoce a lehkými nádechy vanilky, mandlí a čokolády.', NULL, NULL, 'Guatemala', NULL),
(286, 'cs', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Zraje celých 6 let výhradně v sudech z francouzského dubu po Bourbon Whisky, tedy způsobem potřebným pro označení XO. Très Vieux Rhum Agricole J. M vystihuje styl rumů agricole z Martiniku: komplexní, mnohovrstevné, ale sladké a elegantní vůně, plné tělo postupně se rozvíjející na patře a dlouhý, sladce kořenitý závěr.', NULL, NULL, 'Martinik', NULL),
(287, 'cs', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Sytě jantarová barva s živými rubínovými odlesky. Sladké vůně datlí, sušených meruněk, rozinek a broskví v sirupu doplňují výrazné tóny skořice a badyánu a jemná vanilka. Na patře se spojuje hřejivost a elegance, síla a jemnost, v plném, strukturovaném těle s lahodnými ovocnými ozvěnami. Výrazný, suchý a harmonický závěr doznívá kůží, tabákem a lískovým oříškem.', NULL, NULL, 'Martinik', NULL),
(288, 'cs', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Rum agricole v plné síle, destilovaný v roce 1995 a lahvovaný v roce 2015 bez přidání vody či filtrace. Kouřový, dřevitý, mohutný a plný, s dlouhým závěrem.', NULL, NULL, NULL, NULL),
(289, 'cs', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Směs tradičních rumů destilovaných v kolonách a kotlíkových destilačních přístrojích: Diamond, Enmore, Versailles a Albione. Zrání v sudech po bourbonu dává komplexní, bohatý a kořenitý rum, zároveň medový a aromatický.', NULL, NULL, 'Guyana', NULL),
(290, 'cs', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Symbol latinského rumu se vyrábí ze směsi melasy a šťávy z cukrové třtiny a zraje 12 let v sudech z bílého dubu. Vůně jsou sladké a obklopující, s převládajícími tóny exotického ovoce, medu a karamelu.', NULL, NULL, 'Venezuela', NULL),
(291, 'cs', 'OBAN 14 Y.O.', 'Oban 14 Years Old je klasický dram ztělesňující historii palírny. Vůně je bohatá a rašelinová, s ovocnými tóny; chuť hutná a plná, s kořením a medem, po nichž přichází suchý kouř. Poměrně dlouhý závěr doznívá dřevem a jemnou slaností.', NULL, NULL, NULL, NULL),
(292, 'cs', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Tato tmavě zlatá whisky nabízí minerální vůni s mořskými řasami v solném nálevu, rašelinovým kouřem a jemným citrusovým aromatem. Na patře přináší jedinečný zážitek: plný, intenzivní doušek s ozvěnou rašeliny, kouře a pepře.', NULL, NULL, NULL, NULL),
(293, 'cs', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old se destiluje stejně již téměř 75 let. Ječný slad se suší nad rašelinovým ohněm; rašelina pochází výhradně z Islay a dává Laphroaigu osobitou chuť. Výsledkem je plná whisky s kouřovou chutí a překvapivou sladkostí.', NULL, NULL, NULL, NULL),
(294, 'cs', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old je rašelinová skotská single malt whisky, zrající nejméně 16 let v sudech po bourbonu, etalon pro miliony nadšenců po celém světě. V této whisky naleznete celý divoký a nespoutaný charakter ostrova Skye.', NULL, NULL, NULL, NULL),
(295, 'cs', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel je blend vycházející z japonské tradice, zdařilá kombinace single malt a japonských obilných whisky z palíren Yoichi a Miyahikyo. Směs odpočívá v dubových sudech před lahvováním při 51,4 %, bez údaje o stáří.', NULL, NULL, NULL, NULL),
(296, 'cs', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label spojuje single malt whisky ze Speyside, Highland, Lowland a Island, zrající nejméně 15 let. Tento jedinečný blend zahrnuje Talisker, Linkwood, Cragganmore a Caol Ila a nabízí plný charakter i hloubku skotských single maltů.', NULL, NULL, NULL, NULL),
