(23, 'da', 'Marechiaro-trilogien', 'Lokal rød reje marineret i citrus, appelsinbund, hakkede hasselnødder; bolle med sepia-blæk, husmarineret laks, ostecreme, blandede spæde salatblade, safranmayonnaise; tuntataki, Cantaloupemeloncreme.', NULL, NULL, NULL, NULL),
