(55, 'da', 'SFIZIOSA', 'Fior di latte-mozzarella, Parma D.O.P. Gran Riserva-skinke, modnet 24 måneder, figner, karamelliserede løg, stracciatellaost, gule og røde datterinotomater.', NULL, NULL, NULL, NULL),
(56, 'da', 'PARMIGIANA 2.0', 'Passata af røde datterinotomater “Migliarese”, fior di latte-mozzarella, Parmigiano Reggiano D.O.P., modnet 24 måneder, friterede auberginestrimler, coulis af confiterede røde datterinotomater, røget ricotta Crotonese D.O.P., basilikum, ekstra jomfruolivenolie.', NULL, NULL, NULL, NULL),
(57, 'da', 'MEDITERRANEA', 'Focaccia, fior di latte-mozzarella i skiver, tunfileter, Parma D.O.P. Gran Riserva-skinke, modnet 24 måneder, rucola, Parmigiano Reggiano D.O.P., modnet 24 måneder, ekstra jomfruolivenolie.', NULL, NULL, NULL, NULL),
(58, 'da', 'FIORITA', 'Fior di latte-mozzarella, fileter af middelhavsansjoser, gule datterinotomater, squashblomster, ekstra jomfruolivenolie.', NULL, NULL, NULL, NULL),
