(63, 'da', 'GOLOSA', 'Passata af røde datterinotomater “Migliarese”, fileter af middelhavsansjoser, friarielli (broccoli-rabe), burrata, ekstra jomfruolivenolie.', NULL, NULL, NULL, NULL),
(64, 'da', 'MONTANARA', 'Fior di latte-mozzarella, røget mozzarella, pancetta, ovnbagte kartofler, caciocavallo di Ciminà, ekstra jomfruolivenolie.', NULL, NULL, NULL, NULL),
(65, 'da', 'Pølse og friarielli', 'Fior di latte-mozzarella, pølse af sort gris fra Calabrien, friarielli (broccoli-rabe), ekstra jomfruolivenolie.', NULL, NULL, NULL, NULL),
(66, 'da', 'Hav og bjerge', 'Fior di latte-mozzarella, rejer, karljohansvampe, Parmigiano Reggiano D.O.P., modnet 24 måneder, ekstra jomfruolivenolie.', NULL, NULL, NULL, NULL),
