(284, 'da', 'RUM ZACAPA CENTENARIO 23', 'Ron Zacapa 23 Años fra Guatemala forener ung rom med rom lagret i 6 til 23 år, modnet efter et nyt lagringssystem: dynamisk Solera. Brændte egetræsfade, som tidligere indeholdt bourbon eller Sherry, giver en blød, kompleks duft af moden frugt, muskatnød, kakao og lakrids. På ganen er den omsluttende, cremet og varm, med krydrede noter af kakao og vanilje, et diskret strejf af brændt træ og en behageligt intens, vedvarende eftersmag.', NULL, NULL, 'Guatemala', NULL),
(285, 'da', 'RUM ZACAPA XO', 'Den modnes på egetræsfade, der tidligere har indeholdt robuste bourbons, delikate sherryer og fine Pedro Ximenez, og endelig på franske cognacfade. Den er fremstillet af en blanding, der inkluderer rom lagret op til 25 år, af enestående harmoni og uovertruffen kvalitet. Intens og blød, med noter af træ, frugt og lette strejf af vanilje, mandler og chokolade.', NULL, NULL, 'Guatemala', NULL),
(286, 'da', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Lagret i 6 fulde år udelukkende på franske egetræsfade, der tidligere indeholdt Bourbon Whisky, den lagring der kræves for XO-betegnelsen. Très Vieux Rhum Agricole J. M udtrykker stilen i Martiniques rhums agricoles: komplekse, lagdelte, men søde og elegante aromaer, en fyldig krop der langsomt udfolder sig på ganen og en lang, sødt krydret eftersmag.', NULL, NULL, 'Martinique', NULL),
(287, 'da', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Dyb ravfarve med livlige rubinrøde skær. Søde aromaer af dadler, tørrede abrikoser, rosiner og ferskner i sirup møder intens kanel og stjerneanis samt et strejf af vanilje. Smagen forener varme og elegance, kraft og finesse i en struktureret, lækker krop med frugtige ekkoer. Den markante, tørre og harmoniske eftersmag slutter med læder, tobak og hasselnød.', NULL, NULL, 'Martinique', NULL),
(288, 'da', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Rhum agricole på fuld styrke, destilleret i 1995 og aftappet i 2015 uden tilsætning af vand eller filtrering. Røget, træpræget, kraftfuld og fyldig, med lang eftersmag.', NULL, NULL, NULL, NULL),
(289, 'da', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'En blanding af traditionel rom destilleret i kolonne- og pot still-anlæg: Diamond, Enmore, Versailles og Albione. Lagring på ex-bourbonfade giver en kompleks, rig og krydret rom, samtidig honningpræget og aromatisk.', NULL, NULL, 'Guyana', NULL),
(290, 'da', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Symbol for latinsk rom, den er fremstillet af en blanding af melasse og sukkerrørsjuice og lagret i 12 år på hvide egetræsfade. Aromaerne er søde og omsluttende med fremherskende noter af eksotisk frugt, honning og karamel.', NULL, NULL, 'Venezuela', NULL),
(291, 'da', 'OBAN 14 Y.O.', 'Oban 14 Years Old er en klassisk dram, der rummer destilleriets historie. Duften er rig og tørvepræget med frugtnoter; smagen tæt og fyldig, med krydderier og honning efterfulgt af tør røg. Den ret lange eftersmag har træagtige ekkoer og et strejf af salt.', NULL, NULL, NULL, NULL),
(292, 'da', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Denne mørkt gyldne whisky har en mineralsk duft med tang i saltlage, tørverøg og en let citrusaroma. Smagen giver en særlig oplevelse: fyldig og intens, med ekkoer af tørv, røg og peber.', NULL, NULL, NULL, NULL),
(293, 'da', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old er blevet destilleret på samme måde i næsten 75 år. Bygmalten tørres over tørveild med tørv udelukkende fra Islay, som giver Laphroaig sin særlige smag. Resultatet er en fyldig whisky med røget smag og overraskende sødme.', NULL, NULL, NULL, NULL),
(294, 'da', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old er en tørvepræget skotsk single malt whisky, lagret mindst 16 år på ex-bourbonfade og et forbillede for millioner af entusiaster verden over. Her finder I hele øen Skyes vilde, utæmmede karakter.', NULL, NULL, NULL, NULL),
(295, 'da', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel er en blend med rødder i japansk tradition, en meget vellykket kombination af single malt og japansk grain whisky fra Yoichi og Miyahikyo. Blandingen hviler på egetræsfade før aftapning ved 51,4 %, uden aldersangivelse.', NULL, NULL, NULL, NULL),
(296, 'da', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label forener single malts fra Speyside, Highland, Lowland og Island, lagret mindst 15 år. Denne unikke blend omfatter Talisker, Linkwood, Cragganmore og Caol Ila og udtrykker skotske single malts fulde karakter og dybde.', NULL, NULL, NULL, NULL),
