(282, 'de', 'Pfirsichtee', NULL, NULL, NULL, NULL, NULL),
(283, 'de', 'Zitronentee', NULL, NULL, NULL, NULL, NULL),
(284, 'de', 'RUM ZACAPA CENTENARIO 23', 'Ron Zacapa 23 Años aus Guatemala vereint junge Rums mit 6 bis 23 Jahre gereiften Rums, ausgebaut nach einem neuen Reifungsverfahren: dem dynamischen Solera-System. Ausgebrannte Eichenfässer, in denen zuvor Bourbon oder Sherry lagerte, verleihen ihm ein weiches, komplexes Bouquet von reifen Früchten, Muskatnuss, Kakao und Lakritze. Am Gaumen zeigt er sich vollmundig, cremig und warm, mit würzigen Kakao- und Vanillearomen, einem feinen Anklang von gebranntem Holz und einem angenehm intensiven, anhaltenden Abgang.', NULL, NULL, 'Guatemala', NULL),
(285, 'de', 'RUM ZACAPA XO', 'Er reift in Eichenfässern, in denen zuvor kräftiger Bourbon, zarter Sherry und feiner Pedro Ximenez gelagert wurden, und schließlich in französischen Cognac-Fässern. Er wird aus einer Mischung gewonnen, die bis zu 25 Jahre alte Rumsorten von außergewöhnlicher Harmonie und unvergleichlicher Qualität umfasst. Intensiv und weich, mit Noten von Holz, Früchten und leichten Anklängen von Vanille, Mandeln und Schokolade.', NULL, NULL, 'Guatemala', NULL),
(286, 'de', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Sechs volle Jahre ausschließlich in französischen Eichenfässern gereift, in denen zuvor Bourbon Whisky lagerte – die Reifung für die XO-Klassifizierung. Très Vieux Rhum Agricole J. M verkörpert den Stil der Rhums agricoles aus Martinique: komplexe, vielschichtige und dennoch süße, elegante Aromen, einen vollen Körper, der sich langsam am Gaumen entfaltet, und einen langen, süß-würzigen Abgang.', NULL, NULL, 'Martinique', NULL),
(287, 'de', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Intensives Bernstein mit lebhaften rubinroten Reflexen. Süße Fruchtaromen von Datteln, getrockneten Aprikosen, Rosinen und Pfirsichen in Sirup verbinden sich mit kräftigen Noten von Zimt und Sternanis sowie zarter Vanille. Am Gaumen vereinen sich Wärme und Eleganz, Kraft und Feinheit in einem strukturierten, üppigen Körper mit fruchtigen Anklängen. Der markante, trockene und stimmige Abgang endet mit Leder, Tabak und Haselnuss.', NULL, NULL, 'Martinique', NULL),
(288, 'de', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Rhum agricole in voller Stärke, 1995 destilliert und 2015 ohne Wasserzugabe oder Filtration abgefüllt. Rauchig, holzbetont, kraftvoll und vollmundig, mit langem Nachhall.', NULL, NULL, NULL, NULL),
(289, 'de', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Ein Blend traditioneller Rums aus Kolonnen- und Pot-Still-Destillation: Diamond, Enmore, Versailles und Albione. Die Reifung in ehemaligen Bourbonfässern ergibt einen komplexen, reichhaltigen und würzigen Rum mit Honignoten und aromatischer Fülle.', NULL, NULL, 'Guyana', NULL),
(290, 'de', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Als Sinnbild des lateinamerikanischen Rums wird er aus einer Mischung von Melasse und Zuckerrohrsaft hergestellt und 12 Jahre lang in Weißeichenfässern gereift. Die Aromen sind süß und umhüllend, mit vorherrschenden Noten von exotischen Früchten, Honig und Karamell.', NULL, NULL, 'Venezuela', NULL),
(291, 'de', 'OBAN 14 Y.O.', 'Oban 14 Years Old ist ein klassischer Dram, der die Geschichte der Brennerei verkörpert. In der Nase reich und torfig, mit Fruchtnoten; am Gaumen dicht und voll, mit Gewürzen und Honig, denen trockener Rauch folgt. Der recht lange Abgang zeigt holzige Anklänge und eine feine Salzigkeit.', NULL, NULL, NULL, NULL),
(292, 'de', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Dieser dunkelgoldene Whisky zeigt ein mineralisches Bouquet mit Noten von Seetang in Salzlake, Torfrauch und zarten Zitrusaromen. Am Gaumen bietet er ein besonderes Genusserlebnis: vollmundig und intensiv, mit Anklängen von Torf, Rauch und Pfeffer.', NULL, NULL, NULL, NULL),
(293, 'de', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old wird seit fast 75 Jahren auf dieselbe Weise destilliert. Das Gerstenmalz trocknet über einem Torffeuer; der Torf stammt ausschließlich von Islay und verleiht Laphroaig seinen besonderen Geschmack. Das Ergebnis ist ein vollmundiger Whisky mit rauchigem Charakter und überraschender Süße.', NULL, NULL, NULL, NULL),
(294, 'de', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old ist ein getorfter Single Malt Scotch Whisky, mindestens 16 Jahre in ehemaligen Bourbonfässern gereift, ein Maßstab für Millionen von Liebhabern weltweit. In diesem Whisky zeigt sich der wilde, ungezähmte Charakter der Isle of Skye.', NULL, NULL, NULL, NULL),
(295, 'de', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel ist ein Blend in japanischer Tradition, eine besonders gelungene Kombination aus Single Malt und japanischen Grain Whiskys der Brennereien Yoichi und Miyahikyo. Der Blend ruht vor der Abfüllung mit 51,4 % in Eichenfässern und trägt keine Altersangabe.', NULL, NULL, NULL, NULL),
(296, 'de', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label vereint mindestens 15 Jahre gereifte Single Malts aus Speyside, Highland, Lowland und Island. Dieser einzigartige Blend enthält Talisker, Linkwood, Cragganmore und Caol Ila und zeigt den ganzen Charakter und die Tiefe schottischer Single Malts.', NULL, NULL, NULL, NULL),
