(23, 'el', 'Η τριλογία Marechiaro', 'Τοπική κόκκινη γαρίδα μαριναρισμένη σε εσπεριδοειδή, βάση πορτοκαλιού, τριμμένο φουντούκι· ψωμάκι με μελάνι σουπιάς, σολομός μαριναρισμένος στην κουζίνα μας, κρέμα τυριού, ανάμεικτα φύλλα σαλάτας, μαγιονέζα σαφράν· τατάκι τόνου, κρέμα πεπονιού Cantalupo.', NULL, NULL, NULL, NULL),
(24, 'el', 'Το διαχρονικό κλασικό', 'Σπιτική σαλάτα θαλασσινών.', NULL, NULL, NULL, NULL),
(25, 'el', 'Ιερό και βέβηλο', 'Morzello από παστό μπακαλιάρο, καλαβρέζικο ψωμί pitta.', NULL, NULL, NULL, NULL),
(26, 'el', 'Η ομορφιά του κλασικού', 'Μύδια με πιπέρι, φρυγανισμένο ψωμί.', NULL, NULL, NULL, NULL),
(27, 'el', 'Ο τόπος μας', 'Πλατό αλλαντικών, τυριών και μαρμελάδων Καλαβρίας.', NULL, NULL, NULL, NULL),
(28, 'el', 'Το ριζότο', 'Ρύζι Carnaroli από το Sibari “Magisa”, τοπική κόκκινη γαρίδα, λεμόνι, θυμάρι.', NULL, NULL, NULL, NULL),
(29, 'el', 'Όταν η πατάτα βουτά στη θάλασσα', 'Σπιτικά νιόκι από πατάτες Sila I.G.P., τοπική κόκκινη γαρίδα, αχιβάδες vongole veraci σοτέ, σαλικόρνια.', NULL, NULL, NULL, NULL),
(30, 'el', 'Το κλασικό των κλασικών', 'Σπαγγέτι “Gentile”, γαύρος, αρωματικό μπουκέτο Καλαβρίας.', NULL, NULL, NULL, NULL),
(31, 'el', 'Αυθεντικά καλαβρέζικο', 'Mezze maniche “Monograno” Felicetti, μανιτάρια πορτσίνι, μελιτζάνες, λουκάνικο από μαύρο χοίρο Καλαβρίας, καπνιστή ρικότα.', NULL, NULL, NULL, NULL),
(32, 'el', 'Όταν η γαστρονομική αναζήτηση συναντά τον τόπο', 'Παστός μπακαλιάρος μαγειρεμένος σε χαμηλή θερμοκρασία, πατάτα Sila, κρεμμύδι Tropea, σκόνη ελιάς Carolea, χοντροτριμμένη καυτερή πιπεριά.', NULL, NULL, NULL, NULL),
(33, 'el', 'Από την Καλαβρία στους τροπικούς', 'Τόνος ελαφρά ψημένος, καρύδα, μέντα, λάιμ, Gin Mare.', NULL, NULL, NULL, NULL),
(34, 'el', 'Τηγανητή ψαριά ημέρας', 'Ανάλογα με τη διαθεσιμότητα της ημερήσιας ψαριάς.', NULL, NULL, NULL, NULL),
(35, 'el', 'Τηγανητά καλαμάρια και γαρίδες', NULL, NULL, NULL, NULL, NULL),
(36, 'el', 'Το φιλέτο', 'Μοσχαρίσιο φιλέτο στη σχάρα.', NULL, NULL, NULL, NULL),
(37, 'el', 'Ο πρώτος της τάξης', 'Μπριζόλα Fiorentina / Tomahawk.', NULL, NULL, NULL, NULL),
