(39, 'el', 'Καλαβρέζικη καπονατίνα', 'Μελιτζάνες, κολοκύθια, πιπεριές, ντοματίνια κονφί, τραγανό φύλλο ψωμιού, γλυκόξινο κρεμμύδι.', NULL, NULL, NULL, NULL),
(40, 'el', 'Ανάμεικτη σαλάτα εποχής', NULL, NULL, NULL, NULL, NULL),
(41, 'el', 'Καλαβρέζικη σαλάτα', 'Ντομάτες, εξαιρετικό παρθένο ελαιόλαδο, κρεμμύδι Tropea, ρίγανη, βασιλικός, καυτερή πιπεριά.', NULL, NULL, NULL, NULL),
