(53, 'el', 'MARINARA', 'Πασάτα κόκκινης ντομάτας datterino “Migliarese”, σκόρδο, ρίγανη, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(54, 'el', 'MARGHERITA', 'Πασάτα κόκκινης ντομάτας datterino “Migliarese”, μοτσαρέλα fior di latte, βασιλικός, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(55, 'el', 'SFIZIOSA', 'Μοτσαρέλα fior di latte, προσούτο Parma D.O.P. Gran Riserva, ωρίμανσης 24 μηνών, σύκα, καραμελωμένο κρεμμύδι, τυρί stracciatella, κίτρινες και κόκκινες ντομάτες datterino.', NULL, NULL, NULL, NULL),
(56, 'el', 'PARMIGIANA 2.0', 'Πασάτα κόκκινης ντομάτας datterino “Migliarese”, μοτσαρέλα fior di latte, Parmigiano Reggiano D.O.P., ωρίμανσης 24 μηνών, λωρίδες τηγανητής μελιτζάνας, κουλί κόκκινης ντομάτας datterino κονφί, καπνιστή ρικότα Crotonese D.O.P., βασιλικός, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(57, 'el', 'MEDITERRANEA', 'Focaccia, μοτσαρέλα fior di latte σε φέτες, φιλέτα τόνου, προσούτο Parma D.O.P. Gran Riserva, ωρίμανσης 24 μηνών, ρόκα, Parmigiano Reggiano D.O.P., ωρίμανσης 24 μηνών, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(58, 'el', 'FIORITA', 'Μοτσαρέλα fior di latte, φιλέτα μεσογειακού γαύρου, κίτρινες ντομάτες datterino, ανθοί κολοκυθιού, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(59, 'el', 'ROMANA', 'Πασάτα κόκκινης ντομάτας datterino “Migliarese”, φιλέτα μεσογειακού γαύρου, καπαρόμηλα (“Cucunci”), εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(60, 'el', 'BRONTE', 'Μοτσαρέλα fior di latte, προσούτο Parma D.O.P. Gran Riserva, ωρίμανσης 24 μηνών, μοτσαρέλα βουβαλίσια, ντοματίνια, τριμμένο Pistacchio di Bronte D.O.P., βασιλικός, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(61, 'el', 'CALZONE GHIOTTO', 'Μοτσαρέλα fior di latte, προσούτο Parma D.O.P. Gran Riserva, ωρίμανσης 24 μηνών, μοτσαρέλα βουβαλίσια, ντοματίνια, ρόκα, Parmigiano Reggiano D.O.P., ωρίμανσης 24 μηνών, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(62, 'el', 'MUFASA', 'Μοτσαρέλα fior di latte, προσούτο Parma D.O.P. Gran Riserva, ωρίμανσης 24 μηνών, μοτσαρέλα βουβαλίσια, ντοματίνια, ρόκα, Parmigiano Reggiano D.O.P., ωρίμανσης 24 μηνών, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(63, 'el', 'GOLOSA', 'Πασάτα κόκκινης ντομάτας datterino “Migliarese”, φιλέτα μεσογειακού γαύρου, friarielli (χόρτα μπρόκολου), μπουράτα, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(64, 'el', 'MONTANARA', 'Μοτσαρέλα fior di latte, καπνιστή μοτσαρέλα, παντσέτα, πατάτες φούρνου, caciocavallo di Ciminà, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(65, 'el', 'Λουκάνικο και friarielli', 'Μοτσαρέλα fior di latte, λουκάνικο από μαύρο χοίρο Καλαβρίας, friarielli (χόρτα μπρόκολου), εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(66, 'el', 'Θάλασσα και βουνό', 'Μοτσαρέλα fior di latte, γαρίδες, μανιτάρια πορτσίνι, Parmigiano Reggiano D.O.P., ωρίμανσης 24 μηνών, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(67, 'el', 'Χορτοφαγική', 'Μοτσαρέλα fior di latte, κολοκύθια, μελιτζάνες, πιπεριές, ρόκα, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(68, 'el', 'NAPOLI', 'Πασάτα κόκκινης ντομάτας datterino “Migliarese”, μοτσαρέλα fior di latte, φιλέτα μεσογειακού γαύρου, μαύρες ελιές φούρνου, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(69, 'el', 'CALABRESE', 'Πασάτα κόκκινης ντομάτας datterino “Migliarese”, μοτσαρέλα fior di latte, σαλάμι, μαύρες ελιές φούρνου, καυτερή πιπεριά, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(70, 'el', 'PUGLIESE', 'Πασάτα κόκκινης ντομάτας datterino “Migliarese”, μοτσαρέλα fior di latte, τόνος, κρεμμύδι, μαύρες ελιές φούρνου, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(71, 'el', 'Τέσσερα τυριά', 'Μοτσαρέλα fior di latte, gorgonzola, Emmenthal, Parmigiano Reggiano D.O.P., ωρίμανσης 24 μηνών, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(72, 'el', 'Τέσσερις εποχές', 'Πασάτα κόκκινης ντομάτας datterino “Migliarese”, μοτσαρέλα fior di latte, ζαμπόν, μανιτάρια, αγκινάρες, μαύρες ελιές φούρνου, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
(73, 'el', 'CAPRESE', 'Focaccia, μοτσαρέλα fior di latte, ντομάτα καρδιά βοδιού, βασιλικός, ρίγανη, εξαιρετικό παρθένο ελαιόλαδο.', NULL, NULL, NULL, NULL),
