(284, 'el', 'RUM ZACAPA CENTENARIO 23', 'Το Ron Zacapa 23 Años από τη Γουατεμάλα συνδυάζει νεαρά ρούμια με ρούμια παλαιωμένα από 6 έως 23 χρόνια, με ένα νέο σύστημα παλαίωσης: το δυναμικό Solera. Τα καψαλισμένα δρύινα βαρέλια που είχαν περιέχει bourbon ή Sherry χαρίζουν απαλό, σύνθετο μπουκέτο ώριμων φρούτων, μοσχοκάρυδου, κακάο και γλυκόριζας. Στο στόμα είναι πληθωρικό, κρεμώδες και ζεστό, με πικάντικα αρώματα κακάο και βανίλιας, διακριτική νότα καμένου ξύλου και ευχάριστα έντονη, επίμονη επίγευση.', NULL, NULL, 'Γουατεμάλα', NULL),
(285, 'el', 'RUM ZACAPA XO', 'Ωριμάζει σε δρύινα βαρέλια που έχουν φιλοξενήσει στο παρελθόν στιβαρά bourbon, ντελικάτα σέρι και εκλεκτά Pedro Ximenez και τέλος σε βαρέλια γαλλικού κονιάκ. Λαμβάνεται από ένα χαρμάνι που περιλαμβάνει ρούμια παλαίωσης έως 25 ετών, εξαιρετικής αρμονίας και απαράμιλλης ποιότητας. Έντονο και απαλό, με νότες ξύλου, φρούτων και ελαφριές νότες βανίλιας, αμύγδαλου και σοκολάτας.', NULL, NULL, 'Γουατεμάλα', NULL),
(286, 'el', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Παλαιώνει για 6 ολόκληρα χρόνια αποκλειστικά σε γαλλικά δρύινα βαρέλια που είχαν περιέχει Bourbon Whisky, η παλαίωση που απαιτείται για τον χαρακτηρισμό XO. Το Très Vieux Rhum Agricole J. M εκφράζει το ύφος των rhums agricoles της Μαρτινίκας: σύνθετα και πολυεπίπεδα, αλλά γλυκά και κομψά αρώματα, γεμάτο σώμα που απλώνεται αργά στον ουρανίσκο και μακρά, γλυκά πικάντικη επίγευση.', NULL, NULL, 'Μαρτινίκα', NULL),
(287, 'el', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Έντονο κεχριμπαρένιο χρώμα με ζωηρές ρουμπινί ανταύγειες. Γλυκά αρώματα χουρμάδων, αποξηραμένων βερίκοκων, σταφίδας και ροδάκινου σε σιρόπι συνδυάζονται με έντονες νότες κανέλας και αστεροειδούς γλυκάνισου και διακριτική βανίλια. Στο στόμα ενώνει ζεστασιά και κομψότητα, δύναμη και λεπτότητα, σε δομημένο, λαχταριστό σώμα με φρουτώδεις αποχρώσεις. Η αποφασιστική, ξηρή και αρμονική επίγευση κλείνει με δέρμα, καπνό και φουντούκι.', NULL, NULL, 'Μαρτινίκα', NULL),
(288, 'el', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Rhum agricole full proof, αποσταγμένο το 1995 και εμφιαλωμένο το 2015 χωρίς προσθήκη νερού ή φιλτράρισμα. Καπνιστό, ξυλώδες, δυνατό και γεμάτο, με μακρά επίγευση.', NULL, NULL, NULL, NULL),
(289, 'el', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Χαρμάνι παραδοσιακών ρουμιών αποσταγμένων σε αποστακτήρες στήλης και επαναπόσταξης: Diamond, Enmore, Versailles και Albione. Η παλαίωση σε βαρέλια πρώην bourbon δίνει ένα σύνθετο, πλούσιο και πικάντικο ρούμι, μελένιο και αρωματικό.', NULL, NULL, 'Γουιάνα', NULL),
(290, 'el', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Σύμβολο του λατινοαμερικανικού ρουμιού, παράγεται από μείγμα μελάσας και χυμού ζαχαροκάλαμου και παλαιώνει για 12 χρόνια σε βαρέλια λευκής δρυός. Τα αρώματα είναι γλυκά και πληθωρικά, με κυρίαρχες νότες εξωτικών φρούτων, μελιού και καραμέλας.', NULL, NULL, 'Βενεζουέλα', NULL),
(291, 'el', 'OBAN 14 Y.O.', 'Το Oban 14 Years Old είναι ένα κλασικό dram που ενσαρκώνει την ιστορία του αποστακτηρίου. Πλούσιο άρωμα τύρφης με νότες φρούτων· πυκνό και γεμάτο στο στόμα, με μπαχαρικά και μέλι που ακολουθούνται από ξηρό καπνό. Η αρκετά μακρά επίγευση αφήνει ξυλώδεις αποχρώσεις και μια νότα αλμύρας.', NULL, NULL, NULL, NULL),
(292, 'el', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Με σκούρο χρυσό χρώμα, αυτό το ουίσκι προσφέρει μεταλλικές νότες που πλέκονται με φύκια σε άλμη, καπνό τύρφης και διακριτικό άρωμα εσπεριδοειδών. Στο στόμα δίνει μια ξεχωριστή εμπειρία: γεμάτη, έντονη γεύση με αποχρώσεις τύρφης, καπνού και πιπεριού.', NULL, NULL, NULL, NULL),
(293, 'el', 'LAPHROAIG 10 Y.O.', 'Το Laphroaig 10 Years Old αποστάζεται με τον ίδιο τρόπο εδώ και σχεδόν 75 χρόνια. Η βύνη κριθαριού ξηραίνεται πάνω σε φωτιά τύρφης, η οποία προέρχεται αποκλειστικά από το Islay και χαρίζει στο Laphroaig τη χαρακτηριστική του γεύση. Το αποτέλεσμα είναι ένα γεμάτο ουίσκι με καπνιστή γεύση και απρόσμενη γλυκύτητα.', NULL, NULL, NULL, NULL),
(294, 'el', 'LAGAVULIN 16 Y.O.', 'Το Lagavulin 16 Years Old είναι ένα σκωτσέζικο single malt ουίσκι με τύρφη, παλαιωμένο τουλάχιστον 16 χρόνια σε βαρέλια πρώην bourbon, σημείο αναφοράς για εκατομμύρια φίλους του ουίσκι παγκοσμίως. Σε αυτό θα βρείτε όλο τον άγριο, αδάμαστο χαρακτήρα του νησιού Skye.', NULL, NULL, NULL, NULL),
(295, 'el', 'NIKKA FROM THE BARREL', 'Το Nikka Whisky From The Barrel είναι ένα blend με ρίζες στην ιαπωνική παράδοση, ένας ιδιαίτερα επιτυχημένος συνδυασμός single malt και ιαπωνικών ουίσκι δημητριακών από τα αποστακτήρια Yoichi και Miyahikyo. Το χαρμάνι ξεκουράζεται σε δρύινα βαρέλια πριν εμφιαλωθεί στο 51,4 %, χωρίς ένδειξη ηλικίας.', NULL, NULL, NULL, NULL),
(296, 'el', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Το Johnnie Walker Green Label συνδυάζει single malt από Speyside, Highland, Lowland και Island, παλαιωμένα τουλάχιστον 15 χρόνια. Αυτό το μοναδικό blend περιλαμβάνει Talisker, Linkwood, Cragganmore και Caol Ila, εκφράζοντας όλο τον χαρακτήρα και το βάθος των σκωτσέζικων single malt.', NULL, NULL, NULL, NULL),
