(283, 'en', 'Lemon tea', NULL, NULL, NULL, NULL, NULL),
(284, 'en', 'RUM ZACAPA CENTENARIO 23', 'Ron Zacapa 23 Años from Guatemala blends young rums with rums aged between 6 and 23 years, matured using a new ageing system: dynamic Solera. Charred oak casks that previously held bourbon or Sherry lend the spirit a soft, complex bouquet of ripe fruit, nutmeg, cocoa and liquorice. On the palate it is enveloping, creamy and warm, with spicy cocoa and vanilla aromas, a subtle suggestion of charred wood and a pleasantly intense, lingering finish.', NULL, NULL, 'Guatemala', NULL),
(285, 'en', 'RUM ZACAPA XO', 'It matures in oak casks that previously held robust bourbons, delicate sherries and fine Pedro Ximenez, and finally in French cognac barrels. It is obtained from a blend that includes rums aged up to 25 years, of exceptional harmony and unparalleled quality. Intense and soft, with notes of wood, fruit and light hints of vanilla, almonds and chocolate.', NULL, NULL, 'Guatemala', NULL),
(286, 'en', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Aged for 6 full years exclusively in French oak casks that previously held Bourbon Whisky, the maturation required for the XO designation. Très Vieux Rhum Agricole J. M embodies the style of Martinique’s rhums agricoles: complex, layered yet sweet and elegant aromas, a full body that gradually unfolds across the palate, and a long, sweetly spiced finish.', NULL, NULL, 'Martinique', NULL),
(287, 'en', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Deep amber with lively ruby highlights. Sweet fruit aromas of dates, dried apricots, raisins and peaches in syrup mingle with intense cinnamon and star anise, and delicate vanilla. The palate combines warmth and elegance, strength and finesse, in a structured, luscious body with fruity echoes. A firm, dry and harmonious finish closes on leather, tobacco and hazelnut.', NULL, NULL, 'Martinique', NULL),
(288, 'en', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Full-proof rhum agricole, distilled in 1995 and bottled in 2015 without dilution or filtration. Smoky, woody, powerful and full-bodied, with a long finish.', NULL, NULL, NULL, NULL),
(289, 'en', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'A blend of traditional rums distilled in column and pot stills: Diamond, Enmore, Versailles and Albione. Aged in ex-bourbon casks for a complex, rich and spicy rum that is also honeyed and aromatic.', NULL, NULL, 'Guyana', NULL),
(290, 'en', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Symbol of Latin rum, it is produced from a blend of molasses and sugar cane juice and aged for 12 years in white-oak casks. The aromas are sweet and enveloping, with prevailing notes of exotic fruit, honey and caramel.', NULL, NULL, 'Venezuela', NULL),
(291, 'en', 'OBAN 14 Y.O.', 'Oban 14 Years Old is a classic dram that embodies the distillery’s history. Rich and peaty on the nose, with fruit notes; dense and full on the palate, where spice and honey give way to dry smoke. The fairly long finish has woody echoes and a touch of salinity.', NULL, NULL, NULL, NULL),
(292, 'en', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Dark gold in colour, this whisky offers a bouquet of mineral notes woven with seaweed in brine, peat smoke and a delicate citrus aroma. On the palate it gives a distinctive tasting experience: full-bodied and intense, with lingering suggestions of peat, smoke and pepper.', NULL, NULL, NULL, NULL),
(293, 'en', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old has been distilled in the same way for almost 75 years. Its barley malt is dried over a peat fire, using peat exclusively from Islay, which gives Laphroaig its distinctive flavour. The result is a full-bodied whisky with a smoky taste and surprising sweetness.', NULL, NULL, NULL, NULL),
(294, 'en', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old is a peated single malt Scotch whisky aged for at least 16 years in ex-bourbon casks, a benchmark for millions of enthusiasts worldwide. In this whisky you will find all the wild, untamed character of the Isle of Skye.', NULL, NULL, NULL, NULL),
(295, 'en', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel is a blend rooted in Japanese tradition, a highly accomplished combination of single malt and Japanese grain whiskies from the Yoichi and Miyahikyo distilleries. The blend rests in oak casks before bottling at 51.4%, with no age statement.', NULL, NULL, NULL, NULL),
(296, 'en', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label blends single malts from Speyside, Highland, Lowland and Island, each aged for at least 15 years. This distinctive blend includes Talisker, Linkwood, Cragganmore and Caol Ila, bringing out the full character and depth of Scottish single malts.', NULL, NULL, NULL, NULL),
