(284, 'es', 'RUM ZACAPA CENTENARIO 23', 'Originario de Guatemala, Ron Zacapa 23 Años combina rones jóvenes con rones envejecidos entre 6 y 23 años, afinados mediante un nuevo sistema de envejecimiento: la Solera dinámica. Las barricas de roble tostado que antes contuvieron bourbon o Sherry aportan un aroma suave y complejo de fruta madura, nuez moscada, cacao y regaliz. En boca es envolvente, cremoso y cálido, con aromas especiados de cacao y vainilla, un sutil recuerdo de madera quemada y un final agradablemente intenso y persistente.', NULL, NULL, 'Guatemala', NULL),
(285, 'es', 'RUM ZACAPA XO', 'Madura en barricas de roble que anteriormente han albergado robustos bourbons, delicados jerez y fino Pedro Ximenez, y finalmente en barricas de coñac francés. Se obtiene de una mezcla que incluye rones añejados hasta 25 años, de excepcional armonía y calidad inigualable. Intenso y suave, con notas de madera, fruta y ligeros toques de vainilla, almendras y chocolate.', NULL, NULL, 'Guatemala', NULL),
(286, 'es', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Envejecido durante 6 largos años exclusivamente en barricas de roble francés que antes contuvieron Bourbon Whisky, la crianza necesaria para la denominación XO. Très Vieux Rhum Agricole J. M expresa plenamente el estilo de los rones agrícolas de Martinica: aromas complejos y de múltiples matices, dulces y elegantes, un cuerpo pleno que se despliega lentamente en el paladar y un final largo, dulcemente especiado.', NULL, NULL, 'Martinica', NULL),
(287, 'es', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Ámbar intenso con vivos reflejos rubí. Los dulces aromas de dátiles, orejones, pasas y melocotones en almíbar se unen a intensas notas de canela y anís estrellado, con un toque de vainilla. En boca combina calidez y elegancia, fuerza y delicadeza, en un cuerpo estructurado y goloso con recuerdos frutales. El final, firme, seco y armonioso, cierra con cuero, tabaco y avellana.', NULL, NULL, 'Martinica', NULL),
(288, 'es', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Ron agrícola full proof, destilado en 1995 y embotellado en 2015 sin añadir agua ni filtrar. Ahumado, amaderado, potente y pleno, de larga persistencia.', NULL, NULL, NULL, NULL),
(289, 'es', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Mezcla de rones tradicionales destilados en columnas y alambiques de repaso: Diamond, Enmore, Versailles y Albione. Envejecidos en barricas ex-bourbon, dan un ron complejo, rico y especiado, a la vez meloso y aromático.', NULL, NULL, 'Guyana', NULL),
(290, 'es', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Símbolo del ron latino, se elabora a partir de una mezcla de melaza y jugo de caña de azúcar y se añeja durante 12 años en barricas de roble blanco. Los aromas son dulces y envolventes, predominando notas de frutas exóticas, miel y caramelo.', NULL, NULL, 'Venezuela', NULL),
(291, 'es', 'OBAN 14 Y.O.', 'Oban 14 Years Old es un dram clásico que encarna la historia de la destilería. Nariz rica y turbosa, con notas frutales; paladar denso y pleno, con especias y miel que dan paso a un ahumado seco. El final bastante largo deja recuerdos amaderados y un toque salino.', NULL, NULL, NULL, NULL),
(292, 'es', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'De color oro oscuro, este whisky ofrece un bouquet mineral entrelazado con algas en salmuera, humo de turba y un delicado aroma cítrico. En boca brinda una experiencia singular: un trago pleno e intenso con recuerdos de turba, humo y pimienta.', NULL, NULL, NULL, NULL),
(293, 'es', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old se destila del mismo modo desde hace casi 75 años. La malta de cebada se seca sobre fuego de turba procedente exclusivamente de Islay, que le da a Laphroaig su sabor particular. El resultado es un whisky con cuerpo, sabor ahumado y una dulzura sorprendente.', NULL, NULL, NULL, NULL),
(294, 'es', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old es un whisky escocés single malt con turba, envejecido al menos 16 años en barricas ex-bourbon, una referencia para millones de aficionados en todo el mundo. En él encontrará todo el carácter salvaje e indómito de la isla de Skye.', NULL, NULL, NULL, NULL),
(295, 'es', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel es un blend de tradición japonesa, una combinación muy lograda de whiskies single malt y whiskies de grano japoneses de las destilerías Yoichi y Miyahikyo. Reposa en barricas de roble antes de embotellarse al 51,4 %, sin declaración de edad.', NULL, NULL, NULL, NULL),
(296, 'es', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label combina single malts de Speyside, Highland, Lowland e Island, envejecidos al menos 15 años. Este blend único incluye Talisker, Linkwood, Cragganmore y Caol Ila para expresar todo el carácter y la profundidad de los single malts escoceses.', NULL, NULL, NULL, NULL),
