(23, 'fi', 'Marechiaro-trilogia', 'Paikallinen punainen katkarapu sitrusmarinadissa, appelsiinipohja, hasselpähkinärouhe; seepian musteella värjätty sämpylä, talon marinoima lohi, juustokreemi, nuorten salaatinlehtien sekoitus, sahramimajoneesi; tonnikalatataki, Cantaloupe-melonikerma.', NULL, NULL, NULL, NULL),
(24, 'fi', 'Ajaton klassikko', 'Talon mereneläväsalaatti.', NULL, NULL, NULL, NULL),
(25, 'fi', 'Pyhä ja maallinen', 'Suolatusta turskasta valmistettu morzello, calabrialainen pittaleipä.', NULL, NULL, NULL, NULL),
(26, 'fi', 'Klassikon kauneus', 'Pippurisia simpukoita, paahdettua leipää.', NULL, NULL, NULL, NULL),
(27, 'fi', 'Kotiseutumme', 'Lautanen calabrialaisia leikkeleitä, juustoja ja hilloja.', NULL, NULL, NULL, NULL),
(28, 'fi', 'Risotto', '“Magisa”-Carnaroliriisi Sibarista, paikallinen punainen katkarapu, sitruuna, timjami.', NULL, NULL, NULL, NULL),
(29, 'fi', 'Kun peruna kohtaa meren', 'Talon gnocchit Sila I.G.P. -perunoista, paikallinen punainen katkarapu, paistetut venus-simpukat, suolayrtti.', NULL, NULL, NULL, NULL),
(30, 'fi', 'Klassikoiden klassikko', '“Gentile”-spagetti, sardellit, calabrialainen aromikas yrttikimppu.', NULL, NULL, NULL, NULL),
(31, 'fi', 'Tyypillisesti calabrialainen', '“Monograno” Felicetti mezze maniche -pasta, herkkutatit, munakoisot, calabrialainen mustan sian makkara, savustettu ricotta.', NULL, NULL, NULL, NULL),
(32, 'fi', 'Kun kulinaarinen etsintä kohtaa kotiseudun', 'Matalassa lämpötilassa kypsennetty suolattu turska, Sila-peruna, Tropea-sipuli, Carolea-oliivijauhe, karkeasti jauhettu chili.', NULL, NULL, NULL, NULL),
(33, 'fi', 'Calabriasta tropiikkiin', 'Pinnalta paistettu tonnikala, kookos, minttu, lime, Gin Mare.', NULL, NULL, NULL, NULL),
(34, 'fi', 'Päivän saalis friteerattuna', 'Päivän saaliin saatavuuden mukaan.', NULL, NULL, NULL, NULL),
(35, 'fi', 'Friteerattua kalmaria ja katkarapuja', NULL, NULL, NULL, NULL, NULL),
(36, 'fi', 'Filee', 'Grillattu naudanfilee.', NULL, NULL, NULL, NULL),
