(39, 'fi', 'Calabrialainen caponatina', 'Munakoisot, kesäkurpitsat, paprikat, confit-kirsikkatomaatit, rapea leipälastu, hapanimelä sipuli.', NULL, NULL, NULL, NULL),
(40, 'fi', 'Sekoitettu kauden salaatti', NULL, NULL, NULL, NULL, NULL),
(41, 'fi', 'Calabrialainen salaatti', 'Tomaatit, ekstraneitsytoliiviöljy, Tropea-sipuli, oregano, basilika, chili.', NULL, NULL, NULL, NULL),
