(284, 'fi', 'RUM ZACAPA CENTENARIO 23', 'Guatemalalainen Ron Zacapa 23 Años yhdistää nuoria rommeja 6–23 vuotta kypsytettyihin rommeihin uudessa kypsytysjärjestelmässä: dynaamisessa Solerassa. Hiilletyt tammitynnyrit, joissa on aiemmin ollut bourbonia tai Sherryä, antavat pehmeän, moniulotteisen tuoksun, jossa on kypsää hedelmää, muskottipähkinää, kaakaota ja lakritsia. Maku on täyteläinen, kermainen ja lämmin, ja siinä on mausteista kaakaota ja vaniljaa, häivähdys palanutta puuta sekä miellyttävän intensiivinen, pitkä jälkimaku.', NULL, NULL, 'Guatemala', NULL),
(285, 'fi', 'RUM ZACAPA XO', 'Se kypsyy tammitynnyreissä, joissa on aiemmin ollut vahvoja bourboneja, herkkiä sherryjä ja hienoa Pedro Ximeneziä, ja lopuksi ranskalaisissa konjakkitynnyreissä. Se saadaan sekoituksesta, joka sisältää jopa 25 vuotta vanhoja rommeja, jotka ovat poikkeuksellisen harmonisia ja vertaansa vailla. Intensiivinen ja pehmeä, puun ja hedelmän sävyjä sekä kevyitä vaniljan, mantelin ja suklaan vivahteita.', NULL, NULL, 'Guatemala', NULL),
(286, 'fi', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Kypsytetty kuusi täyttä vuotta yksinomaan ranskalaisissa tammitynnyreissä, joissa on aiemmin ollut Bourbon Whiskyä, XO-luokituksen edellyttämällä tavalla. Très Vieux Rhum Agricole J. M ilmentää Martiniquen rhum agricole -rommien tyyliä: moniulotteiset, kerrokselliset mutta makeat ja elegantit aromit, suussa vähitellen avautuva täyteläisyys sekä pitkä, makean mausteinen jälkimaku.', NULL, NULL, 'Martinique', NULL),
(287, 'fi', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Syvä meripihkan väri ja eloisat rubiininpunaiset heijastukset. Makeat taatelin, kuivatun aprikoosin, rusinan ja siirappisen persikan aromit yhdistyvät intensiiviseen kaneliin ja tähtianikseen sekä hienovaraiseen vaniljaan. Maku yhdistää lämmön ja eleganssin, voiman ja hienostuneisuuden rakenteikkaaksi, herkulliseksi kokonaisuudeksi, jossa on hedelmäisiä vivahteita. Selkeä, kuiva ja tasapainoinen jälkimaku päättyy nahkaan, tupakkaan ja hasselpähkinään.', NULL, NULL, 'Martinique', NULL),
(288, 'fi', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Täysvahvuinen rhum agricole, tislattu vuonna 1995 ja pullotettu vuonna 2015 lisäämättä vettä tai suodattamatta. Savuinen, puinen, voimakas ja täyteläinen, pitkällä jälkimaulla.', NULL, NULL, NULL, NULL),
(289, 'fi', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Perinteisten, kolonni- ja pannutislattujen rommien sekoitus: Diamond, Enmore, Versailles ja Albione. Kypsytys entisissä bourbontynnyreissä tuottaa moniulotteisen, runsaan ja mausteisen rommin, joka on myös hunajainen ja aromaattinen.', NULL, NULL, 'Guyana', NULL),
(290, 'fi', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Latinalaisamerikkalaisen rommin symboli, se on valmistettu melassin ja sokeriruokomehun sekoituksesta ja kypsytetty 12 vuotta valkotammitynnyreissä. Aromit ovat makeita ja täyteläisiä, ja niissä vallitsee eksoottisia hedelmiä, hunajaa ja karamellia.', NULL, NULL, 'Venezuela', NULL),
(291, 'fi', 'OBAN 14 Y.O.', 'Oban 14 Years Old on klassinen dram, joka ilmentää tislaamon historiaa. Tuoksu on runsas ja turpeinen, hedelmäisin vivahtein; maku tiivis ja täyteläinen, mausteinen ja hunajainen, ja sitä seuraa kuiva savuisuus. Melko pitkä jälkimaku tarjoaa puun vivahteita ja aavistuksen suolaisuutta.', NULL, NULL, NULL, NULL),
(292, 'fi', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Tumman kultainen viski tarjoaa mineraalisen tuoksun, jossa on suolaliemessä olevaa merilevää, turvesavua ja hienovaraista sitrusta. Maku on ainutlaatuinen, täyteläinen ja intensiivinen, ja siinä viipyvät turpeen, savun ja pippurin vivahteet.', NULL, NULL, NULL, NULL),
(293, 'fi', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old on tislattu samalla tavalla lähes 75 vuotta. Ohramallas kuivataan turvetulen yllä; turve tulee yksinomaan Islaylta ja antaa Laphroaigille sen ominaisen maun. Tuloksena on täyteläinen viski, jossa on savuisuutta ja yllättävää makeutta.', NULL, NULL, NULL, NULL),
(294, 'fi', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old on turpeinen skotlantilainen single malt -viski, jota kypsytetään vähintään 16 vuotta entisissä bourbontynnyreissä; se on esikuva miljoonille harrastajille maailmassa. Tässä viskissä kohtaatte Skyen saaren villin ja kesyttämättömän luonteen.', NULL, NULL, NULL, NULL),
(295, 'fi', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel on japanilaiseen perinteeseen pohjautuva sekoitus, jossa yhdistyvät onnistuneesti Yoichin ja Miyahikyon tislaamojen single malt -viskit ja japanilaiset viljaviskit. Sekoitus lepää tammitynnyreissä ennen pullotusta 51,4 %:n vahvuisena, ilman ikämerkintää.', NULL, NULL, NULL, NULL),
(296, 'fi', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label yhdistää Speysiden, Highlandin, Lowlandin ja Islandin single malt -viskejä, joita on kypsytetty vähintään 15 vuotta. Tämä ainutlaatuinen sekoitus sisältää Taliskeria, Linkwoodia, Cragganmorea ja Caol Ilaa, tuoden esiin skotlantilaisten single maltien luonteen ja syvyyden.', NULL, NULL, NULL, NULL),
