(32, 'fr', 'Quand la recherche culinaire rencontre le terroir', 'Morue salée cuite à basse température, pomme de terre de la Sila, oignon de Tropea, poudre d’olive Carolea, piment grossièrement moulu.', NULL, NULL, NULL, NULL),
