(55, 'fr', 'SFIZIOSA', 'Mozzarella fior di latte, jambon cru de Parma D.O.P. Gran Riserva, affiné 24 mois, figues, oignon caramélisé, stracciatella, tomates datterino jaunes et rouges.', NULL, NULL, NULL, NULL),
(56, 'fr', 'PARMIGIANA 2.0', 'Passata de tomates datterino rouges “Migliarese”, mozzarella fior di latte, Parmigiano Reggiano D.O.P., affiné 24 mois, lamelles d’aubergine frites, coulis de tomates datterino rouges confites, ricotta fumée Crotonese D.O.P., basilic, huile d’olive vierge extra.', NULL, NULL, NULL, NULL),
(57, 'fr', 'MEDITERRANEA', 'Focaccia, mozzarella fior di latte en tranches, filets de thon, jambon cru de Parma D.O.P. Gran Riserva, affiné 24 mois, roquette, Parmigiano Reggiano D.O.P., affiné 24 mois, huile d’olive vierge extra.', NULL, NULL, NULL, NULL),
(58, 'fr', 'FIORITA', 'Mozzarella fior di latte, filets d’anchois de Méditerranée, tomates datterino jaunes, fleurs de courgette, huile d’olive vierge extra.', NULL, NULL, NULL, NULL),
(59, 'fr', 'ROMANA', 'Passata de tomates datterino rouges “Migliarese”, filets d’anchois de Méditerranée, fruits de câprier (“Cucunci”), huile d’olive vierge extra.', NULL, NULL, NULL, NULL),
(60, 'fr', 'BRONTE', 'Mozzarella fior di latte, jambon cru de Parma D.O.P. Gran Riserva, affiné 24 mois, mozzarella de bufflonne, tomates cerises, éclats de Pistacchio di Bronte D.O.P., basilic, huile d’olive vierge extra.', NULL, NULL, NULL, NULL),
(61, 'fr', 'CALZONE GHIOTTO', 'Mozzarella fior di latte, jambon cru de Parma D.O.P. Gran Riserva, affiné 24 mois, mozzarella de bufflonne, tomates cerises, roquette, Parmigiano Reggiano D.O.P., affiné 24 mois, huile d’olive vierge extra.', NULL, NULL, NULL, NULL),
(62, 'fr', 'MUFASA', 'Mozzarella fior di latte, jambon cru de Parma D.O.P. Gran Riserva, affiné 24 mois, mozzarella de bufflonne, tomates cerises, roquette, Parmigiano Reggiano D.O.P., affiné 24 mois, huile d’olive vierge extra.', NULL, NULL, NULL, NULL),
(63, 'fr', 'GOLOSA', 'Passata de tomates datterino rouges “Migliarese”, filets d’anchois de Méditerranée, friarielli (pousses de brocoli-rave), burrata, huile d’olive vierge extra.', NULL, NULL, NULL, NULL),
(64, 'fr', 'MONTANARA', 'Mozzarella fior di latte, mozzarella fumée, pancetta, pommes de terre rôties, caciocavallo di Ciminà, huile d’olive vierge extra.', NULL, NULL, NULL, NULL),
(65, 'fr', 'Saucisse et friarielli', 'Mozzarella fior di latte, saucisse de porc noir de Calabre, friarielli (pousses de brocoli-rave), huile d’olive vierge extra.', NULL, NULL, NULL, NULL),
(66, 'fr', 'Mer et montagne', 'Mozzarella fior di latte, crevettes, cèpes, Parmigiano Reggiano D.O.P., affiné 24 mois, huile d’olive vierge extra.', NULL, NULL, NULL, NULL),
