(284, 'fr', 'RUM ZACAPA CENTENARIO 23', 'Originaire du Guatemala, Ron Zacapa 23 Años assemble des rhums jeunes et des rhums âgés de 6 à 23 ans, affinés selon un nouveau système de vieillissement : la Solera dynamique. Les fûts de chêne toastés ayant contenu du bourbon ou du Sherry lui donnent un bouquet doux et complexe de fruits mûrs, de muscade, de cacao et de réglisse. En bouche, il est enveloppant, crémeux et chaleureux, avec des arômes épicés de cacao et de vanille, une subtile note de bois brûlé et une finale agréablement intense et persistante.', NULL, NULL, 'Guatemala', NULL),
(285, 'fr', 'RUM ZACAPA XO', 'Il vieillit en fûts de chêne ayant préalablement accueilli des bourbons robustes, des sherrys délicats et du fin Pedro Ximenez, et enfin en fûts de cognac français. Il est obtenu à partir d''un assemblage qui comprend des rhums âgés jusqu''à 25 ans, d''une harmonie exceptionnelle et d''une qualité inégalée. Intense et doux, avec des notes de bois, de fruits et de légères notes de vanille, d''amande et de chocolat.', NULL, NULL, 'Guatemala', NULL),
(286, 'fr', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Vieilli pendant 6 longues années exclusivement en fûts de chêne français ayant contenu du Bourbon Whisky, l’élevage nécessaire à la mention XO. Très Vieux Rhum Agricole J. M exprime pleinement le style des rhums agricoles de Martinique : des arômes complexes et nuancés, doux et élégants, un corps ample qui se déploie lentement en bouche et une finale longue, doucement épicée.', NULL, NULL, 'Martinique', NULL),
(287, 'fr', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Une robe ambrée intense aux reflets rubis vifs. Les arômes fruités et doux de dattes, d’abricots secs, de raisins secs et de pêches au sirop se mêlent à d’intenses notes de cannelle et de badiane, avec une touche de vanille. En bouche, chaleur et élégance, puissance et délicatesse s’unissent dans un corps structuré et gourmand aux échos fruités. La finale, affirmée, sèche et harmonieuse, s’achève sur le cuir, le tabac et la noisette.', NULL, NULL, 'Martinique', NULL),
(288, 'fr', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Rhum agricole full proof, distillé en 1995 et embouteillé en 2015 sans ajout d’eau ni filtration. Fumé, boisé, puissant et ample, d’une longue persistance.', NULL, NULL, NULL, NULL),
(289, 'fr', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Assemblage de rhums traditionnels distillés en alambics à colonne et à repasse : Diamond, Enmore, Versailles et Albione. Vieillis en fûts ayant contenu du bourbon, ils donnent un rhum complexe, riche et épicé, tout aussi miellé qu’aromatique.', NULL, NULL, 'Guyana', NULL),
(290, 'fr', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Symbole du rhum latin, il est produit à partir d''un assemblage de mélasse et de jus de canne à sucre et vieilli 12 ans en fûts de chêne blanc. Les arômes sont doux et enveloppants, avec des notes dominantes de fruits exotiques, de miel et de caramel.', NULL, NULL, 'Venezuela', NULL),
(291, 'fr', 'OBAN 14 Y.O.', 'Oban 14 Years Old est un dram classique qui incarne toute l’histoire de la distillerie. Le nez est riche et tourbé, aux notes fruitées ; la bouche, dense et ample, associe épices et miel avant un fumé sec. La finale assez longue laisse des échos boisés et une touche saline.', NULL, NULL, NULL, NULL),
(292, 'fr', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'D’un or foncé, ce whisky offre un bouquet minéral mêlé d’algues en saumure, de fumée de tourbe et d’un délicat arôme d’agrumes. En bouche, l’expérience est singulière : ample et intense, avec des échos de tourbe, de fumée et de poivre.', NULL, NULL, NULL, NULL),
(293, 'fr', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old est distillé de la même manière depuis près de 75 ans. Le malt d’orge est séché au feu de tourbe, provenant exclusivement d’Islay et donnant à Laphroaig sa saveur particulière. Le résultat est un whisky ample, au goût fumé et à la douceur surprenante.', NULL, NULL, NULL, NULL),
(294, 'fr', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old est un whisky écossais single malt tourbé, vieilli au moins 16 ans en fûts ayant contenu du bourbon, une référence pour des millions de passionnés dans le monde. Il révèle tout le caractère sauvage et indompté de l’île de Skye.', NULL, NULL, NULL, NULL),
(295, 'fr', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel est un blend ancré dans la tradition japonaise, un assemblage particulièrement réussi de whiskies single malt et de whiskies de grain japonais des distilleries Yoichi et Miyahikyo. Il repose en fûts de chêne avant d’être embouteillé à 51,4 %, sans mention d’âge.', NULL, NULL, NULL, NULL),
(296, 'fr', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label assemble des single malts du Speyside, de Highland, de Lowland et d’Island, vieillis au moins 15 ans. Ce blend unique réunit Talisker, Linkwood, Cragganmore et Caol Ila pour exprimer tout le caractère et la profondeur des single malts écossais.', NULL, NULL, NULL, NULL),
