(32, 'hu', 'Amikor a kulináris felfedezés találkozik a vidékkel', 'Alacsony hőmérsékleten készült sózott tőkehal, Sila-burgonya, Tropea-hagyma, Carolea-olívapor, durvára őrölt csili.', NULL, NULL, NULL, NULL),
