(55, 'hu', 'SFIZIOSA', 'Fior di latte mozzarella, 24 hónapig érlelt Parma D.O.P. Gran Riserva sonka, füge, karamellizált hagyma, stracciatella sajt, sárga és piros datterino paradicsom.', NULL, NULL, NULL, NULL),
(56, 'hu', 'PARMIGIANA 2.0', '„Migliarese” piros datterino paradicsompassata, fior di latte mozzarella, 24 hónapig érlelt Parmigiano Reggiano D.O.P., sült padlizsáncsíkok, konfitált piros datterino paradicsomcoulis, füstölt Crotonese D.O.P. ricotta, bazsalikom, extra szűz olívaolaj.', NULL, NULL, NULL, NULL),
(57, 'hu', 'MEDITERRANEA', 'Focaccia, szeletelt fior di latte mozzarella, tonhalfilé, 24 hónapig érlelt Parma D.O.P. Gran Riserva sonka, rukkola, 24 hónapig érlelt Parmigiano Reggiano D.O.P., extra szűz olívaolaj.', NULL, NULL, NULL, NULL),
(58, 'hu', 'FIORITA', 'Fior di latte mozzarella, mediterrán szardellafilé, sárga datterino paradicsom, cukkinivirág, extra szűz olívaolaj.', NULL, NULL, NULL, NULL),
(59, 'hu', 'ROMANA', '„Migliarese” piros datterino paradicsompassata, mediterrán szardellafilé, kapribogyótermés („Cucunci”), extra szűz olívaolaj.', NULL, NULL, NULL, NULL),
(60, 'hu', 'BRONTE', 'Fior di latte mozzarella, 24 hónapig érlelt Parma D.O.P. Gran Riserva sonka, bivalymozzarella, koktélparadicsom, aprított Pistacchio di Bronte D.O.P., bazsalikom, extra szűz olívaolaj.', NULL, NULL, NULL, NULL),
(61, 'hu', 'CALZONE GHIOTTO', 'Fior di latte mozzarella, 24 hónapig érlelt Parma D.O.P. Gran Riserva sonka, bivalymozzarella, koktélparadicsom, rukkola, 24 hónapig érlelt Parmigiano Reggiano D.O.P., extra szűz olívaolaj.', NULL, NULL, NULL, NULL),
(62, 'hu', 'MUFASA', 'Fior di latte mozzarella, 24 hónapig érlelt Parma D.O.P. Gran Riserva sonka, bivalymozzarella, koktélparadicsom, rukkola, 24 hónapig érlelt Parmigiano Reggiano D.O.P., extra szűz olívaolaj.', NULL, NULL, NULL, NULL),
(63, 'hu', 'GOLOSA', '„Migliarese” piros datterino paradicsompassata, mediterrán szardellafilé, friarielli (olasz tarlórépa-zöld), burrata, extra szűz olívaolaj.', NULL, NULL, NULL, NULL),
(64, 'hu', 'MONTANARA', 'Fior di latte mozzarella, füstölt mozzarella, pancetta, sült burgonya, caciocavallo di Ciminà, extra szűz olívaolaj.', NULL, NULL, NULL, NULL),
(65, 'hu', 'Kolbász és friarielli', 'Fior di latte mozzarella, calabriai fekete sertésből készült kolbász, friarielli (olasz tarlórépa-zöld), extra szűz olívaolaj.', NULL, NULL, NULL, NULL),
