(284, 'hu', 'RUM ZACAPA CENTENARIO 23', 'A guatemalai Ron Zacapa 23 Años fiatal rumokat és 6–23 évig érlelt rumokat egyesít egy új érlelési rendszerben: a dinamikus Solerában. A korábban bourbont vagy Sherryt tartalmazó kiégetett tölgyfahordók lágy, összetett illatot adnak, érett gyümölcsök, szerecsendió, kakaó és édesgyökér jegyeivel. Ízében selymesen körülölelő, krémes és meleg, fűszeres kakaó- és vaníliaaromával, az égetett fa finom emlékével és kellemesen intenzív, tartós lecsengéssel.', NULL, NULL, 'Guatemala', NULL),
(285, 'hu', 'RUM ZACAPA XO', 'Tölgyfahordókban érlelődik, amelyek korábban karakteres bourbonokat, finom sherryket és nemes Pedro Ximenezt tartalmaztak, végül francia konyakhordókban kapja meg végső érlelését. Egy olyan keverékből nyerik, amely akár 25 évig érlelt rumokat tartalmaz, kivételes harmóniával és páratlan minőséggel. Intenzív és lágy, fás és gyümölcsös jegyekkel, valamint vanília, mandula és csokoládé finom árnyalataival.', NULL, NULL, 'Guatemala', NULL),
(286, 'hu', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Hat teljes évig érlelik kizárólag francia tölgyfahordókban, amelyek korábban Bourbon Whiskyt tartalmaztak; ez az érlelés szükséges az XO megjelöléshez. A Très Vieux Rhum Agricole J. M a martinique-i rhum agricole-ok stílusát testesíti meg: összetett, rétegzett, mégis édes és elegáns aromák, a szájban lassan kibontakozó telt test és hosszú, édesen fűszeres lecsengés.', NULL, NULL, 'Martinique', NULL),
(287, 'hu', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Mély borostyánszín élénk rubinos reflexekkel. A datolya, aszalt sárgabarack, mazsola és szirupos őszibarack édes aromái intenzív fahéjjal, csillagánizzsal és finom vaníliával fonódnak össze. Ízében melegség és elegancia, erő és finomság egyesül egy határozott szerkezetű, zamatos, gyümölcsös testben. A markáns, száraz és harmonikus lecsengést bőr, dohány és mogyoró zárja.', NULL, NULL, 'Martinique', NULL),
(288, 'hu', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Teljes erősségű rhum agricole, 1995-ben lepárolva, 2015-ben víz hozzáadása és szűrés nélkül palackozva. Füstös, fás, erőteljes és telt, hosszú lecsengéssel.', NULL, NULL, NULL, NULL),
(289, 'hu', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Oszlopos és üstös lepárlással készült hagyományos rumok házasítása: Diamond, Enmore, Versailles és Albione. Ex-bourbon hordókban érlelve összetett, gazdag és fűszeres, ugyanakkor mézes és aromás rum születik.', NULL, NULL, 'Guyana', NULL),
(290, 'hu', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'A latin rum jelképe, melasz és cukornádlé keverékéből készül, és 12 évig érlelik fehér tölgyfahordóban. Illatai édesek és körülölelők, egzotikus gyümölcsök, méz és karamell jegyei uralkodnak.', NULL, NULL, 'Venezuela', NULL),
(291, 'hu', 'OBAN 14 Y.O.', 'Az Oban 14 Years Old klasszikus dram, amely a lepárló történetét testesíti meg. Illata gazdag és tőzeges, gyümölcsös jegyekkel; íze sűrű és telt, fűszerrel és mézzel, amelyet száraz füst követ. Meglehetősen hosszú lecsengése fás emlékeket és finom sósságot hagy.', NULL, NULL, NULL, NULL),
(292, 'hu', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Ez a sötétarany whisky ásványos illatot kínál, sós lében ázó tengeri alga, tőzegfüst és finom citrus jegyeivel. Ízében egyedülálló élményt ad: testes és intenzív korty, tőzeges, füstös és borsos emlékekkel.', NULL, NULL, NULL, NULL),
(293, 'hu', 'LAPHROAIG 10 Y.O.', 'A Laphroaig 10 Years Oldot közel 75 éve ugyanúgy párolják le. Az árpamalátát tőzegtűz felett szárítják; a tőzeg kizárólag Islay szigetéről származik, és ez adja a Laphroaig sajátos ízét. Az eredmény testes whisky, füstös ízzel és meglepő édességgel.', NULL, NULL, NULL, NULL),
(294, 'hu', 'LAGAVULIN 16 Y.O.', 'A Lagavulin 16 Years Old tőzeges skót single malt whisky, legalább 16 évig ex-bourbon hordókban érlelve, világszerte rajongók millióinak mércéje. Ebben a whiskyben Skye szigetének teljes vad, zabolátlan karakterét találja.', NULL, NULL, NULL, NULL),
(295, 'hu', 'NIKKA FROM THE BARREL', 'A Nikka Whisky From The Barrel a japán hagyományokra épülő blend, a Yoichi és Miyahikyo lepárlók single malt és japán gabonaviskyjeinek különösen sikerült ötvözete. A keverék tölgyfahordókban pihen, majd 51,4 %-on palackozzák, kormegjelölés nélkül.', NULL, NULL, NULL, NULL),
(296, 'hu', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'A Johnnie Walker Green Label legalább 15 évig érlelt Speyside, Highland, Lowland és Island single maltokat házasít. Ez az egyedi blend a Talisker, Linkwood, Cragganmore és Caol Ila whiskyjeit tartalmazza, a skót single maltok teljes karakterét és mélységét kínálva.', NULL, NULL, NULL, NULL),
