(23, 'nl', 'De Marechiaro-trilogie', 'Lokale rode garnaal in citrusmarinade, sinaasappelbasis, gehakte hazelnoten; broodje met inktvisinkt, huisgemarineerde zalm, kaascrème, gemengde jonge sla, saffraanmayonaise; tonijntataki, Cantaloupemeloencrème.', NULL, NULL, NULL, NULL),
