(56, 'nl', 'PARMIGIANA 2.0', 'Passata van rode datterinotomaten “Migliarese”, fior di latte-mozzarella, Parmigiano Reggiano D.O.P., 24 maanden gerijpt, gefrituurde auberginereepjes, coulis van gekonfijte rode datterinotomaten, gerookte ricotta Crotonese D.O.P., basilicum, extra vierge olijfolie.', NULL, NULL, NULL, NULL),
