(283, 'nl', 'Citroenthee', NULL, NULL, NULL, NULL, NULL),
(284, 'nl', 'RUM ZACAPA CENTENARIO 23', 'Ron Zacapa 23 Años uit Guatemala combineert jonge rum met rum die 6 tot 23 jaar heeft gerijpt, volgens een nieuw rijpingssysteem: de dynamische Solera. Gebrande eikenhouten vaten waarin eerder bourbon of Sherry zat, geven de rum een zacht, complex bouquet van rijp fruit, nootmuskaat, cacao en zoethout. In de mond is hij omhullend, romig en warm, met kruidige cacao- en vanillearoma’s, een subtiele toets van gebrand hout en een aangenaam intense, aanhoudende afdronk.', NULL, NULL, 'Guatemala', NULL),
(285, 'nl', 'RUM ZACAPA XO', 'Hij rijpt in eikenhouten vaten waar voorheen robuuste bourbons, delicate sherry''s en fijne Pedro Ximenez in hebben gezeten, en ten slotte in Franse cognacvaten. Hij wordt verkregen uit een blend van rum die tot 25 jaar oud is, van uitzonderlijke harmonie en ongeëvenaarde kwaliteit. Intens en zacht, met tonen van hout, fruit en lichte hints van vanille, amandelen en chocolade.', NULL, NULL, 'Guatemala', NULL),
(286, 'nl', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Zes volle jaren gerijpt in uitsluitend Franse eikenhouten vaten die eerder Bourbon Whisky bevatten, de rijping die nodig is voor de XO-classificatie. Très Vieux Rhum Agricole J. M belichaamt de stijl van de rhums agricoles uit Martinique: complexe, gelaagde maar zoete en elegante aroma’s, een volle body die zich langzaam in de mond ontvouwt en een lange, zoet-kruidige afdronk.', NULL, NULL, 'Martinique', NULL),
(287, 'nl', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Diep amber met levendige robijnrode schitteringen. Zoete fruitaroma’s van dadels, gedroogde abrikozen, rozijnen en perziken op siroop mengen zich met intense kaneel en steranijs en een vleugje vanille. In de mond verenigt hij warmte en elegantie, kracht en finesse, in een gestructureerde, weelderige body met fruitige toetsen. De uitgesproken, droge en harmonieuze afdronk eindigt met leer, tabak en hazelnoot.', NULL, NULL, 'Martinique', NULL),
(288, 'nl', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Rhum agricole op volle sterkte, gedistilleerd in 1995 en gebotteld in 2015 zonder verdunning of filtratie. Rokerig, houtachtig, krachtig en vol, met een lange afdronk.', NULL, NULL, NULL, NULL),
(289, 'nl', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Een blend van traditionele rum uit kolom- en potdistillatie: Diamond, Enmore, Versailles en Albione. Gerijpt in ex-bourbonvaten voor een complexe, rijke en kruidige rum, tegelijk honingachtig en aromatisch.', NULL, NULL, 'Guyana', NULL),
(290, 'nl', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Als symbool van Latijns-Amerikaanse rum wordt hij gemaakt uit een mengsel van melasse en suikerrietsap en wordt gedurende 12 jaar gerijpt in witte eikenhouten vaten. De aroma''s zijn zoet en omhullend, met overheersende tonen van exotisch fruit, honing en karamel.', NULL, NULL, 'Venezuela', NULL),
(291, 'nl', 'OBAN 14 Y.O.', 'Oban 14 Years Old is een klassieke dram die de geschiedenis van de distilleerderij belichaamt. Een rijk, turfachtig bouquet met fruittonen; in de mond dicht en vol, met kruiden en honing gevolgd door droge rook. De vrij lange afdronk laat houttonen en een vleugje ziltigheid achter.', NULL, NULL, NULL, NULL),
(292, 'nl', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Deze donker gouden whisky biedt een mineraal bouquet met zeewier in pekel, turfrook en een subtiel citrusaroma. In de mond geeft hij een bijzondere smaakervaring: vol en intens, met herinneringen aan turf, rook en peper.', NULL, NULL, NULL, NULL),
(293, 'nl', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old wordt al bijna 75 jaar op dezelfde wijze gedistilleerd. De gerstemout droogt boven een turfvuur; de turf komt uitsluitend van Islay en geeft Laphroaig zijn kenmerkende smaak. Het resultaat is een volle whisky met een rokerige smaak en verrassende zoetheid.', NULL, NULL, NULL, NULL),
(294, 'nl', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old is een geturfde Schotse single malt whisky, minstens 16 jaar gerijpt in ex-bourbonvaten en een maatstaf voor miljoenen liefhebbers wereldwijd. In deze whisky vindt u het wilde, ongetemde karakter van het eiland Skye.', NULL, NULL, NULL, NULL),
(295, 'nl', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel is een blend geworteld in de Japanse traditie, een bijzonder geslaagde combinatie van single malt en Japanse graanwhisky’s uit Yoichi en Miyahikyo. De blend rust in eikenhouten vaten vóór botteling op 51,4 % en heeft geen leeftijdsaanduiding.', NULL, NULL, NULL, NULL),
(296, 'nl', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label combineert single malts uit Speyside, Highland, Lowland en Island, minstens 15 jaar gerijpt. Deze unieke blend bevat Talisker, Linkwood, Cragganmore en Caol Ila en toont het volle karakter en de diepte van Schotse single malts.', NULL, NULL, NULL, NULL),
