(23, 'no', 'Marechiaro-trilogien', 'Lokal rød reke marinert i sitrus, appelsinbase, hakkede hasselnøtter; brød med sepia-blekk, husmarinert laks, ostekrem, blandede unge salatblader, safranmajones; tunfisktataki, Cantaloupemelonkrem.', NULL, NULL, NULL, NULL),
(24, 'no', 'Den tidløse klassikeren', 'Hjemmelaget sjømatsalat.', NULL, NULL, NULL, NULL),
(25, 'no', 'Hellig og profant', 'Morzello av saltet torsk, kalabrisk pittabrød.', NULL, NULL, NULL, NULL),
