(29, 'no', 'Når poteten møter havet', 'Hjemmelagde gnocchi av Sila I.G.P.-poteter, lokal rød reke, sauterte venusmuslinger, salturt.', NULL, NULL, NULL, NULL),
(30, 'no', 'Klassikernes klassiker', 'Spaghetti «Gentile», ansjos, kalabrisk aromatisk urtebukett.', NULL, NULL, NULL, NULL),
(31, 'no', 'Typisk kalabrisk', 'Mezze maniche «Monograno» Felicetti, steinsopp, auberginer, pølse av svart gris fra Calabria, røkt ricotta.', NULL, NULL, NULL, NULL),
(32, 'no', 'Når kulinarisk utforskning møter vår hjemstavn', 'Saltet torsk tilberedt ved lav temperatur, Sila-potet, Tropea-løk, Carolea-olivenpulver, grovmalt chili.', NULL, NULL, NULL, NULL),
