(56, 'no', 'PARMIGIANA 2.0', 'Passata av røde datterinotomater «Migliarese», fior di latte-mozzarella, Parmigiano Reggiano D.O.P., modnet i 24 måneder, friterte auberginestrimler, coulis av konfiterte røde datterinotomater, røkt ricotta Crotonese D.O.P., basilikum, extra virgin olivenolje.', NULL, NULL, NULL, NULL),
(57, 'no', 'MEDITERRANEA', 'Focaccia, fior di latte-mozzarella i skiver, tunfiskfileter, Parma D.O.P. Gran Riserva-skinke, modnet i 24 måneder, ruccola, Parmigiano Reggiano D.O.P., modnet i 24 måneder, extra virgin olivenolje.', NULL, NULL, NULL, NULL),
