(284, 'no', 'RUM ZACAPA CENTENARIO 23', 'Ron Zacapa 23 Años fra Guatemala forener ung rom med rom lagret i 6 til 23 år, modnet etter et nytt lagringssystem: dynamisk Solera. Brente eikefat som tidligere inneholdt bourbon eller Sherry, gir en myk, kompleks duft av moden frukt, muskat, kakao og lakris. På ganen er den omsluttende, kremet og varm, med krydrede toner av kakao og vanilje, et svakt hint av brent tre og en behagelig intens, vedvarende ettersmak.', NULL, NULL, 'Guatemala', NULL),
(285, 'no', 'RUM ZACAPA XO', 'Den modnes på eikefat som tidligere har inneholdt robuste bourbons, delikate sherryer og fine Pedro Ximenez, og til slutt på franske konjakkfat. Den er fremstilt av en blanding som inkluderer rom som er lagret opp til 25 år, av eksepsjonell harmoni og uovertruffen kvalitet. Intens og myk, med toner av tre, frukt og lette hint av vanilje, mandler og sjokolade.', NULL, NULL, 'Guatemala', NULL),
(286, 'no', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Lagret i 6 fulle år utelukkende på franske eikefat som tidligere inneholdt Bourbon Whisky, den modningen som kreves for XO-betegnelsen. Très Vieux Rhum Agricole J. M uttrykker stilen til Martiniques rhums agricoles: komplekse, lagdelte, men søte og elegante aromaer, en fyldig kropp som langsomt utfolder seg på ganen og en lang, søtt krydret ettersmak.', NULL, NULL, 'Martinique', NULL),
(287, 'no', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Dyp ravfarge med livlige rubinrøde skiftninger. Søte aromaer av dadler, tørkede aprikoser, rosiner og fersken i sirup møter intens kanel og stjerneanis samt et hint av vanilje. Smaken forener varme og eleganse, kraft og finesse i en strukturert, saftig kropp med fruktige ekkoer. Den tydelige, tørre og harmoniske ettersmaken avsluttes med lær, tobakk og hasselnøtt.', NULL, NULL, 'Martinique', NULL),
(288, 'no', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Rhum agricole på full styrke, destillert i 1995 og tappet i 2015 uten tilsetning av vann eller filtrering. Røykpreget, trepreget, kraftig og fyldig, med lang ettersmak.', NULL, NULL, NULL, NULL),
(289, 'no', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'En blanding av tradisjonell rom destillert i kolonne- og pot still-anlegg: Diamond, Enmore, Versailles og Albione. Lagring på ex-bourbonfat gir en kompleks, rik og krydret rom, samtidig honningpreget og aromatisk.', NULL, NULL, 'Guyana', NULL),
(290, 'no', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Som et symbol på latinamerikansk rom er den fremstilt av en blanding av melasse og sukkerrørjuice og lagret i 12 år på hvite eikefat. Aromaene er søte og omsluttende, med fremherskende toner av eksotisk frukt, honning og karamell.', NULL, NULL, 'Venezuela', NULL),
(291, 'no', 'OBAN 14 Y.O.', 'Oban 14 Years Old er en klassisk dram som rommer destilleriets historie. Duften er rik og torvpreget med frukttoner; smaken tett og fyldig, med krydder og honning etterfulgt av tørr røyk. Den ganske lange ettersmaken har trepreg og et hint av salt.', NULL, NULL, NULL, NULL),
(292, 'no', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Denne mørkt gylne whiskyen har en mineralsk duft med tang i saltlake, torvrøyk og en lett sitrusaroma. Smaken gir en særegen opplevelse: fyldig og intens, med ekko av torv, røyk og pepper.', NULL, NULL, NULL, NULL),
(293, 'no', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old har blitt destillert på samme måte i nesten 75 år. Byggmalten tørkes over torvild med torv utelukkende fra Islay, som gir Laphroaig sin særegne smak. Resultatet er en fyldig whisky med røyksmak og overraskende sødme.', NULL, NULL, NULL, NULL),
(294, 'no', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old er en torvpreget skotsk single malt whisky, lagret minst 16 år på ex-bourbonfat og en målestokk for millioner av entusiaster verden over. Her finner dere hele øya Skyes ville, utemmede karakter.', NULL, NULL, NULL, NULL),
(295, 'no', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel er en blend med røtter i japansk tradisjon, en svært vellykket kombinasjon av single malt og japansk grain whisky fra Yoichi og Miyahikyo. Blandingen hviler på eikefat før tapping ved 51,4 %, uten aldersangivelse.', NULL, NULL, NULL, NULL),
(296, 'no', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label forener single malts fra Speyside, Highland, Lowland og Island, lagret minst 15 år. Denne unike blenden inneholder Talisker, Linkwood, Cragganmore og Caol Ila og uttrykker skotske single malts fulle karakter og dybde.', NULL, NULL, NULL, NULL),
