(23, 'pl', 'Trylogia Marechiaro', 'Lokalna czerwona krewetka marynowana w cytrusach, podstawa z pomarańczy, kruszone orzechy laskowe; bułeczka z atramentem mątwy, łosoś marynowany na miejscu, krem serowy, mieszanka młodych liści, majonez szafranowy; tataki z tuńczyka, krem z melona Cantalupo.', NULL, NULL, NULL, NULL),
(24, 'pl', 'Ponadczasowa klasyka', 'Domowa sałatka z owoców morza.', NULL, NULL, NULL, NULL),
(25, 'pl', 'Sacrum i profanum', 'Morzello z solonego dorsza, kalabryjski chleb pitta.', NULL, NULL, NULL, NULL),
(26, 'pl', 'Piękno klasyki', 'Małże z pieprzem, grzanki.', NULL, NULL, NULL, NULL),
(27, 'pl', 'Nasza ziemia', 'Deska kalabryjskich wędlin, serów i konfitur.', NULL, NULL, NULL, NULL),
(28, 'pl', 'Risotto', 'Ryż Carnaroli z Sibari „Magisa”, lokalna czerwona krewetka, cytryna, tymianek.', NULL, NULL, NULL, NULL),
(29, 'pl', 'Gdy ziemniak zanurza się w morzu', 'Domowe gnocchi z ziemniaków Sila I.G.P., lokalna czerwona krewetka, podsmażane małże wenus, soliród.', NULL, NULL, NULL, NULL),
(30, 'pl', 'Klasyka klasyków', 'Spaghetti „Gentile”, sardele, kalabryjski bukiet aromatyczny.', NULL, NULL, NULL, NULL),
