(284, 'pl', 'RUM ZACAPA CENTENARIO 23', 'Ron Zacapa 23 Años z Gwatemali łączy młode rumy z rumami dojrzewającymi od 6 do 23 lat w nowym systemie: dynamicznej Solera. Wypalane beczki dębowe po bourbonie lub Sherry nadają mu delikatny, złożony aromat dojrzałych owoców, gałki muszkatołowej, kakao i lukrecji. Na podniebieniu jest otulający, kremowy i ciepły, z korzennymi aromatami kakao i wanilii, subtelnym wspomnieniem palonego drewna oraz przyjemnie intensywnym, trwałym finiszem.', NULL, NULL, 'Gwatemala', NULL),
(285, 'pl', 'RUM ZACAPA XO', 'Dojrzewa w dębowych beczkach, w których wcześniej gościły mocne bourbony, delikatne sherry i wyborne Pedro Ximenez, a na koniec we francuskich beczkach po koniaku. Otrzymywany jest z mieszanki składającej się z rumów dojrzewających do 25 lat, charakteryzujących się wyjątkową harmonią i niezrównaną jakością. Intensywny i miękki, z nutami drewna, owoców i lekkimi nutami wanilii, migdałów i czekolady.', NULL, NULL, 'Gwatemala', NULL),
(286, 'pl', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Dojrzewa przez 6 pełnych lat wyłącznie w beczkach z francuskiego dębu po Bourbon Whisky, co jest wymagane do oznaczenia XO. Très Vieux Rhum Agricole J. M oddaje styl rumów agricole z Martyniki: złożone, wielowarstwowe, a zarazem słodkie i eleganckie aromaty, pełne ciało stopniowo otulające podniebienie i długi, słodko-korzenny finisz.', NULL, NULL, 'Martynika', NULL),
(287, 'pl', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Intensywny bursztyn z żywymi rubinowymi refleksami. Słodkie aromaty daktyli, suszonych moreli, rodzynek i brzoskwiń w syropie łączą się z wyrazistymi nutami cynamonu i anyżu gwiazdkowatego oraz delikatną wanilią. Na podniebieniu ciepło i elegancja, siła i subtelność tworzą pełne, uporządkowane ciało z apetycznymi owocowymi akcentami. Zdecydowany, wytrawny i harmonijny finisz zamyka się nutami skóry, tytoniu i orzecha laskowego.', NULL, NULL, 'Martynika', NULL),
(288, 'pl', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Rum agricole full proof, destylowany w 1995 roku i butelkowany w 2015 bez dodawania wody ani filtracji. Dymny, drzewny, mocny i pełny, z długim finiszem.', NULL, NULL, NULL, NULL),
(289, 'pl', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Mieszanka tradycyjnych rumów destylowanych w kolumnach i alembikach: Diamond, Enmore, Versailles i Albione. Dojrzewanie w beczkach po bourbonie daje rum złożony, bogaty i korzenny, a zarazem miodowy i aromatyczny.', NULL, NULL, 'Gujana', NULL),
(290, 'pl', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Symbol latynoamerykańskiego rumu, produkowany z mieszanki melasy i soku z trzciny cukrowej, dojrzewający przez 12 lat w beczkach z białego dębu. Aromaty są słodkie i otulające, z przewagą nut egzotycznych owoców, miodu i karmelu.', NULL, NULL, 'Wenezuela', NULL),
(291, 'pl', 'OBAN 14 Y.O.', 'Oban 14 Years Old to klasyczny dram oddający historię destylarni. Aromat jest bogaty i torfowy, z nutami owoców; smak gęsty i pełny, z przyprawami i miodem, po których pojawia się suchy dym. Dość długi finisz pozostawia drzewne akcenty i delikatną słoność.', NULL, NULL, NULL, NULL),
(292, 'pl', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Whisky o ciemnozłotej barwie oferuje mineralny bukiet z nutami wodorostów w solance, dymu torfowego i delikatnych cytrusów. Na podniebieniu daje wyjątkowe doznania: pełny, intensywny smak ze wspomnieniem torfu, dymu i pieprzu.', NULL, NULL, NULL, NULL),
(293, 'pl', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old destylowany jest tak samo od niemal 75 lat. Słód jęczmienny suszy się nad ogniem z torfu pochodzącego wyłącznie z Islay, który nadaje Laphroaig charakterystyczny smak. Powstaje pełna whisky o dymnym smaku i zaskakującej słodyczy.', NULL, NULL, NULL, NULL),
(294, 'pl', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old to torfowa szkocka whisky single malt, dojrzewająca co najmniej 16 lat w beczkach po bourbonie, punkt odniesienia dla milionów miłośników na świecie. Odnajdą w niej Państwo cały dziki, nieokiełznany charakter wyspy Skye.', NULL, NULL, NULL, NULL),
(295, 'pl', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel to blend zakorzeniony w japońskiej tradycji, wyjątkowo udane połączenie whisky single malt i japońskich whisky zbożowych z destylarni Yoichi i Miyahikyo. Mieszanka odpoczywa w dębowych beczkach przed butelkowaniem z mocą 51,4 %, bez oznaczenia wieku.', NULL, NULL, NULL, NULL),
(296, 'pl', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label łączy single malty ze Speyside, Highland, Lowland i Island, dojrzewające co najmniej 15 lat. Ten wyjątkowy blend obejmuje Talisker, Linkwood, Cragganmore i Caol Ila, ukazując cały charakter i głębię szkockich single maltów.', NULL, NULL, NULL, NULL),
