(23, 'pt', 'A trilogia Marechiaro', 'Camarão-vermelho local marinado em citrinos, base de laranja, avelã picada; pão com tinta de choco, salmão marinado na casa, creme de queijo, mistura de folhas, maionese de açafrão; tataki de atum, creme de melão Cantalupo.', NULL, NULL, NULL, NULL),
(24, 'pt', 'O clássico intemporal', 'Salada de marisco caseira.', NULL, NULL, NULL, NULL),
(25, 'pt', 'Sagrado e profano', 'Morzello de bacalhau, pão pitta calabrês.', NULL, NULL, NULL, NULL),
(26, 'pt', 'A beleza do clássico', 'Mexilhões com pimenta, pão torrado.', NULL, NULL, NULL, NULL),
(27, 'pt', 'A nossa terra', 'Tábua de enchidos, queijos e compotas da Calábria.', NULL, NULL, NULL, NULL),
