(29, 'pt', 'Quando a batata mergulha no mar', 'Gnocchi caseiros de batata da Sila I.G.P., camarão-vermelho local, amêijoas salteadas, salicórnia.', NULL, NULL, NULL, NULL),
(30, 'pt', 'O clássico dos clássicos', 'Spaghetti “Gentile”, anchovas, bouquet aromático calabrês.', NULL, NULL, NULL, NULL),
(31, 'pt', 'Tipicamente calabrês', 'Mezze maniche “Monograno” Felicetti, cogumelos porcini, beringelas, salsicha de porco preto da Calábria, ricotta fumada.', NULL, NULL, NULL, NULL),
(32, 'pt', 'Quando a pesquisa culinária encontra o território', 'Bacalhau cozinhado a baixa temperatura, batata da Sila, cebola de Tropea, pó de azeitona Carolea, malagueta grosseiramente moída.', NULL, NULL, NULL, NULL),
(33, 'pt', 'Da Calábria aos trópicos', 'Atum selado, coco, hortelã, lima, Gin Mare.', NULL, NULL, NULL, NULL),
