(284, 'pt', 'RUM ZACAPA CENTENARIO 23', 'Originário da Guatemala, Ron Zacapa 23 Años combina runs jovens com runs envelhecidos entre 6 e 23 anos, afinados segundo um novo sistema de envelhecimento: o Solera dinâmico. As barricas de carvalho tostado que antes contiveram bourbon ou Sherry conferem-lhe um aroma suave e complexo de fruta madura, noz-moscada, cacau e alcaçuz. Na boca é envolvente, cremoso e quente, com aromas especiados de cacau e baunilha, um subtil toque de madeira queimada e um final agradavelmente intenso e persistente.', NULL, NULL, 'Guatemala', NULL),
(285, 'pt', 'RUM ZACAPA XO', 'Amadurece em barricas de carvalho que já abrigaram bourbons robustos, delicados xerez e o fino Pedro Ximenez e, finalmente, em barricas de conhaque francês. É obtido a partir de um blend que inclui runs envelhecidos até 25 anos, de excepcional harmonia e qualidade incomparável. Intenso e macio, com notas de madeira, frutas e leves notas de baunilha, amêndoas e chocolate.', NULL, NULL, 'Guatemala', NULL),
(286, 'pt', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Envelhecido durante 6 longos anos exclusivamente em barricas de carvalho francês que antes contiveram Bourbon Whisky, o estágio necessário para a designação XO. Très Vieux Rhum Agricole J. M expressa o estilo dos rhums agricoles da Martinica: aromas complexos e em camadas, doces e elegantes, um corpo pleno que se revela lentamente no paladar e um final longo, suavemente especiado.', NULL, NULL, 'Martinica', NULL),
(287, 'pt', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Âmbar intenso com vivos reflexos rubi. Aromas doces de tâmaras, damascos secos, passas e pêssegos em calda unem-se a notas intensas de canela e anis-estrelado, com um toque de baunilha. Na boca combina calor e elegância, força e delicadeza, num corpo estruturado e guloso com ecos frutados. O final firme, seco e harmonioso termina em couro, tabaco e avelã.', NULL, NULL, 'Martinica', NULL),
(288, 'pt', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Rhum agricole full proof, destilado em 1995 e engarrafado em 2015 sem adição de água nem filtração. Fumado, amadeirado, poderoso e encorpado, de longa persistência.', NULL, NULL, NULL, NULL),
(289, 'pt', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Mistura de runs tradicionais destilados em alambiques de coluna e de redestilação: Diamond, Enmore, Versailles e Albione. O envelhecimento em barricas ex-bourbon produz um rum complexo, rico e especiado, igualmente meloso e aromático.', NULL, NULL, 'Guiana', NULL),
(290, 'pt', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Símbolo do rum latino, é produzido a partir de uma mistura de melaço e caldo de cana-de-açúcar e envelhecido por 12 anos em barricas de carvalho branco. Os aromas são doces e envolventes, predominando notas de fruta exótica, mel e caramelo.', NULL, NULL, 'Venezuela', NULL),
(291, 'pt', 'OBAN 14 Y.O.', 'Oban 14 Years Old é um dram clássico que encarna a história da destilaria. No nariz é rico e turfado, com notas de fruta; na boca é denso e pleno, com especiarias e mel seguidos de um fumado seco. O final bastante longo revela ecos amadeirados e um toque salino.', NULL, NULL, NULL, NULL),
(292, 'pt', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'De cor ouro escuro, este whisky oferece um bouquet mineral entrelaçado com algas em salmoura, fumo de turfa e um delicado aroma cítrico. Na boca proporciona uma experiência singular: um gole encorpado e intenso, com ecos de turfa, fumo e pimenta.', NULL, NULL, NULL, NULL),
(293, 'pt', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old é destilado da mesma forma há quase 75 anos. O malte de cevada seca sobre fogo de turfa proveniente exclusivamente de Islay, que dá ao Laphroaig o seu sabor particular. O resultado é um whisky encorpado, de sabor fumado e doçura surpreendente.', NULL, NULL, NULL, NULL),
(294, 'pt', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old é um whisky escocês single malt turfado, envelhecido pelo menos 16 anos em barricas ex-bourbon, uma referência para milhões de apreciadores em todo o mundo. Nele encontrará todo o carácter selvagem e indomado da ilha de Skye.', NULL, NULL, NULL, NULL),
(295, 'pt', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel é um blend de tradição japonesa, uma combinação muito conseguida de whiskies single malt e whiskies de grão japoneses das destilarias Yoichi e Miyahikyo. Repousa em barricas de carvalho antes de ser engarrafado a 51,4 %, sem indicação de idade.', NULL, NULL, NULL, NULL),
(296, 'pt', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label combina single malts de Speyside, Highland, Lowland e Island, envelhecidos pelo menos 15 anos. Este blend único inclui Talisker, Linkwood, Cragganmore e Caol Ila, revelando todo o carácter e a profundidade dos single malts escoceses.', NULL, NULL, NULL, NULL),
