(23, 'ro', 'Trilogia Marechiaro', 'Crevete roșu local marinat în citrice, bază de portocală, alune de pădure mărunțite; chiflă cu cerneală de sepie, somon marinat în casă, cremă de brânză, mix de frunze, maioneză cu șofran; tataki de ton, cremă de pepene Cantalupo.', NULL, NULL, NULL, NULL),
(24, 'ro', 'Clasicul atemporal', 'Salată de fructe de mare preparată în casă.', NULL, NULL, NULL, NULL),
(25, 'ro', 'Sacru și profan', 'Morzello de cod sărat, pâine pitta calabreză.', NULL, NULL, NULL, NULL),
(26, 'ro', 'Frumusețea clasicului', 'Midii cu piper, pâine prăjită.', NULL, NULL, NULL, NULL),
(27, 'ro', 'Pământul nostru', 'Platou cu mezeluri, brânzeturi și dulcețuri din Calabria.', NULL, NULL, NULL, NULL),
(28, 'ro', 'Risottoul', 'Orez Carnaroli din Sibari „Magisa”, crevete roșu local, lămâie, cimbru.', NULL, NULL, NULL, NULL),
(29, 'ro', 'Când cartoful se cufundă în mare', 'Gnocchi de casă din cartofi de Sila I.G.P., crevete roșu local, scoici vongole veraci sotate, salicornia.', NULL, NULL, NULL, NULL),
(30, 'ro', 'Clasicul clasicelor', 'Spaghetti „Gentile”, anșoa, buchet aromatic calabrez.', NULL, NULL, NULL, NULL),
(31, 'ro', 'Tipic calabrez', 'Mezze maniche „Monograno” Felicetti, hribi, vinete, cârnați din porc negru de Calabria, ricotta afumată.', NULL, NULL, NULL, NULL),
(32, 'ro', 'Când explorarea culinară întâlnește terroir-ul', 'Cod sărat gătit la temperatură joasă, cartof de Sila, ceapă de Tropea, pudră de măsline Carolea, ardei iute măcinat grosier.', NULL, NULL, NULL, NULL),
(33, 'ro', 'Din Calabria la tropice', 'Ton rumenit rapid, cocos, mentă, lime, Gin Mare.', NULL, NULL, NULL, NULL),
(34, 'ro', 'Pește prăjit din captura zilei', 'În funcție de disponibilitatea capturii zilnice.', NULL, NULL, NULL, NULL),
