(53, 'ro', 'MARINARA', 'Passata de roșii datterino roșii „Migliarese”, usturoi, oregano, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(54, 'ro', 'MARGHERITA', 'Passata de roșii datterino roșii „Migliarese”, mozzarella fior di latte, busuioc, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(55, 'ro', 'SFIZIOSA', 'Mozzarella fior di latte, prosciutto crudo de Parma D.O.P. Gran Riserva, maturat 24 de luni, smochine, ceapă caramelizată, brânză stracciatella, roșii datterino galbene și roșii.', NULL, NULL, NULL, NULL),
(56, 'ro', 'PARMIGIANA 2.0', 'Passata de roșii datterino roșii „Migliarese”, mozzarella fior di latte, Parmigiano Reggiano D.O.P., maturat 24 de luni, fâșii de vinete prăjite, coulis de roșii datterino roșii confiate, ricotta afumată Crotonese D.O.P., busuioc, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(57, 'ro', 'MEDITERRANEA', 'Focaccia, mozzarella fior di latte feliată, fileuri de ton, prosciutto crudo de Parma D.O.P. Gran Riserva, maturat 24 de luni, rucola, Parmigiano Reggiano D.O.P., maturat 24 de luni, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(58, 'ro', 'FIORITA', 'Mozzarella fior di latte, fileuri de anșoa din Mediterana, roșii datterino galbene, flori de dovlecel, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(59, 'ro', 'ROMANA', 'Passata de roșii datterino roșii „Migliarese”, fileuri de anșoa din Mediterana, fructe de caper („Cucunci”), ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(60, 'ro', 'BRONTE', 'Mozzarella fior di latte, prosciutto crudo de Parma D.O.P. Gran Riserva, maturat 24 de luni, mozzarella de bivoliță, roșii cherry, Pistacchio di Bronte D.O.P. mărunțit, busuioc, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(61, 'ro', 'CALZONE GHIOTTO', 'Mozzarella fior di latte, prosciutto crudo de Parma D.O.P. Gran Riserva, maturat 24 de luni, mozzarella de bivoliță, roșii cherry, rucola, Parmigiano Reggiano D.O.P., maturat 24 de luni, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(62, 'ro', 'MUFASA', 'Mozzarella fior di latte, prosciutto crudo de Parma D.O.P. Gran Riserva, maturat 24 de luni, mozzarella de bivoliță, roșii cherry, rucola, Parmigiano Reggiano D.O.P., maturat 24 de luni, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(63, 'ro', 'GOLOSA', 'Passata de roșii datterino roșii „Migliarese”, fileuri de anșoa din Mediterana, friarielli (frunze de broccoli rabe), burrata, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(64, 'ro', 'MONTANARA', 'Mozzarella fior di latte, mozzarella afumată, pancetta, cartofi la cuptor, caciocavallo di Ciminà, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(65, 'ro', 'Cârnați și friarielli', 'Mozzarella fior di latte, cârnați din porc negru de Calabria, friarielli (frunze de broccoli rabe), ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(66, 'ro', 'Mare și munte', 'Mozzarella fior di latte, creveți, hribi, Parmigiano Reggiano D.O.P., maturat 24 de luni, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(67, 'ro', 'Vegetariană', 'Mozzarella fior di latte, dovlecei, vinete, ardei, rucola, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(68, 'ro', 'NAPOLI', 'Passata de roșii datterino roșii „Migliarese”, mozzarella fior di latte, fileuri de anșoa din Mediterana, măsline negre coapte, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(69, 'ro', 'CALABRESE', 'Passata de roșii datterino roșii „Migliarese”, mozzarella fior di latte, salam, măsline negre coapte, ardei iute, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(70, 'ro', 'PUGLIESE', 'Passata de roșii datterino roșii „Migliarese”, mozzarella fior di latte, ton, ceapă, măsline negre coapte, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
(71, 'ro', 'Patru brânzeturi', 'Mozzarella fior di latte, gorgonzola, Emmenthal, Parmigiano Reggiano D.O.P., maturat 24 de luni, ulei de măsline extravirgin.', NULL, NULL, NULL, NULL),
