(284, 'ro', 'RUM ZACAPA CENTENARIO 23', 'Originar din Guatemala, Ron Zacapa 23 Años combină romuri tinere cu romuri învechite între 6 și 23 de ani, maturate într-un nou sistem: Solera dinamic. Butoaiele de stejar arse în interior, care au conținut bourbon sau Sherry, îi conferă un buchet fin și complex de fructe coapte, nucșoară, cacao și lemn dulce. Pe palat este învăluitor, cremos și cald, cu arome condimentate de cacao și vanilie, o discretă notă de lemn ars și un final plăcut intens și persistent.', NULL, NULL, 'Guatemala', NULL),
(285, 'ro', 'RUM ZACAPA XO', 'Se maturează în butoaie de stejar care au găzduit anterior bourbonuri robuste, sherry delicat și Pedro Ximenez fin și, în sfârșit, în butoaie de coniac francez. Este obținut dintr-un cupaj de romuri învechite până la 25 de ani, de o armonie excepțională și o calitate fără egal. Intens și catifelat, cu note de lemn și fructe și accente delicate de vanilie, migdale și ciocolată.', NULL, NULL, 'Guatemala', NULL),
(286, 'ro', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Învechit timp de 6 ani întregi exclusiv în butoaie de stejar francez care au conținut Bourbon Whisky, maturarea necesară clasificării XO. Très Vieux Rhum Agricole J. M exprimă stilul romurilor agricole din Martinica: arome complexe și stratificate, dar dulci și elegante, un corp plin care se dezvăluie lent pe palat și un final lung, cu note dulci de condimente.', NULL, NULL, 'Martinica', NULL),
(287, 'ro', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Chihlimbar intens cu reflexe rubinii vii. Aromele dulci de curmale, caise uscate, stafide și piersici în sirop se împletesc cu note intense de scorțișoară și anason stelat, plus accente delicate de vanilie. Pe palat combină căldura și eleganța, forța și delicatețea, într-un corp structurat și generos, cu ecouri fructate. Finalul ferm, sec și armonios se încheie cu piele, tutun și alune de pădure.', NULL, NULL, 'Martinica', NULL),
(288, 'ro', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Rom agricole full proof, distilat în 1995 și îmbuteliat în 2015 fără diluare sau filtrare. Afumat, lemnos, puternic și plin, cu persistență îndelungată.', NULL, NULL, NULL, NULL),
(289, 'ro', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Cupaj de romuri tradiționale distilate în coloane și alambicuri de redistilare: Diamond, Enmore, Versailles și Albione. Învechirea în butoaie ex-bourbon oferă un rom complex, bogat și condimentat, totodată cu note de miere și aromat.', NULL, NULL, 'Guyana', NULL),
(290, 'ro', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Simbol al romului latin, este produs dintr-un amestec de melasă și suc de trestie de zahăr și învechit timp de 12 ani în butoaie de stejar alb. Aromele sunt dulci și învăluitoare, predominând note de fructe exotice, miere și caramel.', NULL, NULL, 'Venezuela', NULL),
(291, 'ro', 'OBAN 14 Y.O.', 'Oban 14 Years Old este un dram clasic ce întruchipează istoria distileriei. Buchet bogat, cu note de turbă și fructe; pe palat este dens și plin, cu condimente și miere urmate de fum sec. Finalul destul de lung lasă ecouri lemnoase și o notă salină.', NULL, NULL, NULL, NULL),
(292, 'ro', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'De un auriu închis, acest whisky oferă un buchet mineral împletit cu alge în saramură, fum de turbă și un delicat parfum de citrice. Pe palat propune o experiență aparte: plină și intensă, cu ecouri de turbă, fum și piper.', NULL, NULL, NULL, NULL),
(293, 'ro', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old este distilat în același mod de aproape 75 de ani. Malțul de orz se usucă la foc de turbă provenită exclusiv din Islay, care îi dă lui Laphroaig gustul distinctiv. Rezultatul este un whisky plin, cu gust afumat și dulceață surprinzătoare.', NULL, NULL, NULL, NULL),
(294, 'ro', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old este un whisky scoțian single malt cu note de turbă, învechit cel puțin 16 ani în butoaie ex-bourbon, un reper pentru milioane de pasionați din lume. În el veți regăsi întregul caracter sălbatic și neîmblânzit al insulei Skye.', NULL, NULL, NULL, NULL),
(295, 'ro', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel este un blend ancorat în tradiția japoneză, o combinație foarte reușită de whisky-uri single malt și whisky-uri japoneze de cereale din distileriile Yoichi și Miyahikyo. Cupajul se odihnește în butoaie de stejar înainte de îmbutelierea la 51,4 %, fără mențiune de vârstă.', NULL, NULL, NULL, NULL),
(296, 'ro', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label combină single malt-uri din Speyside, Highland, Lowland și Island, învechite cel puțin 15 ani. Acest blend unic include Talisker, Linkwood, Cragganmore și Caol Ila, exprimând întregul caracter și profunzimea single malt-urilor scoțiene.', NULL, NULL, NULL, NULL),
