(23, 'ru', 'Трилогия Marechiaro', 'Местная красная креветка в цитрусовом маринаде, апельсиновая основа, дроблёный фундук; булочка с чернилами каракатицы, лосось домашнего маринования, сырный крем, смесь салатных листьев, шафрановый майонез; татаки из тунца, крем из дыни Cantalupo.', NULL, NULL, NULL, NULL),
(24, 'ru', 'Вечная классика', 'Салат из морепродуктов домашнего приготовления.', NULL, NULL, NULL, NULL),
(25, 'ru', 'Священное и мирское', 'Морцелло из солёной трески, калабрийский хлеб pitta.', NULL, NULL, NULL, NULL),
