(27, 'ru', 'Наша земля', 'Доска калабрийских мясных деликатесов, сыров и конфитюров.', NULL, NULL, NULL, NULL),
(28, 'ru', 'Ризотто', 'Рис Carnaroli из Sibari «Magisa», местная красная креветка, лимон, тимьян.', NULL, NULL, NULL, NULL),
(29, 'ru', 'Когда картофель погружается в море', 'Домашние ньокки из картофеля Sila I.G.P., местная красная креветка, соте из моллюсков vongole veraci, солерос.', NULL, NULL, NULL, NULL),
(30, 'ru', 'Классика классики', 'Спагетти «Gentile», анчоусы, калабрийский ароматический букет.', NULL, NULL, NULL, NULL),
(31, 'ru', 'По-калабрийски', 'Паста mezze maniche «Monograno» Felicetti, белые грибы, баклажаны, колбаса из калабрийской чёрной свиньи, копчёная рикотта.', NULL, NULL, NULL, NULL),
(32, 'ru', 'Когда кулинарный поиск встречает родной край', 'Солёная треска, приготовленная при низкой температуре, картофель Sila, лук Tropea, порошок из оливок Carolea, перец чили грубого помола.', NULL, NULL, NULL, NULL),
(33, 'ru', 'Из Калабрии в тропики', 'Быстро обжаренный тунец, кокос, мята, лайм, Gin Mare.', NULL, NULL, NULL, NULL),
(34, 'ru', 'Жареный улов дня', 'В зависимости от наличия ежедневного улова.', NULL, NULL, NULL, NULL),
(35, 'ru', 'Жареные кальмары и креветки', NULL, NULL, NULL, NULL, NULL),
