(53, 'ru', 'MARINARA', 'Пассата из красных томатов datterino «Migliarese», чеснок, орегано, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(54, 'ru', 'MARGHERITA', 'Пассата из красных томатов datterino «Migliarese», моцарелла fior di latte, базилик, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(55, 'ru', 'SFIZIOSA', 'Моцарелла fior di latte, сыровяленая ветчина Parma D.O.P. Gran Riserva, выдержанная 24 месяца, инжир, карамелизированный лук, сыр stracciatella, жёлтые и красные томаты datterino.', NULL, NULL, NULL, NULL),
(56, 'ru', 'PARMIGIANA 2.0', 'Пассата из красных томатов datterino «Migliarese», моцарелла fior di latte, Parmigiano Reggiano D.O.P., выдержанный 24 месяца, полоски жареного баклажана, кули из красных томатов datterino конфи, копчёная рикотта Crotonese D.O.P., базилик, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(57, 'ru', 'MEDITERRANEA', 'Focaccia, моцарелла fior di latte ломтиками, филе тунца, сыровяленая ветчина Parma D.O.P. Gran Riserva, выдержанная 24 месяца, рукола, Parmigiano Reggiano D.O.P., выдержанный 24 месяца, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(58, 'ru', 'FIORITA', 'Моцарелла fior di latte, филе средиземноморских анчоусов, жёлтые томаты datterino, цветки цукини, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(59, 'ru', 'ROMANA', 'Пассата из красных томатов datterino «Migliarese», филе средиземноморских анчоусов, плоды каперсов («Cucunci»), оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(60, 'ru', 'BRONTE', 'Моцарелла fior di latte, сыровяленая ветчина Parma D.O.P. Gran Riserva, выдержанная 24 месяца, моцарелла из буйволиного молока, томаты черри, дроблёный Pistacchio di Bronte D.O.P., базилик, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(61, 'ru', 'CALZONE GHIOTTO', 'Моцарелла fior di latte, сыровяленая ветчина Parma D.O.P. Gran Riserva, выдержанная 24 месяца, моцарелла из буйволиного молока, томаты черри, рукола, Parmigiano Reggiano D.O.P., выдержанный 24 месяца, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(62, 'ru', 'MUFASA', 'Моцарелла fior di latte, сыровяленая ветчина Parma D.O.P. Gran Riserva, выдержанная 24 месяца, моцарелла из буйволиного молока, томаты черри, рукола, Parmigiano Reggiano D.O.P., выдержанный 24 месяца, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(63, 'ru', 'GOLOSA', 'Пассата из красных томатов datterino «Migliarese», филе средиземноморских анчоусов, friarielli (итальянская листовая капуста), буррата, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(64, 'ru', 'MONTANARA', 'Моцарелла fior di latte, копчёная моцарелла, панчетта, запечённый картофель, caciocavallo di Ciminà, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(65, 'ru', 'Колбаса и friarielli', 'Моцарелла fior di latte, колбаса из калабрийской чёрной свиньи, friarielli (итальянская листовая капуста), оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(66, 'ru', 'Море и горы', 'Моцарелла fior di latte, креветки, белые грибы, Parmigiano Reggiano D.O.P., выдержанный 24 месяца, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(67, 'ru', 'Вегетарианская', 'Моцарелла fior di latte, цукини, баклажаны, сладкий перец, рукола, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(68, 'ru', 'NAPOLI', 'Пассата из красных томатов datterino «Migliarese», моцарелла fior di latte, филе средиземноморских анчоусов, чёрные оливки, запечённые в печи, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(69, 'ru', 'CALABRESE', 'Пассата из красных томатов datterino «Migliarese», моцарелла fior di latte, салями, чёрные оливки, запечённые в печи, перец чили, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(70, 'ru', 'PUGLIESE', 'Пассата из красных томатов datterino «Migliarese», моцарелла fior di latte, тунец, лук, чёрные оливки, запечённые в печи, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(71, 'ru', 'Четыре сыра', 'Моцарелла fior di latte, gorgonzola, Emmenthal, Parmigiano Reggiano D.O.P., выдержанный 24 месяца, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(72, 'ru', 'Четыре сезона', 'Пассата из красных томатов datterino «Migliarese», моцарелла fior di latte, варёная ветчина, грибы, артишоки, чёрные оливки, запечённые в печи, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(73, 'ru', 'CAPRESE', 'Focaccia, моцарелла fior di latte, помидор бычье сердце, базилик, орегано, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
(74, 'ru', 'CAPRICCIOSA', 'Пассата из красных томатов datterino «Migliarese», моцарелла fior di latte, салями, грибы, артишоки, чёрные оливки, запечённые в печи, оливковое масло extra virgin.', NULL, NULL, NULL, NULL),
