(280, 'ru', 'Газированный напиток chinotto', NULL, NULL, NULL, NULL, NULL),
(281, 'ru', 'Campari Soda', NULL, NULL, NULL, NULL, NULL),
(282, 'ru', 'Персиковый чай', NULL, NULL, NULL, NULL, NULL),
(283, 'ru', 'Лимонный чай', NULL, NULL, NULL, NULL, NULL),
(284, 'ru', 'RUM ZACAPA CENTENARIO 23', 'Гватемальский Ron Zacapa 23 Años сочетает молодые ромы с ромами, выдержанными от 6 до 23 лет по новой системе: динамической Solera. Обожжённые дубовые бочки после бурбона или Sherry придают мягкий, сложный букет спелых фруктов, мускатного ореха, какао и лакрицы. Вкус обволакивающий, сливочный и тёплый, с пряными ароматами какао и ванили, тонким оттенком обожжённого дерева и приятно интенсивным, долгим послевкусием.', NULL, NULL, 'Гватемала', NULL),
(285, 'ru', 'RUM ZACAPA XO', 'Он созревает в дубовых бочках, в которых ранее выдерживались крепкие бурбоны, нежные шерри и изысканный Pedro Ximenez, и, наконец, в бочках из-под французского коньяка. Он получен из купажа, включающего ромы выдержкой до 25 лет, обладающие исключительной гармонией и непревзойденным качеством. Интенсивный и мягкий, с нотами древесины, фруктов и легкими оттенками ванили, миндаля и шоколада.', NULL, NULL, 'Гватемала', NULL),
(286, 'ru', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Выдержан шесть полных лет исключительно в бочках из французского дуба после Bourbon Whisky, как требуется для обозначения XO. Très Vieux Rhum Agricole J. M воплощает стиль ромов agricole Мартиники: сложные, многослойные, одновременно сладкие и элегантные ароматы, полное тело, постепенно раскрывающееся на нёбе, и долгое, сладко-пряное послевкусие.', NULL, NULL, 'Мартиника', NULL),
(287, 'ru', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Насыщенный янтарный цвет с яркими рубиновыми отблесками. Сладкие ароматы фиников, кураги, изюма и персиков в сиропе сочетаются с интенсивными нотами корицы и бадьяна и деликатной ванилью. Вкус соединяет тепло и элегантность, силу и тонкость в структурированном, сочном теле с фруктовыми оттенками. Выразительное, сухое и гармоничное послевкусие завершается кожей, табаком и фундуком.', NULL, NULL, 'Мартиника', NULL),
(288, 'ru', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Ром agricole полной крепости, дистиллированный в 1995 году и разлитый в 2015 без добавления воды или фильтрации. Дымный, древесный, мощный и полнотелый, с долгим послевкусием.', NULL, NULL, NULL, NULL),
(289, 'ru', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Купаж традиционных ромов, дистиллированных в колоннах и перегонных кубах: Diamond, Enmore, Versailles и Albione. Выдержка в бочках после бурбона даёт сложный, насыщенный и пряный ром, одновременно медовый и ароматный.', NULL, NULL, 'Гайана', NULL),
(290, 'ru', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Символ латинского рома, он производится из смеси патоки и сока сахарного тростника и выдерживается 12 лет в бочках из белого дуба. Ароматы сладкие и обволакивающие, с преобладающими нотами экзотических фруктов, меда и карамели.', NULL, NULL, 'Венесуэла', NULL),
(291, 'ru', 'OBAN 14 Y.O.', 'Oban 14 Years Old — классический драм, воплощающий историю винокурни. Аромат богатый и торфяной, с фруктовыми нотами; вкус плотный и полный, с пряностями и мёдом, за которыми следует сухой дым. Довольно долгое послевкусие оставляет древесные оттенки и лёгкую солоноватость.', NULL, NULL, NULL, NULL),
(292, 'ru', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Этот виски тёмно-золотого цвета раскрывает минеральный букет с водорослями в рассоле, торфяным дымом и деликатным цитрусовым ароматом. Во вкусе — особое впечатление: полнота и интенсивность с отголосками торфа, дыма и перца.', NULL, NULL, NULL, NULL),
(293, 'ru', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old дистиллируют одинаково уже почти 75 лет. Ячменный солод сушат над торфяным огнём; торф происходит исключительно с Islay и придаёт Laphroaig особый вкус. Результат — полнотелый виски с дымным вкусом и удивительной сладостью.', NULL, NULL, NULL, NULL),
(294, 'ru', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old — торфяной шотландский односолодовый виски, выдержанный не менее 16 лет в бочках после бурбона, эталон для миллионов ценителей в мире. В нём вы найдёте весь дикий, необузданный характер острова Skye.', NULL, NULL, NULL, NULL),
(295, 'ru', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel — купаж в японской традиции, удачное сочетание односолодовых и японских зерновых виски с винокурен Yoichi и Miyahikyo. Купаж отдыхает в дубовых бочках перед розливом с крепостью 51,4 %, без указания возраста.', NULL, NULL, NULL, NULL),
(296, 'ru', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label сочетает односолодовые виски из Speyside, Highland, Lowland и Island, выдержанные не менее 15 лет. Этот особый купаж включает Talisker, Linkwood, Cragganmore и Caol Ila, раскрывая весь характер и глубину шотландских односолодовых виски.', NULL, NULL, NULL, NULL),
