(56, 'sv', 'PARMIGIANA 2.0', 'Passata av röda datterinotomater ”Migliarese”, fior di latte-mozzarella, Parmigiano Reggiano D.O.P., lagrad 24 månader, friterade auberginestrimlor, coulis av konfiterade röda datterinotomater, rökt ricotta Crotonese D.O.P., basilika, extra jungfruolivolja.', NULL, NULL, NULL, NULL),
