(283, 'sv', 'Citronte', NULL, NULL, NULL, NULL, NULL),
(284, 'sv', 'RUM ZACAPA CENTENARIO 23', 'Ron Zacapa 23 Años från Guatemala förenar ung rom med rom lagrad i 6 till 23 år, förädlad med ett nytt lagringssystem: dynamisk Solera. Brända ekfat som tidigare innehöll bourbon eller Sherry ger en mjuk, komplex doft av mogen frukt, muskot, kakao och lakrits. I munnen är den omslutande, krämig och varm, med kryddiga toner av kakao och vanilj, en antydan till bränt trä och en behagligt intensiv, lång eftersmak.', NULL, NULL, 'Guatemala', NULL),
(285, 'sv', 'RUM ZACAPA XO', 'Den mognar på ekfat som tidigare tidigare har innehållit robusta bourbons, delikata sherryer och fina Pedro Ximenez, och slutligen på franska konjakfat. Den framställs av en blandning som inkluderar rom lagrad upp till 25 år, av exceptionell harmoni och oöverträffad kvalitet. Intensiv och mjuk, med toner av trä, frukt och lätta inslag av vanilj, mandel och choklad.', NULL, NULL, 'Guatemala', NULL),
(286, 'sv', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Lagrad i 6 hela år uteslutande på franska ekfat som tidigare innehöll Bourbon Whisky, den lagring som krävs för XO-beteckningen. Très Vieux Rhum Agricole J. M uttrycker stilen hos Martiniques rhums agricoles: komplexa, skiktade men söta och eleganta aromer, en fyllig kropp som långsamt breder ut sig i munnen och en lång, sött kryddig eftersmak.', NULL, NULL, 'Martinique', NULL),
(287, 'sv', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Djupt bärnstensfärgad med livliga rubinröda skiftningar. Söta aromer av dadlar, torkade aprikoser, russin och persikor i sockerlag möter intensiv kanel och stjärnanis samt en lätt ton av vanilj. Smaken förenar värme och elegans, kraft och finess i en strukturerad, läcker kropp med fruktiga ekon. Den tydliga, torra och harmoniska eftersmaken avslutas med läder, tobak och hasselnöt.', NULL, NULL, 'Martinique', NULL),
(288, 'sv', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Rhum agricole på full styrka, destillerad 1995 och buteljerad 2015 utan tillsats av vatten eller filtrering. Rökig, träig, kraftfull och fyllig, med lång eftersmak.', NULL, NULL, NULL, NULL),
(289, 'sv', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'En blandning av traditionell rom destillerad i kolonn- och pot still-pannor: Diamond, Enmore, Versailles och Albione. Lagring på ex-bourbonfat ger en komplex, rik och kryddig rom, samtidigt honungstonad och aromatisk.', NULL, NULL, 'Guyana', NULL),
(290, 'sv', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Symbol för latinsk rom, den är framställd av en blandning av melass och sockerrörsjuice och lagrad i 12 år på vita ekfat. Aromerna är söta och omslutande, med rådande toner av exotisk frukt, honung och karamell.', NULL, NULL, 'Venezuela', NULL),
(291, 'sv', 'OBAN 14 Y.O.', 'Oban 14 Years Old är en klassisk dram som förkroppsligar destilleriets historia. Doften är rik och torvig med frukttoner; smaken tät och fyllig, med kryddor och honung som följs av torr rök. Den ganska långa eftersmaken har träiga ekon och en lätt sälta.', NULL, NULL, NULL, NULL),
(292, 'sv', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Denna mörkt gyllene whisky har en mineralisk doft med toner av tång i saltlake, torvrök och en lätt citrusarom. Smaken erbjuder en särpräglad upplevelse: fyllig och intensiv, med ekon av torv, rök och peppar.', NULL, NULL, NULL, NULL),
(293, 'sv', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old har destillerats på samma sätt i nästan 75 år. Kornmalten torkas över en torveld med torv uteslutande från Islay, som ger Laphroaig dess särpräglade smak. Resultatet är en fyllig whisky med rökig smak och överraskande sötma.', NULL, NULL, NULL, NULL),
(294, 'sv', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old är en torvig skotsk single malt whisky, lagrad minst 16 år på ex-bourbonfat och en förebild för miljontals entusiaster världen över. Här finner ni hela den vilda, otämjda karaktären hos ön Skye.', NULL, NULL, NULL, NULL),
(295, 'sv', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel är en blend med rötter i japansk tradition, en mycket lyckad kombination av single malt och japansk grain whisky från Yoichi och Miyahikyo. Blandningen vilar på ekfat före buteljering vid 51,4 %, utan åldersangivelse.', NULL, NULL, NULL, NULL),
(296, 'sv', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label förenar single malt från Speyside, Highland, Lowland och Island, lagrade minst 15 år. Denna unika blend innehåller Talisker, Linkwood, Cragganmore och Caol Ila och lyfter fram skotska single malts fulla karaktär och djup.', NULL, NULL, NULL, NULL),
