(23, 'tr', 'Marechiaro üçlemesi', 'Narenciyede marine edilmiş yerel kırmızı karides, portakal tabanı, kırılmış fındık; mürekkep balığı mürekkepli sandviç ekmeği, mutfağımızda marine edilmiş somon, peynir kreması, karışık körpe salata yaprakları, safranlı mayonez; ton balığı tataki, Cantalupo kavun kreması.', NULL, NULL, NULL, NULL),
(24, 'tr', 'Zamansız klasik', 'Ev yapımı deniz ürünleri salatası.', NULL, NULL, NULL, NULL),
(25, 'tr', 'Kutsal ve dünyevi', 'Tuzlu morinadan morzello, Calabria usulü pitta ekmeği.', NULL, NULL, NULL, NULL),
(26, 'tr', 'Klasiğin güzelliği', 'Karabiberli midye, kızarmış ekmek.', NULL, NULL, NULL, NULL),
(27, 'tr', 'Toprağımız', 'Calabria şarküteri ürünleri, peynirleri ve reçellerinden oluşan tabak.', NULL, NULL, NULL, NULL),
(28, 'tr', 'Risotto', 'Sibari’den “Magisa” Carnaroli pirinci, yerel kırmızı karides, limon, kekik.', NULL, NULL, NULL, NULL),
(29, 'tr', 'Patates denizle buluştuğunda', 'Sila I.G.P. patatesinden ev yapımı gnocchi, yerel kırmızı karides, sotelenmiş vongole veraci deniz tarağı, deniz börülcesi.', NULL, NULL, NULL, NULL),
(30, 'tr', 'Klasiklerin klasiği', '“Gentile” spagetti, hamsi, Calabria aromatik ot buketi.', NULL, NULL, NULL, NULL),
(31, 'tr', 'Özgün Calabria lezzeti', '“Monograno” Felicetti mezze maniche makarna, porcini mantarı, patlıcan, Calabria siyah domuz sosisi, füme ricotta.', NULL, NULL, NULL, NULL),
(32, 'tr', 'Mutfak arayışı yöreyle buluştuğunda', 'Düşük sıcaklıkta pişirilmiş tuzlu morina, Sila patatesi, Tropea soğanı, Carolea zeytin tozu, iri çekilmiş acı biber.', NULL, NULL, NULL, NULL),
(33, 'tr', 'Calabria’dan tropiklere', 'Dışı mühürlenmiş ton balığı, Hindistan cevizi, nane, lime, Gin Mare.', NULL, NULL, NULL, NULL),
