(53, 'tr', 'MARINARA', '“Migliarese” kırmızı datterino domates passatası, sarımsak, kekik, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(54, 'tr', 'MARGHERITA', '“Migliarese” kırmızı datterino domates passatası, fior di latte mozzarella, fesleğen, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(55, 'tr', 'SFIZIOSA', 'Fior di latte mozzarella, 24 ay olgunlaştırılmış Parma D.O.P. Gran Riserva kuru jambon, incir, karamelize soğan, stracciatella peyniri, sarı ve kırmızı datterino domates.', NULL, NULL, NULL, NULL),
(56, 'tr', 'PARMIGIANA 2.0', '“Migliarese” kırmızı datterino domates passatası, fior di latte mozzarella, 24 ay olgunlaştırılmış Parmigiano Reggiano D.O.P., kızarmış patlıcan şeritleri, konfi kırmızı datterino domates coulis, füme Crotonese D.O.P. ricotta, fesleğen, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(57, 'tr', 'MEDITERRANEA', 'Focaccia, dilimlenmiş fior di latte mozzarella, ton balığı filetosu, 24 ay olgunlaştırılmış Parma D.O.P. Gran Riserva kuru jambon, roka, 24 ay olgunlaştırılmış Parmigiano Reggiano D.O.P., sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(58, 'tr', 'FIORITA', 'Fior di latte mozzarella, Akdeniz hamsisi filetosu, sarı datterino domates, kabak çiçeği, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(59, 'tr', 'ROMANA', '“Migliarese” kırmızı datterino domates passatası, Akdeniz hamsisi filetosu, kapari meyvesi (“Cucunci”), sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(60, 'tr', 'BRONTE', 'Fior di latte mozzarella, 24 ay olgunlaştırılmış Parma D.O.P. Gran Riserva kuru jambon, manda mozzarellası, çeri domates, kırılmış Pistacchio di Bronte D.O.P., fesleğen, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(61, 'tr', 'CALZONE GHIOTTO', 'Fior di latte mozzarella, 24 ay olgunlaştırılmış Parma D.O.P. Gran Riserva kuru jambon, manda mozzarellası, çeri domates, roka, 24 ay olgunlaştırılmış Parmigiano Reggiano D.O.P., sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(62, 'tr', 'MUFASA', 'Fior di latte mozzarella, 24 ay olgunlaştırılmış Parma D.O.P. Gran Riserva kuru jambon, manda mozzarellası, çeri domates, roka, 24 ay olgunlaştırılmış Parmigiano Reggiano D.O.P., sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(63, 'tr', 'GOLOSA', '“Migliarese” kırmızı datterino domates passatası, Akdeniz hamsisi filetosu, friarielli (İtalyan şalgam yeşilliği), burrata, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(64, 'tr', 'MONTANARA', 'Fior di latte mozzarella, füme mozzarella, pancetta (domuz göbeği), fırın patates, caciocavallo di Ciminà, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(65, 'tr', 'Sosis ve friarielli', 'Fior di latte mozzarella, Calabria siyah domuz sosisi, friarielli (İtalyan şalgam yeşilliği), sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(66, 'tr', 'Deniz ve dağlar', 'Fior di latte mozzarella, karides, porcini mantarı, 24 ay olgunlaştırılmış Parmigiano Reggiano D.O.P., sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(67, 'tr', 'Vejetaryen', 'Fior di latte mozzarella, kabak, patlıcan, biber, roka, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(68, 'tr', 'NAPOLI', '“Migliarese” kırmızı datterino domates passatası, fior di latte mozzarella, Akdeniz hamsisi filetosu, fırınlanmış siyah zeytin, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(69, 'tr', 'CALABRESE', '“Migliarese” kırmızı datterino domates passatası, fior di latte mozzarella, salam, fırınlanmış siyah zeytin, acı biber, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(70, 'tr', 'PUGLIESE', '“Migliarese” kırmızı datterino domates passatası, fior di latte mozzarella, ton balığı, soğan, fırınlanmış siyah zeytin, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(71, 'tr', 'Dört peynir', 'Fior di latte mozzarella, gorgonzola, Emmenthal, 24 ay olgunlaştırılmış Parmigiano Reggiano D.O.P., sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(72, 'tr', 'Dört mevsim', '“Migliarese” kırmızı datterino domates passatası, fior di latte mozzarella, pişmiş jambon, mantar, enginar, fırınlanmış siyah zeytin, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
(73, 'tr', 'CAPRESE', 'Focaccia, fior di latte mozzarella, öküz kalbi domates, fesleğen, kekik, sızma zeytinyağı.', NULL, NULL, NULL, NULL),
