(284, 'tr', 'RUM ZACAPA CENTENARIO 23', 'Guatemala kökenli Ron Zacapa 23 Años, genç romları 6 ile 23 yıl yıllandırılmış romlarla yeni bir olgunlaştırma sistemi olan dinamik Solera’da birleştirir. Önceden bourbon veya Sherry içermiş yakılmış meşe fıçılar, olgun meyve, muskat, kakao ve meyan kökü notalarıyla yumuşak ve katmanlı bir koku sunar. Damakta saran, kremsi ve sıcaktır; baharatlı kakao ve vanilya aromaları, hafif yanık odun izi ve hoş, yoğun, kalıcı bir bitiş taşır.', NULL, NULL, 'Guatemala', NULL),
(285, 'tr', 'RUM ZACAPA XO', 'Daha önce sağlam burbonlara, narin şerilere ve kaliteli Pedro Ximenez''e ev sahipliği yapan meşe fıçılarda ve son olarak Fransız konyak fıçılarında olgunlaşır. 25 yıla kadar yıllandırılmış romları içeren, olağanüstü uyum ve benzersiz kaliteye sahip bir karışımdan elde edilir. Yoğun ve yumuşak, odunsu, meyveli ve hafif vanilya, badem ve çikolata notalarıyla.', NULL, NULL, 'Guatemala', NULL),
(286, 'tr', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Önceden Bourbon Whisky içermiş Fransız meşe fıçılarında tam 6 yıl olgunlaştırılır; bu süreç XO sınıflandırması için gereklidir. Très Vieux Rhum Agricole J. M, Martinik rhum agricole tarzını yansıtır: karmaşık ve katmanlı, ancak tatlı ve zarif aromalar, damakta yavaşça açılan dolgun bir gövde ve uzun, tatlı baharatlı bir bitiş.', NULL, NULL, 'Martinik', NULL),
(287, 'tr', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Canlı yakut yansımalarıyla yoğun amber rengi. Hurma, kuru kayısı, kuru üzüm ve şuruplu şeftalinin tatlı aromaları, güçlü tarçın ve yıldız anason notaları ve hafif vanilyayla birleşir. Damakta sıcaklık ve zarafet, güç ve incelik; meyvemsi izler taşıyan yapılı, iştah açıcı bir gövdede buluşur. Belirgin, kuru ve uyumlu bitiş deri, tütün ve fındık tonlarıyla sonlanır.', NULL, NULL, 'Martinik', NULL),
(288, 'tr', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Tam derecesinde rhum agricole; 1995’te damıtılmış, 2015’te su eklenmeden ve filtre edilmeden şişelenmiştir. İsli, odunsu, güçlü ve dolgun, uzun bir bitişe sahiptir.', NULL, NULL, NULL, NULL),
(289, 'tr', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Kolon ve imbik yöntemiyle damıtılmış geleneksel romların harmanı: Diamond, Enmore, Versailles ve Albione. Eski bourbon fıçılarında olgunlaştırılarak karmaşık, zengin ve baharatlı; aynı zamanda ballı ve aromatik bir rom elde edilir.', NULL, NULL, 'Guyana', NULL),
(290, 'tr', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Latin Amerika romunun simgesi olan bu içki, melas ve şeker kamışı suyunun karışımından üretilip ak meşe fıçılarda 12 yıl dinlendirilir. Aromalar tatlı ve sarmalayıcı olup, egzotik meyve, bal ve karamel notaları hakimdir.', NULL, NULL, 'Venezuela', NULL),
(291, 'tr', 'OBAN 14 Y.O.', 'Oban 14 Years Old, damıtımevinin tarihini taşıyan klasik bir dramdır. Kokusu meyve notalarıyla zengin ve turbalı; damakta yoğun ve dolgundur, baharat ve balı kuru bir is izler. Oldukça uzun bitişte odunsu izler ve hafif bir tuzluluk belirir.', NULL, NULL, NULL, NULL),
(292, 'tr', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Koyu altın renkli bu viski; salamurada deniz yosunu, turba dumanı ve hafif narenciye aromasıyla örülen mineral bir koku sunar. Damakta özgün bir deneyim verir: dolgun ve yoğun bir yudum, turba, is ve biber izleri.', NULL, NULL, NULL, NULL),
(293, 'tr', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old neredeyse 75 yıldır aynı yöntemle damıtılır. Arpa maltı, yalnızca Islay’dan gelen turbanın ateşi üzerinde kurutulur; bu turba Laphroaig’e kendine özgü tadını verir. Sonuç, isli tada ve şaşırtıcı bir tatlılığa sahip dolgun bir viskidir.', NULL, NULL, NULL, NULL),
(294, 'tr', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old, eski bourbon fıçılarında en az 16 yıl olgunlaştırılmış turbalı bir İskoç single malt viskidir; dünyadaki milyonlarca meraklı için bir ölçüttür. Bu viskide Skye Adası’nın tüm vahşi ve evcilleşmemiş karakterini bulacaksınız.', NULL, NULL, NULL, NULL),
(295, 'tr', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel, Japon geleneğine dayanan bir harmandır; Yoichi ve Miyahikyo damıtımevlerinden single malt ve Japon tahıl viskilerinin çok başarılı birleşimidir. Harman, meşe fıçılarda dinlendirildikten sonra %51,4 alkol oranıyla, yaş belirtilmeden şişelenir.', NULL, NULL, NULL, NULL),
(296, 'tr', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label, Speyside, Highland, Lowland ve Island’dan en az 15 yıl olgunlaştırılmış single malt viskileri birleştirir. Talisker, Linkwood, Cragganmore ve Caol Ila içeren bu özgün harman, İskoç single maltlarının tüm karakterini ve derinliğini ortaya koyar.', NULL, NULL, NULL, NULL),
