(22, 'uk', 'Чорна тріска (аноплопома)', NULL, NULL, NULL, NULL, NULL),
(23, 'uk', 'Трилогія Marechiaro', 'Місцева червона креветка, маринована в цитрусових, апельсинова основа, подрібнений фундук; булочка з чорнилом каракатиці, лосось власного маринування, сирний крем, мікс салатного листя, шафрановий майонез; татакі з тунця, крем із дині Cantalupo.', NULL, NULL, NULL, NULL),
(24, 'uk', 'Невмируща класика', 'Салат із морепродуктів власного приготування.', NULL, NULL, NULL, NULL),
(25, 'uk', 'Сакральне і світське', 'Морцелло із солоної тріски, калабрійський хліб pitta.', NULL, NULL, NULL, NULL),
(26, 'uk', 'Краса класики', 'Мідії з перцем, підсмажений хліб.', NULL, NULL, NULL, NULL),
(27, 'uk', 'Наша земля', 'Дошка калабрійських м’ясних делікатесів, сирів і конфітюрів.', NULL, NULL, NULL, NULL),
(28, 'uk', 'Ризото', 'Рис Carnaroli із Sibari «Magisa», місцева червона креветка, лимон, чебрець.', NULL, NULL, NULL, NULL),
(29, 'uk', 'Коли картопля занурюється в море', 'Домашні ньокі з картоплі Sila I.G.P., місцева червона креветка, соте з молюсків vongole veraci, солерос.', NULL, NULL, NULL, NULL),
(30, 'uk', 'Класика класик', 'Спагеті «Gentile», анчоуси, калабрійський ароматичний букет.', NULL, NULL, NULL, NULL),
(31, 'uk', 'По-калабрійськи', 'Паста mezze maniche «Monograno» Felicetti, білі гриби, баклажани, ковбаса з калабрійської чорної свині, копчена рикота.', NULL, NULL, NULL, NULL),
(32, 'uk', 'Коли кулінарний пошук зустрічає рідний край', 'Солона тріска, приготована за низької температури, картопля Sila, цибуля Tropea, порошок з оливок Carolea, перець чилі грубого помелу.', NULL, NULL, NULL, NULL),
(33, 'uk', 'З Калабрії до тропіків', 'Швидко обсмажений тунець, кокос, м’ята, лайм, Gin Mare.', NULL, NULL, NULL, NULL),
(34, 'uk', 'Смажений улов дня', 'Залежно від наявності щоденного улову.', NULL, NULL, NULL, NULL),
(35, 'uk', 'Смажені кальмари та креветки', NULL, NULL, NULL, NULL, NULL),
(36, 'uk', 'Філе', 'Яловиче філе на грилі.', NULL, NULL, NULL, NULL),
(37, 'uk', 'Перший у класі', 'Стейк Fiorentina / Tomahawk.', NULL, NULL, NULL, NULL),
(38, 'uk', 'Запечена картопля з травами', NULL, NULL, NULL, NULL, NULL),
(39, 'uk', 'Калабрійська капонатіна', 'Баклажани, цукіні, солодкий перець, томати чері конфі, хрустка хлібна пластинка, кисло-солодка цибуля.', NULL, NULL, NULL, NULL),
(40, 'uk', 'Змішаний сезонний салат', NULL, NULL, NULL, NULL, NULL),
(41, 'uk', 'Калабрійський салат', 'Помідори, оливкова олія extra virgin, цибуля Tropea, орегано, базилік, перець чилі.', NULL, NULL, NULL, NULL),
(42, 'uk', 'Польова зелень по-селянськи', NULL, NULL, NULL, NULL, NULL),
(43, 'uk', 'Мільфей, крем шантільї, шоколад', NULL, NULL, NULL, NULL, NULL),
(44, 'uk', 'Мільфей, крем шантільї, червоні ягоди', NULL, NULL, NULL, NULL, NULL),
(45, 'uk', 'Чизкейк із рикоти з червоними ягодами', NULL, NULL, NULL, NULL, NULL),
(46, 'uk', 'Кавове тірамісу', NULL, NULL, NULL, NULL, NULL),
(47, 'uk', 'Теплий шоколадний фондан із морозивом fior di latte', NULL, NULL, NULL, NULL, NULL),
