(53, 'uk', 'MARINARA', 'Пасата з червоних томатів datterino «Migliarese», часник, орегано, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(54, 'uk', 'MARGHERITA', 'Пасата з червоних томатів datterino «Migliarese», моцарела fior di latte, базилік, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(55, 'uk', 'SFIZIOSA', 'Моцарела fior di latte, сиров’ялена шинка Parma D.O.P. Gran Riserva, витримана 24 місяці, інжир, карамелізована цибуля, сир stracciatella, жовті та червоні томати datterino.', NULL, NULL, NULL, NULL),
(56, 'uk', 'PARMIGIANA 2.0', 'Пасата з червоних томатів datterino «Migliarese», моцарела fior di latte, Parmigiano Reggiano D.O.P., витриманий 24 місяці, смужки смажених баклажанів, кулі з червоних томатів datterino конфі, копчена рикота Crotonese D.O.P., базилік, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(57, 'uk', 'MEDITERRANEA', 'Focaccia, моцарела fior di latte скибочками, філе тунця, сиров’ялена шинка Parma D.O.P. Gran Riserva, витримана 24 місяці, рукола, Parmigiano Reggiano D.O.P., витриманий 24 місяці, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(58, 'uk', 'FIORITA', 'Моцарела fior di latte, філе середземноморських анчоусів, жовті томати datterino, квіти цукіні, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(59, 'uk', 'ROMANA', 'Пасата з червоних томатів datterino «Migliarese», філе середземноморських анчоусів, плоди каперсів («Cucunci»), оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(60, 'uk', 'BRONTE', 'Моцарела fior di latte, сиров’ялена шинка Parma D.O.P. Gran Riserva, витримана 24 місяці, моцарела з буйволячого молока, томати чері, подрібнений Pistacchio di Bronte D.O.P., базилік, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(61, 'uk', 'CALZONE GHIOTTO', 'Моцарела fior di latte, сиров’ялена шинка Parma D.O.P. Gran Riserva, витримана 24 місяці, моцарела з буйволячого молока, томати чері, рукола, Parmigiano Reggiano D.O.P., витриманий 24 місяці, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(62, 'uk', 'MUFASA', 'Моцарела fior di latte, сиров’ялена шинка Parma D.O.P. Gran Riserva, витримана 24 місяці, моцарела з буйволячого молока, томати чері, рукола, Parmigiano Reggiano D.O.P., витриманий 24 місяці, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(63, 'uk', 'GOLOSA', 'Пасата з червоних томатів datterino «Migliarese», філе середземноморських анчоусів, friarielli (італійська листова капуста), бурата, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(64, 'uk', 'MONTANARA', 'Моцарела fior di latte, копчена моцарела, панчета, запечена картопля, caciocavallo di Ciminà, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(65, 'uk', 'Ковбаса та friarielli', 'Моцарела fior di latte, ковбаса з калабрійської чорної свині, friarielli (італійська листова капуста), оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(66, 'uk', 'Море й гори', 'Моцарела fior di latte, креветки, білі гриби, Parmigiano Reggiano D.O.P., витриманий 24 місяці, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(67, 'uk', 'Вегетаріанська', 'Моцарела fior di latte, цукіні, баклажани, солодкий перець, рукола, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(68, 'uk', 'NAPOLI', 'Пасата з червоних томатів datterino «Migliarese», моцарела fior di latte, філе середземноморських анчоусів, чорні оливки, запечені в печі, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(69, 'uk', 'CALABRESE', 'Пасата з червоних томатів datterino «Migliarese», моцарела fior di latte, салямі, чорні оливки, запечені в печі, перець чилі, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(70, 'uk', 'PUGLIESE', 'Пасата з червоних томатів datterino «Migliarese», моцарела fior di latte, тунець, цибуля, чорні оливки, запечені в печі, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(71, 'uk', 'Чотири сири', 'Моцарела fior di latte, gorgonzola, Emmenthal, Parmigiano Reggiano D.O.P., витриманий 24 місяці, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(72, 'uk', 'Чотири пори року', 'Пасата з червоних томатів datterino «Migliarese», моцарела fior di latte, варена шинка, гриби, артишоки, чорні оливки, запечені в печі, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(73, 'uk', 'CAPRESE', 'Focaccia, моцарела fior di latte, помідор бичаче серце, базилік, орегано, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
(74, 'uk', 'CAPRICCIOSA', 'Пасата з червоних томатів datterino «Migliarese», моцарела fior di latte, салямі, гриби, артишоки, чорні оливки, запечені в печі, оливкова олія extra virgin.', NULL, NULL, NULL, NULL),
