(283, 'uk', 'Лимонний чай', NULL, NULL, NULL, NULL, NULL),
(284, 'uk', 'RUM ZACAPA CENTENARIO 23', 'Гватемальський Ron Zacapa 23 Años поєднує молоді роми з ромами, витриманими від 6 до 23 років за новою системою: динамічною Solera. Обпалені дубові бочки після бурбону або Sherry надають м’який, складний букет стиглих фруктів, мускатного горіха, какао й лакриці. На піднебінні він обволікальний, вершковий і теплий, із пряними ароматами какао та ванілі, делікатним відтінком обпаленого дерева й приємно інтенсивним, тривалим післясмаком.', NULL, NULL, 'Гватемала', NULL),
(285, 'uk', 'RUM ZACAPA XO', 'Він дозріває в дубових бочках, які раніше містили міцні бурбони, делікатні хереси та вишуканий Pedro Ximenez, і, нарешті, у бочках для французького коньяку. Його отримують із купажу, який включає роми з витримкою до 25 років, виняткової гармонії та неперевершеної якості. Інтенсивний і м''який, з нотами дерева, фруктів і легкими відтінками ванілі, мигдалю і шоколаду.', NULL, NULL, 'Гватемала', NULL),
(286, 'uk', 'J.M. XO RUM TRÈS VIEUX AGRICOLE', 'Витриманий шість повних років виключно в бочках із французького дуба після Bourbon Whisky, як передбачено для позначення XO. Très Vieux Rhum Agricole J. M втілює стиль ромів agricole Мартиніки: складні, багатошарові, водночас солодкі й елегантні аромати, повне тіло, що повільно розкривається на піднебінні, і довгий, солодко-пряний післясмак.', NULL, NULL, 'Мартиніка', NULL),
(287, 'uk', 'J BALLY 7 Y.O. RUM VIEUX AGRICOLE', 'Насичений бурштиновий колір із живими рубіновими відблисками. Солодкі аромати фініків, кураги, родзинок і персиків у сиропі поєднуються з виразними нотами кориці та бадьяну й делікатною ваніллю. Смак єднає тепло та елегантність, силу й витонченість у структурованому, соковитому тілі з фруктовими відтінками. Виразний, сухий і гармонійний післясмак завершується шкірою, тютюном і фундуком.', NULL, NULL, 'Мартиніка', NULL),
(288, 'uk', 'DAMOISEAU RHUM VIEUX MILLESIME 1995', 'Ром agricole повної міцності, дистильований 1995 року й розлитий 2015 року без додавання води або фільтрації. Димний, деревний, потужний і повнотілий, із довгим післясмаком.', NULL, NULL, NULL, NULL),
(289, 'uk', 'RUM EL DORADO 21 Y.O. SPECIAL RESERVE', 'Купаж традиційних ромів, дистильованих у колонах і перегінних кубах: Diamond, Enmore, Versailles та Albione. Витримка в бочках після бурбону дає складний, насичений і пряний ром, водночас медовий та ароматний.', NULL, NULL, 'Гаяна', NULL),
(290, 'uk', 'DIPLOMATICO RESERVA EXCLUSIVA RUM', 'Символ латинського рому, його виробляють із суміші патоки та соку цукрової тростини та витримують 12 років у бочках з білого дуба. Аромати солодкі та обволікаючі, з переважаючими нотами екзотичних фруктів, меду та карамелі.', NULL, NULL, 'Венесуела', NULL),
(291, 'uk', 'OBAN 14 Y.O.', 'Oban 14 Years Old — класичний драм, що втілює історію винокурні. Аромат багатий і торф’яний, із фруктовими нотами; смак щільний і повний, із прянощами та медом, за якими йде сухий дим. Досить довгий післясмак залишає деревні відтінки й легку солоність.', NULL, NULL, NULL, NULL),
(292, 'uk', 'TALISKER 10 Y.O. SINGLE MALT SCOTCH WHISKY', 'Цей віскі темно-золотого кольору має мінеральний букет із нотами водоростей у розсолі, торф’яного диму й делікатних цитрусів. На піднебінні дарує особливий досвід: повний та інтенсивний смак із відгомонами торфу, диму й перцю.', NULL, NULL, NULL, NULL),
(293, 'uk', 'LAPHROAIG 10 Y.O.', 'Laphroaig 10 Years Old дистилюють однаково вже майже 75 років. Ячмінний солод сушать над торф’яним вогнем; торф походить виключно з Islay і надає Laphroaig особливого смаку. Результат — повнотілий віскі з димним смаком і дивовижною солодкістю.', NULL, NULL, NULL, NULL),
(294, 'uk', 'LAGAVULIN 16 Y.O.', 'Lagavulin 16 Years Old — торф’яний шотландський односолодовий віскі, витриманий щонайменше 16 років у бочках після бурбону, еталон для мільйонів поціновувачів у світі. У ньому ви знайдете весь дикий, неприборканий характер острова Skye.', NULL, NULL, NULL, NULL),
(295, 'uk', 'NIKKA FROM THE BARREL', 'Nikka Whisky From The Barrel — купаж, укорінений у японській традиції, вдале поєднання односолодових і японських зернових віскі з винокурень Yoichi та Miyahikyo. Купаж відпочиває в дубових бочках перед розливом із міцністю 51,4 %, без зазначення віку.', NULL, NULL, NULL, NULL),
(296, 'uk', 'JOHNNIE WALKER GREEN LABEL 15 YEARS OLD', 'Johnnie Walker Green Label поєднує односолодові віскі зі Speyside, Highland, Lowland та Island, витримані щонайменше 15 років. Цей особливий купаж включає Talisker, Linkwood, Cragganmore і Caol Ila, розкриваючи весь характер і глибину шотландських односолодових віскі.', NULL, NULL, NULL, NULL),
(297, 'uk', 'Кава', NULL, NULL, NULL, NULL, NULL),
(298, 'uk', 'Кава без кофеїну', NULL, NULL, NULL, NULL, NULL),
(299, 'uk', 'Кава мак’ято', NULL, NULL, NULL, NULL, NULL),
(300, 'uk', 'Cappuccino', NULL, NULL, NULL, NULL, NULL),
(301, 'uk', 'Солодка кава з женьшенем', NULL, NULL, NULL, NULL, NULL),
(302, 'uk', 'Гірка кава з женьшенем', NULL, NULL, NULL, NULL, NULL),
(303, 'uk', 'Велика солодка кава з женьшенем', NULL, NULL, NULL, NULL, NULL),
(304, 'uk', 'Велика гірка кава з женьшенем', NULL, NULL, NULL, NULL, NULL),
(305, 'uk', 'Latte macchiato', NULL, NULL, NULL, NULL, NULL),
