DO $check$
BEGIN
 IF EXISTS (SELECT 1 FROM stage_menu_item_translations s LEFT JOIN public.menu_item_translations t USING (item_id, language_code) WHERE t.id IS NULL)
 AND NOT EXISTS (
  SELECT 1 FROM information_schema.columns
  WHERE table_schema='public' AND table_name='menu_item_translations' AND column_name='id'
    AND (is_identity='YES' OR column_default IS NOT NULL)
 ) THEN
  RAISE EXCEPTION 'La tabella menu_item_translations richiede nuovi ID ma non ha generazione automatica: nessun dato importato';
 END IF;
END $check$;

UPDATE public.menu_item_translations t SET nome=s.nome, descrizione=s.descrizione, vitigni=s.vitigni, produttore=s.produttore, origine=s.origine, regione=s.regione, updated_at=now() FROM stage_menu_item_translations s WHERE t.item_id=s.item_id AND t.language_code=s.language_code;

INSERT INTO public.menu_item_translations (item_id, language_code, nome, descrizione, vitigni, produttore, origine, regione) SELECT s.item_id, s.language_code, s.nome, s.descrizione, s.vitigni, s.produttore, s.origine, s.regione FROM stage_menu_item_translations s WHERE NOT EXISTS (SELECT 1 FROM public.menu_item_translations t WHERE t.item_id=s.item_id AND t.language_code=s.language_code)
ON CONFLICT (item_id, language_code) DO UPDATE SET nome=EXCLUDED.nome, descrizione=EXCLUDED.descrizione, vitigni=EXCLUDED.vitigni, produttore=EXCLUDED.produttore, origine=EXCLUDED.origine, regione=EXCLUDED.regione, updated_at=now();

COMMIT;
